insert into public.sources (title, url, kind, publisher, published_on) values ('INTERPOL · ¿Qué es INTERPOL? y Comité Ejecutivo', 'https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL', 'web_oficial'::public.source_kind, 'Organización Internacional de Policía Criminal (INTERPOL, web oficial)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-06b-agencias-internacionales', 'Tema 6. Instituciones internacionales (II): INTERPOL, EUROPOL, EUROJUST, FRONTEX, CEPOL, FAO, FMI y OMS') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-06b-agencias-internacionales' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"INTERPOL (Organización Internacional de Policía Criminal)"},{"n":"1.1","title":"Asamblea General, Comité Ejecutivo, Secretaría General y Oficinas Centrales Nacionales"},{"n":"2","title":"Agencias de la Unión Europea en materia de seguridad y justicia"},{"n":"2.1","title":"EUROPOL: cooperación policial (La Haya)"},{"n":"2.2","title":"EUROJUST: cooperación judicial penal (La Haya)"},{"n":"2.3","title":"FRONTEX: Guardia Europea de Fronteras y Costas (Varsovia)"},{"n":"2.4","title":"CEPOL: formación policial (Budapest)"},{"n":"3","title":"Organismos especializados de las Naciones Unidas"},{"n":"3.1","title":"FAO: alimentación y agricultura (Roma)"},{"n":"3.2","title":"FMI: Fondo Monetario Internacional"},{"n":"3.3","title":"OMS: Organización Mundial de la Salud"}]'::jsonb, '["INTERPOL, ¿Qué es INTERPOL? Web de INTERPOL: «La Secretaría General coordina nuestras actividades diarias de lucha contra distintos delitos. Dirigida por el Secretario General, trabajan en ella tanto policías como civiles. Está formada por las oficinas centrales en Lyon, un complejo mundial para la innovación en Singapur y varias oficinas satélites en distintas regiones.»","INTERPOL, Oficinas Centrales Nacionales Web de INTERPOL: «En cada país, una Oficina Central Nacional (OCN) de INTERPOL actúa como punto de contacto para la Secretaría General y otras OCN.»","INTERPOL, Asamblea General Web de INTERPOL: «La Asamblea General es nuestro órgano de gobierno y reúne a todos los países una vez al año para tomar decisiones.»","INTERPOL, Comité Ejecutivo Web de INTERPOL: «Elegido por la Asamblea General, el Comité Ejecutivo está formado por 13 miembros incluyendo el Presidente de la Organización, tres vicepresidentes y nueve vocales.»","Europol Portal de la UE (Europol): «El cometido de la Oficina Europea de Policía (Europol), agencia encargada de velar por el cumplimiento de la ley en la UE, es contribuir a que Europa sea más segura ayudando a las autoridades responsables de la aplicación de la ley en los países miembros de la UE.»","Eurojust Portal de la UE (Eurojust): «La Agencia de la Unión Europea para la Cooperación Judicial Penal (Eurojust) facilita la coordinación judicial y la cooperación entre las autoridades nacionales prestando apoyo práctico a los fiscales en la lucha contra la delincuencia transfronteriza grave y el terrorismo.»","Eurojust, Colegio Portal de la UE (Eurojust): «Miembros: Colegio de Eurojust, con un miembro nacional de cada país»","Frontex Portal de la UE (Frontex): «Función: Frontex, la Agencia Europea de la Guardia de Fronteras y Costas, apoya a los países de la UE y de Schengen en la gestión de las fronteras exteriores de la UE y en la lucha contra la delincuencia transfronteriza.»","Frontex, cuerpo permanente Portal de la UE (Frontex): «Con el cuerpo permanente, el primer servicio uniformado de fuerzas de seguridad de la Unión Europea, Frontex se ha convertido en un brazo operativo de la UE.»","CEPOL Portal de la UE (CEPOL): «La CEPOL, Agencia de la Unión Europea para la Formación Policial, desarrolla, ejecuta y organiza cursos de formación para la policía y otros funcionarios de las fuerzas y cuerpos de seguridad del Estado.»","FAO Web de la FAO: «La FAO es la agencia de las Naciones Unidas que lidera el esfuerzo internacional para poner fin al hambre.»","FAO, Día Mundial de la Alimentación Web de la FAO: «Durante la 20.a reunión de la Conferencia de la FAO se decidió en forma unánime celebrar anualmente el Día Mundial de la Alimentación el 16 de octubre en honor a la fecha de fundación de la FAO.»","FMI, misiones Web del FMI: «El FMI tiene tres misiones críticas: promover la cooperación monetaria internacional, alentar la expansión del comercio internacional y del crecimiento económico, y desalentar políticas que vayan en perjuicio de la prosperidad.»","FMI, fundación Web del FMI: «La idea de crear el FMI se planteó en julio de 1944 en una conferencia de las Naciones Unidas celebrada en Bretton Woods, cuando los representantes de 44 países acordaron establecer un marco de cooperación económica internacional»","OMS Web de la OMS: «Fundada en 1948, la OMS es el organismo de las Naciones Unidas que pone en contacto a naciones, asociados y personas a fin de promover la salud, preservar la seguridad mundial y servir a las poblaciones vulnerables»","OMS, Asamblea Mundial de la Salud Web de la OMS: «La Asamblea Mundial de la Salud es el órgano decisorio de la OMS y a ella asisten delegaciones de todos los Estados Miembros.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"INTERPOL: qué es y para qué sirve","blocks":[{"text":"INTERPOL es la Organización Internacional de Policía Criminal, una organización intergubernamental que, según su web oficial, cuenta con 196 países miembros. Su función es ayudar a las policías de esos países a colaborar entre sí: les facilita el intercambio de información sobre delitos y delincuentes y el acceso a ella, y les presta apoyo técnico y operativo.","refs":[{"ref":"INTERPOL, ¿Qué es INTERPOL?","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Nuestro nombre completo es Organización International de Policía Criminal y somos una organización intergubernamental que cuenta con 196 países miembros. Ayudamos a la policía de estos países a colaborar entre sí para hacer del mundo un lugar más seguro."},{"ref":"INTERPOL, ¿Qué es INTERPOL?","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Para ello, les facilitamos el intercambio y acceso a información sobre delitos y delincuentes. También les ofrecemos apoyo técnico y operativo de diversa índole."}]},{"text":"Por ser una organización internacional, INTERPOL permite que la policía trabaje directamente con sus homólogos incluso entre países que no mantienen relaciones diplomáticas. Todas sus acciones son políticamente neutrales y se realizan dentro de los límites de la legislación de cada país. Su apoyo se centra en cuatro áreas globales que la propia organización considera las más acuciantes: terrorismo, ciberdelincuencia, delincuencia organizada, y delincuencia financiera y corrupción.","refs":[{"ref":"INTERPOL, Plataforma mundial","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Facilitamos a la policía el trabajo directo con sus homólogos, incluso entre países que no mantienen relaciones diplomáticas. Todas nuestras acciones son políticamente neutrales y se ejecutan dentro de los límites de legislaciones existentes en los diferentes países."},{"ref":"INTERPOL, Qué hacemos","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"cuatro áreas globales que consideramos las más acuciantes actualmente: terrorismo, ciberdelincuencia, delincuencia organizada. y delincuencia financiera y corrupción."}]}]},{"n":"2","title":"INTERPOL: Asamblea General, Secretaría General y Oficinas Centrales Nacionales","blocks":[{"text":"La Asamblea General es el órgano de gobierno de INTERPOL: reúne a todos los países miembros una vez al año para tomar decisiones. La Secretaría General coordina las actividades diarias contra la delincuencia; la dirige el Secretario General y en ella trabajan policías y civiles. Está formada por las oficinas centrales en Lyon, un complejo mundial para la innovación en Singapur y varias oficinas satélite regionales. Ojo en el examen: la sede central de la Secretaría General está en Lyon, no en Singapur.","refs":[{"ref":"INTERPOL, Asamblea General","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"La Asamblea General es nuestro órgano de gobierno y reúne a todos los países una vez al año para tomar decisiones."},{"ref":"INTERPOL, Secretaría General","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"La Secretaría General coordina nuestras actividades diarias de lucha contra distintos delitos. Dirigida por el Secretario General, trabajan en ella tanto policías como civiles. Está formada por las oficinas centrales en Lyon, un complejo mundial para la innovación en Singapur y varias oficinas satélites en distintas regiones."}]},{"text":"En cada país existe una Oficina Central Nacional (OCN) de INTERPOL, que es el punto de contacto con la Secretaría General y con las OCN de los demás países. Las OCN las dirigen funcionarios de la policía nacional y normalmente forman parte del ministerio responsable de las actividades policiales. La Secretaría General gestiona bases de datos policiales (desde nombres y huellas dactilares hasta pasaportes robados) accesibles en tiempo real.","refs":[{"ref":"INTERPOL, Oficinas Centrales Nacionales","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"En cada país, una Oficina Central Nacional (OCN) de INTERPOL actúa como punto de contacto para la Secretaría General y otras OCN. Las OCN están dirigidas por funcionarios de la policía nacional y, normalmente, forman parte del ministerio del gobierno responsable de las actividades policiales."},{"ref":"INTERPOL, Qué hacemos","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Gestionamos bases de datos policiales con información sobre delitos y delincuentes (desde nombres y huellas dactilares a pasaportes robados), accesibles para los países en tiempo real."}]}]},{"n":"3","title":"INTERPOL: Comité Ejecutivo y sistema I-24/7","blocks":[{"text":"El Comité Ejecutivo, elegido por la Asamblea General, tiene 13 miembros: el Presidente de la Organización, tres vicepresidentes y nueve vocales, de países distintos y con distribución geográfica equilibrada. Se reúne tres veces al año y supervisa la ejecución de las decisiones de la Asamblea General y la administración y el trabajo de la Secretaría General; además prepara el orden del día de la Asamblea, le somete programas y proyectos y vigila la gestión del Secretario General. El presidente se elige por cuatro años y los vicepresidentes por tres, sin reelección para el periodo inmediatamente posterior en el mismo cargo ni como vocales.","refs":[{"ref":"INTERPOL, Comité Ejecutivo","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Elegido por la Asamblea General, el Comité Ejecutivo está formado por 13 miembros incluyendo el Presidente de la Organización, tres vicepresidentes y nueve vocales."},{"ref":"INTERPOL, Comité Ejecutivo","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"El Comité Ejecutivo es el órgano regidor encargado de supervisar la ejecución de las decisiones de la Asamblea General y la administración y el trabajo de la Secretaría General. El Comité Ejecutivo se reúne tres veces al año."},{"ref":"INTERPOL, Comité Ejecutivo","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Se elige al presidente por un periodo de cuatro años, y a los vicepresidentes por tres años. No podrán ser reelegidos para el periodo inmediatamente posterior en el mismo cargo o como vocales del Comité Ejecutivo."}]},{"text":"Todos los países miembros están conectados mediante un sistema de comunicación protegido llamado I-24/7. Con él los países se comunican entre sí y con la Secretaría General, y acceden en tiempo real a las bases de datos y servicios de INTERPOL, tanto desde localizaciones centrales como remotas.","refs":[{"ref":"INTERPOL, Conectando a la policía","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Conectamos a todos los países miembros a través de un sistema de comunicación denominado I-24/7. Los países utilizan este sistema protegido para ponerse en contacto entre sí y con la Secretaría General."}]}]},{"n":"4","title":"EUROPOL: Agencia de la Unión Europea para la Cooperación Policial","blocks":[{"text":"Europol (Oficina Europea de Policía) es la agencia de la UE encargada de velar por el cumplimiento de la ley; ayuda a las autoridades policiales y judiciales nacionales a combatir la delincuencia internacional y el terrorismo. Se creó en 1999, tiene su sede en La Haya (Países Bajos) y una plantilla de más de 900 personas. Su cometido es contribuir a una Europa más segura ayudando a las autoridades de aplicación de la ley de los Estados miembros.","refs":[{"ref":"Europol, visión general","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"Función: Europol ayuda a las autoridades policiales y judiciales nacionales a combatir la delincuencia internacional y el terrorismo. Año de creación: 1999 Plantilla: 900+ Sede: La Haya (Países Bajos)"},{"ref":"Europol","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"El cometido de la Oficina Europea de Policía (Europol), agencia encargada de velar por el cumplimiento de la ley en la UE, es contribuir a que Europa sea más segura ayudando a las autoridades responsables de la aplicación de la ley en los países miembros de la UE."}]},{"text":"Europol ofrece tres servicios principales: apoyo sobre el terreno a las operaciones de las fuerzas y cuerpos de seguridad, una central de intercambio de información sobre actividades delictivas y un centro de conocimientos especializados en aplicación de la ley. Cuenta con unos 100 analistas y elabora periódicamente análisis a largo plazo sobre delincuencia y terrorismo. Las fuerzas y cuerpos de seguridad reciben su apoyo operativo las 24 horas, todos los días.","refs":[{"ref":"Europol, servicios","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"apoyo sobre el terreno a las operaciones de las fuerzas y cuerpos de seguridad central de intercambio de información sobre actividades delictivas centro de conocimientos especializados en materia de aplicación de la ley."},{"ref":"Europol, analistas","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"Europol da empleo a unos 100 analistas que se encuentran entre los mejor formados de Europa."},{"ref":"Europol, análisis","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"Europol elabora periódicamente análisis a largo plazo sobre delincuencia y terrorismo."},{"ref":"Europol, beneficiarios","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"Los cuerpos y fuerzas de seguridad, que reciben apoyo operativo las 24 horas del día todos los días de la semana."}]}]},{"n":"5","title":"EUROJUST: Agencia de la Unión Europea para la Cooperación Judicial Penal","blocks":[{"text":"Eurojust es la Agencia de la Unión Europea para la Cooperación Judicial Penal. Facilita la coordinación judicial y la cooperación entre autoridades nacionales dando apoyo práctico a los fiscales frente a la delincuencia transfronteriza grave y el terrorismo. Se creó en 2002 y, como Europol, tiene su sede en La Haya (Países Bajos). Sus miembros forman el Colegio de Eurojust, con un miembro nacional de cada país.","refs":[{"ref":"Eurojust","law":"Portal de la UE (Eurojust)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es","quote":"La Agencia de la Unión Europea para la Cooperación Judicial Penal (Eurojust) facilita la coordinación judicial y la cooperación entre las autoridades nacionales prestando apoyo práctico a los fiscales en la lucha contra la delincuencia transfronteriza grave y el terrorismo."},{"ref":"Eurojust, generalidades","law":"Portal de la UE (Eurojust)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es","quote":"Miembros: Colegio de Eurojust, con un miembro nacional de cada país Año de creación: 2002 Plantilla: 270 personas Sede: La Haya (Países Bajos)"}]},{"text":"Eurojust coordina investigaciones y acciones penales que afecten al menos a dos países, ayuda a resolver conflictos de jurisdicción y facilita la aplicación de instrumentos de la UE como la orden de detención europea, la orden europea de investigación y las resoluciones de embargo y decomiso. Para ello celebra reuniones de coordinación, ayuda a crear y financiar equipos conjuntos de investigación (ECI) y organiza centros de coordinación en tiempo real. También alberga las secretarías de la Red Judicial Europea (RJE), de la Red de Expertos Nacionales de ECI y de la Red Europea de Cooperación contra el Genocidio.","refs":[{"ref":"Eurojust, servicios","law":"Portal de la UE (Eurojust)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es","quote":"coordina las investigaciones y las acciones penales que afecten a un mínimo de dos países; ayuda a resolver conflictos juridiccionales; facilita la elaboración y aplicación de instrumentos jurídicos de la UE, como las órdenes de detención europeas, las órdenes europeas de investigación y las resoluciones o certificados de embargo y decomiso."},{"ref":"Eurojust, secretarías de redes","law":"Portal de la UE (Eurojust)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es","quote":"También alberga las secretarías de la Red Judicial Europea (RJE), la Red de Expertos Nacionales de Equipos Conjuntos de Investigación (Red ECI) y la Red de Investigación y Enjuiciamiento del Genocidio, los Crímenes contra la Humanidad y los Crímenes de Guerra (Red Europea de Cooperación contra el Genocidio)."}]}]},{"n":"6","title":"FRONTEX: Agencia Europea de la Guardia de Fronteras y Costas","blocks":[{"text":"Frontex, la Agencia Europea de la Guardia de Fronteras y Costas, apoya a los países de la UE y de Schengen en la gestión de las fronteras exteriores de la Unión y en la lucha contra la delincuencia transfronteriza. Se creó en 2004 y tiene su sede en Varsovia (Polonia). Es un centro de excelencia del control fronterizo que comparte inteligencia con los países de la UE y con países vecinos afectados por las tendencias migratorias; también ayuda en los procedimientos de retorno y en la vigilancia aérea.","refs":[{"ref":"Frontex","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Función: Frontex, la Agencia Europea de la Guardia de Fronteras y Costas, apoya a los países de la UE y de Schengen en la gestión de las fronteras exteriores de la UE y en la lucha contra la delincuencia transfronteriza."},{"ref":"Frontex, sede","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Año de creación: 2004 Sede: Varsovia (Polonia)"},{"ref":"Frontex, funciones","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"la vigilancia aérea y la recogida de información, a fin de ayudar en los procedimientos de retorno"}]},{"text":"Con su cuerpo permanente, que es el primer servicio uniformado de fuerzas de seguridad de la Unión Europea, Frontex se ha convertido en un brazo operativo de la UE, y es la agencia de mayor tamaño y crecimiento más rápido. Junto con otras instituciones de la UE y 30 países europeos está aplicando el SEIAV, un sistema de autorización de viajes para los nacionales exentos de visado.","refs":[{"ref":"Frontex, cuerpo permanente","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Con el cuerpo permanente, el primer servicio uniformado de fuerzas de seguridad de la Unión Europea, Frontex se ha convertido en un brazo operativo de la UE."},{"ref":"Frontex, SEIAV","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Frontex, junto con otras instituciones de la UE y 30 países europeos, está aplicando el SEIAV, un sistema de autorización de viajes para los nacionales exentos de la obligación de visado"},{"ref":"Frontex","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Es la agencia de la UE de mayor tamaño y con un crecimiento más rápido."}]}]},{"n":"7","title":"CEPOL: Agencia de la Unión Europea para la Formación Policial","blocks":[{"text":"La CEPOL es la Agencia de la Unión Europea para la Formación Policial: desarrolla, ejecuta y organiza cursos de formación para la policía y otros funcionarios de las fuerzas y cuerpos de seguridad. Se creó en 2005 y su sede está en Budapest (Hungría). Imparte formación, mejora la seguridad de la UE mediante la puesta en común de conocimientos y crea redes de formación; su cartera incluye cursos residenciales, aprendizaje en línea, programas de intercambio, planes de estudios comunes y ciencia e investigación.","refs":[{"ref":"CEPOL","law":"Portal de la UE (CEPOL)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-law-enforcement-training-cepol_es","quote":"La CEPOL, Agencia de la Unión Europea para la Formación Policial, desarrolla, ejecuta y organiza cursos de formación para la policía y otros funcionarios de las fuerzas y cuerpos de seguridad del Estado."},{"ref":"CEPOL, sede","law":"Portal de la UE (CEPOL)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-law-enforcement-training-cepol_es","quote":"Año de creación: 2005 Plantilla: 110 Sede: Budapest (Hungría)"},{"ref":"CEPOL, cartera","law":"Portal de la UE (CEPOL)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-law-enforcement-training-cepol_es","quote":"cursos residenciales aprendizaje en línea programas de intercambio planes de estudios comunes ciencia e investigación"}]}]},{"n":"8","title":"FAO: Organización de las Naciones Unidas para la Alimentación y la Agricultura","blocks":[{"text":"La FAO es la agencia de las Naciones Unidas que lidera el esfuerzo internacional para poner fin al hambre; su objetivo es la seguridad alimentaria para todos. Tiene 194 miembros (193 países y la Unión Europea) y trabaja en más de 130 países. Nació como organismo especializado de la ONU en la ciudad de Quebec (Canadá), con Washington D.C. como sede temporal; en 1949 los Estados Miembros decidieron trasladar sus oficinas a Roma, adonde se mudaron en 1951.","refs":[{"ref":"FAO","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"La FAO es la agencia de las Naciones Unidas que lidera el esfuerzo internacional para poner fin al hambre."},{"ref":"FAO, miembros","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"Con 194 miembros - 193 países y la Unión Europea, la FAO trabaja en más de 130 países en todo el mundo."},{"ref":"FAO, nacimiento","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"En la ciudad de Quebec, Canadá, el primer período de sesiones de las Naciones Unidas establece a la Organización para la Alimentación y la Agricultura (FAO) como un organismo especializado de la ONU. Washington D.C. es designada sede temporal de la FAO."},{"ref":"FAO, sede","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"Tras el quinto período de sesiones de la Conferencia General llevada a cabo en 1949, en la cual los Estados Miembros decidieron trasladar las oficinas de la FAO a Roma, dos barcos, Saturnia y Vulcania, zarparon desde Washington a inicios de la primavera de 1951"}]},{"text":"El Día Mundial de la Alimentación se celebra cada 16 de octubre, en honor a la fecha de fundación de la FAO, por decisión unánime de la 20.ª reunión de su Conferencia. En 1961 la FAO y la Asamblea General de la ONU dieron origen al Programa Mundial de Alimentos. La FAO también impulsa el Codex Alimentarius («legislación alimentaria»), que coordina normas alimentarias para proteger la salud de los consumidores.","refs":[{"ref":"FAO, Día Mundial de la Alimentación","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"Durante la 20.a reunión de la Conferencia de la FAO se decidió en forma unánime celebrar anualmente el Día Mundial de la Alimentación el 16 de octubre en honor a la fecha de fundación de la FAO."},{"ref":"FAO, Programa Mundial de Alimentos","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"En diciembre de 1961, la FAO y la Asamblea General de las Naciones Unidas adoptaron resoluciones paralelas que dieron origen al Programa Mundial de Alimentos"},{"ref":"FAO, Codex Alimentarius","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"Codex Alimentarius proviene del latín y significa \"legislación alimentaria\""}]}]},{"n":"9","title":"FMI: Fondo Monetario Internacional","blocks":[{"text":"El FMI busca un crecimiento y una prosperidad sostenibles para sus 191 países miembros. Tiene tres misiones: promover la cooperación monetaria internacional, alentar la expansión del comercio internacional y del crecimiento económico, y desalentar las políticas que perjudiquen la prosperidad. Actúa mediante la supervisión, la asistencia financiera (préstamos a países con problemas de balanza de pagos) y el fortalecimiento de capacidades, y emite un activo de reserva llamado Derechos Especiales de Giro (DEG).","refs":[{"ref":"FMI","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"El objetivo del Fondo Monetario Internacional (FMI) es lograr un crecimiento y una prosperidad sostenibles para cada uno de sus 191 países miembros."},{"ref":"FMI, misiones","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"El FMI tiene tres misiones críticas: promover la cooperación monetaria internacional, alentar la expansión del comercio internacional y del crecimiento económico, y desalentar políticas que vayan en perjuicio de la prosperidad."},{"ref":"FMI, DEG","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"El FMI emite un activo de reserva internacional conocido como Derechos Especiales de Giro"}]},{"text":"La instancia máxima del FMI es la Junta de Gobernadores, con un gobernador y un suplente por país miembro, que se reúne una vez al año en las Reuniones Anuales del FMI y el Banco Mundial. Las operaciones diarias las supervisa el Directorio Ejecutivo, de 25 miembros, presidido por el Director Gerente. Su principal fuente de financiación son las cuotas de los miembros. La idea de crearlo surgió en julio de 1944 en la conferencia de Bretton Woods, con representantes de 44 países, para evitar devaluaciones como las de la Gran Depresión.","refs":[{"ref":"FMI, órganos de gobierno","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"La instancia máxima en la estructura organizativa es la Junta de Gobernadores, que está integrada por un gobernador y un gobernador suplente por cada país miembro"},{"ref":"FMI, Directorio Ejecutivo","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"Las operaciones cotidianas del FMI son supervisadas por el Directorio Ejecutivo, que tiene 25 miembros y representa a todos los países miembros"},{"ref":"FMI, Directora Gerente","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"La Directora Gerente es la jefa del personal técnico del FMI, preside el Directorio Ejecutivo y cuenta con la asistencia de cuatro subdirectores gerentes."},{"ref":"FMI, cuotas","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"La principal fuente de financiamiento del FMI son las cuotas de los países miembros"},{"ref":"FMI, fundación","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"La idea de crear el FMI se planteó en julio de 1944 en una conferencia de las Naciones Unidas celebrada en Bretton Woods, cuando los representantes de 44 países acordaron establecer un marco de cooperación económica internacional destinado a evitar que se repitieran las devaluaciones cambiarias monetarias que contribuyeron a provocar la Gran Depresión de los años treinta."}]}]},{"n":"10","title":"OMS: Organización Mundial de la Salud","blocks":[{"text":"La OMS, fundada en 1948, es el organismo de las Naciones Unidas que pone en contacto a naciones, asociados y personas para promover la salud, preservar la seguridad mundial y servir a las poblaciones vulnerables. Trabaja con 194 Estados Miembros de seis regiones, lidera la cobertura sanitaria universal y coordina la respuesta mundial a las emergencias sanitarias. Su Constitución, tratado constitutivo, se adoptó en 1946 y está en vigor desde 1948; afirma que la salud es un derecho humano fundamental. El órgano decisorio es la Asamblea Mundial de la Salud, con delegaciones de todos los Estados Miembros.","refs":[{"ref":"OMS","law":"Web de la OMS","url":"https://www.who.int/es/about","quote":"Fundada en 1948, la OMS es el organismo de las Naciones Unidas que pone en contacto a naciones, asociados y personas a fin de promover la salud, preservar la seguridad mundial y servir a las poblaciones vulnerables"},{"ref":"OMS, Estados Miembros","law":"Web de la OMS","url":"https://www.who.int/es/about","quote":"Junto a los 194 Estados Miembros de las seis regiones"},{"ref":"OMS, Constitución","law":"Web de la OMS","url":"https://www.who.int/es/about","quote":"La Constitución de la OMS, que fue adoptada en 1946 y está en vigor desde 1948, es el tratado constitutivo de la Organización. En ella se establecen el mandato y el sistema de gobernanza de la Organización y se afirma que la salud es un derecho humano fundamental"},{"ref":"OMS, Asamblea Mundial de la Salud","law":"Web de la OMS","url":"https://www.who.int/es/about","quote":"La Asamblea Mundial de la Salud es el órgano decisorio de la OMS y a ella asisten delegaciones de todos los Estados Miembros."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"INTERPOL: Asamblea General una vez al año (órgano de gobierno); Secretaría General con oficinas centrales en Lyon.","refs":[{"ref":"INTERPOL, Secretaría General","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"Está formada por las oficinas centrales en Lyon"}]},{"text":"Comité Ejecutivo de INTERPOL: 13 miembros (Presidente, tres vicepresidentes y nueve vocales); red I-24/7; una OCN en cada país.","refs":[{"ref":"INTERPOL, Comité Ejecutivo","law":"Web de INTERPOL","url":"https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL","quote":"el Comité Ejecutivo está formado por 13 miembros incluyendo el Presidente de la Organización, tres vicepresidentes y nueve vocales."}]},{"text":"Europol: creada en 1999, sede en La Haya.","refs":[{"ref":"Europol, sede","law":"Portal de la UE (Europol)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es","quote":"Sede: La Haya (Países Bajos)"}]},{"text":"Eurojust: creada en 2002, sede en La Haya, Colegio con un miembro nacional por país; alberga la secretaría de la RJE.","refs":[{"ref":"Eurojust, Colegio","law":"Portal de la UE (Eurojust)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es","quote":"Miembros: Colegio de Eurojust, con un miembro nacional de cada país"}]},{"text":"Frontex: Varsovia, creada en 2004; su cuerpo permanente es el primer servicio uniformado de la UE; aplica el SEIAV.","refs":[{"ref":"Frontex, sede","law":"Portal de la UE (Frontex)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es","quote":"Sede: Varsovia (Polonia)"}]},{"text":"CEPOL: formación policial, Budapest, creada en 2005.","refs":[{"ref":"CEPOL, sede","law":"Portal de la UE (CEPOL)","url":"https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-law-enforcement-training-cepol_es","quote":"Sede: Budapest (Hungría)"}]},{"text":"FAO: Roma (traslado decidido en 1949); Día Mundial de la Alimentación, 16 de octubre.","refs":[{"ref":"FAO, Día Mundial de la Alimentación","law":"Web de la FAO","url":"https://www.fao.org/about/about-fao/es/","quote":"celebrar anualmente el Día Mundial de la Alimentación el 16 de octubre"}]},{"text":"FMI: Bretton Woods, julio de 1944, 44 países; máxima instancia, la Junta de Gobernadores.","refs":[{"ref":"FMI, fundación","law":"Web del FMI","url":"https://www.imf.org/es/about/factsheets/imf-at-a-glance","quote":"La idea de crear el FMI se planteó en julio de 1944 en una conferencia de las Naciones Unidas celebrada en Bretton Woods"}]},{"text":"OMS: Constitución adoptada en 1946 y en vigor desde 1948; órgano decisorio, la Asamblea Mundial de la Salud.","refs":[{"ref":"OMS, Constitución","law":"Web de la OMS","url":"https://www.who.int/es/about","quote":"La Constitución de la OMS, que fue adoptada en 1946 y está en vigor desde 1948"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL'), 'https://www.interpol.int/es/Quienes-somos/Que-es-INTERPOL', null, null, null, 'Otras normas citadas: Portal de la UE (Europol) (https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/europol_es), Portal de la UE (Eurojust) (https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/eurojust_es), Portal de la UE (Frontex) (https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/frontex_es), Portal de la UE (CEPOL) (https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-union-agency-law-enforcement-training-cepol_es), Web de la FAO (https://www.fao.org/about/about-fao/es/), Web del FMI (https://www.imf.org/es/about/factsheets/imf-at-a-glance), Web de la OMS (https://www.who.int/es/about)'
  from public.topics t where t.slug = 'gc-06b-agencias-internacionales'
