   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 24 de julio de 1889, Código Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-07-derecho-civil', 'Tema 7. Derecho civil: título preliminar y libro I del Código Civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-07-derecho-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Título preliminar: fuentes del derecho y aplicación de las normas (arts. 1-5 CC)"},{"n":"1.1","title":"Eficacia general de las normas; derecho internacional privado y vecindad civil (arts. 6-16 CC)"},{"n":"2","title":"De los españoles y extranjeros: nacionalidad (arts. 17-28 CC)"},{"n":"3","title":"Nacimiento y extinción de la personalidad civil; personas jurídicas (arts. 29-39 CC)"},{"n":"4","title":"Del domicilio (arts. 40-41 CC)"},{"n":"5","title":"Del matrimonio: requisitos, efectos, nulidad, separación y divorcio (arts. 42-107 CC)"},{"n":"6","title":"Filiación y alimentos entre parientes (arts. 108-153 CC)"},{"n":"7","title":"Relaciones paterno-filiales y adopción (arts. 154-180 CC)"},{"n":"8","title":"Ausencia y declaración de fallecimiento (arts. 181-198 CC)"},{"n":"9","title":"Tutela y guarda de los menores (arts. 199-238 CC)"},{"n":"10","title":"Mayor edad y emancipación (arts. 239-248 CC)"},{"n":"11","title":"Medidas de apoyo a las personas con discapacidad y disposiciones comunes (arts. 249-300 CC)"}]'::jsonb, '["Art. 1.1 Código Civil: «Las fuentes del ordenamiento jurídico español son la ley, la costumbre y los principios generales del derecho.»","Art. 2.1 Código Civil: «Las leyes entrarán en vigor a los veinte días de su completa publicación en el «Boletín Oficial del Estado», si en ellas no se dispone otra cosa.»","Art. 6.1 Código Civil: «La ignorancia de las leyes no excusa de su cumplimiento. El error de derecho producirá únicamente aquellos efectos que las leyes determinen.»","Art. 14.1 Código Civil: «La sujeción al derecho civil común o al especial o foral se determina por la vecindad civil.»","Art. 17.1 Código Civil: «Son españoles de origen: a) Los nacidos de padre o madre españoles. b) Los nacidos en España de padres extranjeros si, al menos, uno de ellos hubiera nacido también en España. Se exceptúan los hijos de funcionario diplomático o consular acreditado en España.»","Art. 22.1 Código Civil: «Para la concesión de la nacionalidad por residencia se requiere que ésta haya durado diez años. Serán suficientes cinco años para los que hayan obtenido la condición de refugiado y dos años cuando se trate de nacionales de origen de países iberoamericanos, Andorra, Filipinas, Guinea Ecuatorial o Portugal o de sefardíes.»","Art. 29-30 Código Civil: «El nacimiento determina la personalidad; pero el concebido se tiene por nacido para todos los efectos que le sean favorables, siempre que nazca con las condiciones que expresa el artículo siguiente. […] La personalidad se adquiere en el momento del nacimiento con vida, una vez producido el entero desprendimiento del seno materno.»","Art. 40 Código Civil: «Para el ejercicio de los derechos y el cumplimiento de las obligaciones civiles, el domicilio de las personas naturales es el lugar de su residencia habitual, y, en su caso, el que determine la Ley de Enjuiciamiento Civil.»","Art. 44-45 Código Civil: «Toda persona tiene derecho a contraer matrimonio conforme a las disposiciones de este Código. El matrimonio tendrá los mismos requisitos y efectos cuando ambos contrayentes sean del mismo o de diferente sexo. […] No hay matrimonio sin consentimiento matrimonial.»","Art. 85 Código Civil: «El matrimonio se disuelve, sea cual fuere la forma y el tiempo de su celebración, por la muerte o la declaración de fallecimiento de uno de los cónyuges y por el divorcio.»","Art. 108 Código Civil: «La filiación puede tener lugar por naturaleza y por adopción. La filiación por naturaleza puede ser matrimonial y no matrimonial. Es matrimonial cuando los progenitores están casados entre sí.»","Art. 154 Código Civil: «Los hijos e hijas no emancipados están bajo la patria potestad de los progenitores.»","Art. 183 Código Civil: «Se considerará en situación de ausencia legal al desaparecido de su domicilio o de su última residencia: Primero. Pasado un año desde las últimas noticias o a falta de éstas desde su desaparición, si no hubiese dejado apoderado con facultades de administración de todos sus bienes. Segundo. Pasados tres años, si hubiese dejado encomendada por apoderamiento la administración de todos sus bienes.»","Art. 199 Código Civil: «Quedan sujetos a tutela: 1.º Los menores no emancipados en situación de desamparo. 2.º Los menores no emancipados no sujetos a patria potestad.»","Art. 239-240 Código Civil: «La emancipación tiene lugar: 1.º Por la mayor edad. 2.º Por concesión de los que ejerzan la patria potestad. 3.º Por concesión judicial. […] La mayor edad empieza a los dieciocho años cumplidos.»","Art. 250 Código Civil: «Las medidas de apoyo para el ejercicio de la capacidad jurídica de las personas que lo precisen son, además de las de naturaleza voluntaria, la guarda de hecho, la curatela y el defensor judicial.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Título preliminar: fuentes del derecho y aplicación de las normas (arts. 1-5 CC)","blocks":[{"text":"El Código Civil abre con el sistema de fuentes. Las fuentes del ordenamiento jurídico español son tres y por este orden: la ley, la costumbre y los principios generales del derecho (art. 1.1 CC). Carecen de validez las disposiciones que contradigan otra de rango superior (art. 1.2). La costumbre es fuente subsidiaria: solo rige en defecto de ley aplicable y con dos condiciones, no ser contraria a la moral o al orden público y resultar probada (art. 1.3). Los principios generales se aplican en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento (art. 1.4).","refs":[{"ref":"Art. 1.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las fuentes del ordenamiento jurídico español son la ley, la costumbre y los principios generales del derecho."},{"ref":"Art. 1.3 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La costumbre sólo regirá en defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público, y que resulte probada."},{"ref":"Art. 1.4 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los principios generales del derecho se aplicarán en defecto de ley o costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico."}]},{"text":"Los tratados internacionales no son de aplicación directa hasta que forman parte del ordenamiento interno mediante su publicación íntegra en el BOE (art. 1.5). La jurisprudencia no es fuente en sentido estricto: «complementa» el ordenamiento con la doctrina que, de modo reiterado, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales (art. 1.6).","refs":[{"ref":"Art. 1.6 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de modo reiterado, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales del derecho."}]},{"text":"Salvo que la propia ley disponga otra cosa, las leyes entran en vigor a los veinte días de su completa publicación en el BOE (art. 2.1); este periodo se conoce como vacatio legis. Las leyes solo se derogan por otras posteriores y la simple derogación de una ley no hace recobrar vigencia a las que esta hubiera derogado (art. 2.2). Como regla, las leyes no tienen efecto retroactivo si no disponen lo contrario (art. 2.3).","refs":[{"ref":"Art. 2.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las leyes entrarán en vigor a los veinte días de su completa publicación en el «Boletín Oficial del Estado», si en ellas no se dispone otra cosa."},{"ref":"Art. 2.2 y 2.3 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las leyes sólo se derogan por otras posteriores. […] Por la simple derogación de una ley no recobran vigencia las que ésta hubiere derogado. 3. Las leyes no tendrán efecto retroactivo, si no dispusieren lo contrario."}]},{"text":"Las normas se interpretan según el sentido propio de sus palabras, en relación con el contexto, los antecedentes históricos y legislativos y la realidad social del tiempo en que se aplican, atendiendo sobre todo a su espíritu y finalidad (art. 3.1). La equidad se pondera en la aplicación, pero una resolución solo puede descansar exclusivamente en ella cuando la ley lo permita (art. 3.2). Cabe la analogía cuando hay identidad de razón (art. 4.1), salvo en las leyes penales, las excepcionales y las de ámbito temporal, que no se aplican a supuestos ni momentos distintos de los previstos (art. 4.2). El Código es supletorio en las materias regidas por otras leyes (art. 4.3).","refs":[{"ref":"Art. 3.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las normas se interpretarán según el sentido propio de sus palabras, en relación con el contexto, los antecedentes históricos y legislativos, y la realidad social del tiempo en que han de ser aplicadas, atendiendo fundamentalmente al espíritu y finalidad de aquellas."},{"ref":"Art. 4.2 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las leyes penales, las excepcionales y las de ámbito temporal no se aplicarán a supuestos ni en momentos distintos de los comprendidos expresamente en ellas."}]},{"text":"Cómputo de plazos (art. 5 CC): en los plazos por días, el día inicial queda excluido y se empieza a contar al día siguiente; los plazos por meses o años se computan de fecha a fecha y, si en el mes del vencimiento no hay día equivalente, el plazo expira el último del mes. En el cómputo civil no se excluyen los días inhábiles (art. 5.2).","refs":[{"ref":"Art. 5.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"quedará éste excluido del cómputo, el cual deberá empezar en el día siguiente; y si los plazos estuviesen fijados por meses o años, se computarán de fecha a fecha."},{"ref":"Art. 5.2 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"En el cómputo civil de los plazos no se excluyen los días inhábiles."}]}]},{"n":"2","title":"Eficacia general de las normas; derecho internacional privado y vecindad civil (arts. 6-16 CC)","blocks":[{"text":"La ignorancia de las leyes no excusa de su cumplimiento (art. 6.1). La renuncia a los derechos solo es válida si no contraría el interés o el orden público ni perjudica a terceros (art. 6.2); los actos contrarios a normas imperativas y prohibitivas son nulos de pleno derecho (art. 6.3), y los realizados en fraude de ley no impiden aplicar la norma que se quiso eludir (art. 6.4). Los derechos se ejercitan conforme a la buena fe y la ley no ampara el abuso del derecho (art. 7).","refs":[{"ref":"Art. 6.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La ignorancia de las leyes no excusa de su cumplimiento. El error de derecho producirá únicamente aquellos efectos que las leyes determinen."},{"ref":"Art. 7 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los derechos deberán ejercitarse conforme a las exigencias de la buena fe. 2. La Ley no ampara el abuso del derecho o el ejercicio antisocial del mismo."}]},{"text":"En derecho internacional privado, la ley personal de las personas físicas es la de su nacionalidad y rige la capacidad, el estado civil, los derechos y deberes de familia y la sucesión (art. 9.1); para apátridas o nacionalidad indeterminada se aplica la ley de la residencia habitual (art. 9.10).","refs":[{"ref":"Art. 9.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La ley personal correspondiente a las personas físicas es la determinada por su nacionalidad. Dicha ley regirá la capacidad y el estado civil, los derechos y deberes de familia y la sucesión por causa de muerte."}]},{"text":"La sujeción al derecho civil común o al especial o foral depende de la vecindad civil (art. 14.1). El matrimonio no altera la vecindad, aunque el cónyuge no separado puede optar por la del otro (art. 14.4). La vecindad se adquiere por residencia continuada de dos años con declaración de voluntad, o de diez años sin declaración en contrario; ambas declaraciones constan en el Registro Civil (art. 14.5). En caso de duda prevalece la del lugar de nacimiento (art. 14.6).","refs":[{"ref":"Art. 14.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La sujeción al derecho civil común o al especial o foral se determina por la vecindad civil."},{"ref":"Art. 14.5 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La vecindad civil se adquiere: 1.° Por residencia continuada durante dos años, siempre que el interesado manifieste ser esa su voluntad. 2.° Por residencia continuada de diez años, sin declaración en contrario durante este plazo."},{"ref":"Art. 14.6 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"En caso de duda prevalecerá la vecindad civil que corresponda al lugar de nacimiento."}]}]},{"n":"3","title":"De los españoles y extranjeros: la nacionalidad (arts. 17-28 CC)","blocks":[{"text":"Son españoles de origen (art. 17.1): los nacidos de padre o madre españoles; los nacidos en España de padres extranjeros si al menos uno de ellos nació también en España, salvo los hijos de diplomáticos o cónsules acreditados en España; los nacidos en España de padres apátridas o cuya legislación no atribuya nacionalidad al hijo; y los nacidos en España de filiación no determinada.","refs":[{"ref":"Art. 17.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"a) Los nacidos de padre o madre españoles. b) Los nacidos en España de padres extranjeros si, al menos, uno de ellos hubiera nacido también en España. Se exceptúan los hijos de funcionario diplomático o consular acreditado en España."}]},{"text":"La nacionalidad también se adquiere por opción (art. 20), por carta de naturaleza, otorgada discrecionalmente por Real Decreto cuando concurren circunstancias excepcionales, y por residencia, concedida por el Ministro de Justicia (art. 21). La residencia exigida es de diez años como regla; cinco para refugiados; dos para nacionales de origen de países iberoamericanos, Andorra, Filipinas, Guinea Ecuatorial, Portugal o sefardíes (art. 22.1); y un año en casos como el nacido en España o el casado con español desde hace un año sin separación (art. 22.2). Siempre ha de ser legal, continuada e inmediatamente anterior a la petición (art. 22.3).","refs":[{"ref":"Art. 21.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La nacionalidad española se adquiere por carta de naturaleza, otorgada discrecionalmente mediante Real Decreto, cuando en el interesado concurran circunstancias excepcionales."},{"ref":"Art. 22.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Para la concesión de la nacionalidad por residencia se requiere que ésta haya durado diez años. Serán suficientes cinco años para los que hayan obtenido la condición de refugiado y dos años cuando se trate de nacionales de origen de países iberoamericanos, Andorra, Filipinas, Guinea Ecuatorial o Portugal o de sefardíes."},{"ref":"Art. 22.3 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"En todos los casos, la residencia habrá de ser legal, continuada e inmediatamente anterior a la petición."}]},{"text":"Los españoles que no lo son de origen pierden la nacionalidad si durante tres años usan exclusivamente la nacionalidad a la que renunciaron, o si entran voluntariamente al servicio de las armas o ejercen cargo político en un Estado extranjero contra la prohibición expresa del Gobierno (art. 25.1). La sentencia firme que declare falsedad, ocultación o fraude en la adquisición produce su nulidad; la acción la ejercita el Ministerio Fiscal, de oficio o por denuncia, en el plazo de quince años (art. 25.2).","refs":[{"ref":"Art. 25.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"a) Cuando durante un período de tres años utilicen exclusivamente la nacionalidad a la que hubieran declarado renunciar al adquirir la nacionalidad española."},{"ref":"Art. 25.2 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La acción de nulidad deberá ejercitarse por el Ministerio Fiscal de oficio o en virtud de denuncia, dentro del plazo de quince años."}]}]},{"n":"4","title":"Nacimiento y extinción de la personalidad civil; personas jurídicas (arts. 29-39 CC)","blocks":[{"text":"El nacimiento determina la personalidad, pero el concebido se tiene por nacido para todos los efectos favorables si llega a nacer en las condiciones legales (art. 29). La personalidad se adquiere en el momento del nacimiento con vida, una vez producido el entero desprendimiento del seno materno (art. 30). Se extingue por la muerte (art. 32).","refs":[{"ref":"Art. 29 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El nacimiento determina la personalidad; pero el concebido se tiene por nacido para todos los efectos que le sean favorables, siempre que nazca con las condiciones que expresa el artículo siguiente."},{"ref":"Art. 30 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La personalidad se adquiere en el momento del nacimiento con vida, una vez producido el entero desprendimiento del seno materno."},{"ref":"Art. 32 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La personalidad civil se extingue por la muerte de las personas."}]},{"text":"Si se duda entre dos o más personas llamadas a sucederse cuál murió primero, quien sostenga la muerte anterior debe probarla; a falta de prueba se presumen muertas al mismo tiempo y no hay transmisión de derechos entre ellas (art. 33, conmoriencia). Son personas jurídicas las corporaciones, asociaciones y fundaciones de interés público reconocidas por la ley, con personalidad desde su válida constitución, y las asociaciones de interés particular a las que la ley conceda personalidad propia (art. 35).","refs":[{"ref":"Art. 33 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"a falta de prueba, se presumen muertas al mismo tiempo y no tiene lugar la transmisión de derechos de uno a otro."},{"ref":"Art. 35 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las corporaciones, asociaciones y fundaciones de interés público reconocidas por la ley. Su personalidad empieza desde el instante mismo en que, con arreglo a derecho, hubiesen quedado válidamente constituidas."}]}]},{"n":"5","title":"Del domicilio (arts. 40-41 CC)","blocks":[{"text":"Para ejercer derechos y cumplir obligaciones civiles, el domicilio de las personas naturales es el lugar de su residencia habitual y, en su caso, el que determine la Ley de Enjuiciamiento Civil (art. 40). Si ni la ley ni los estatutos fijan el domicilio de una persona jurídica, se entiende que está donde tenga su representación legal o ejerza sus principales funciones (art. 41).","refs":[{"ref":"Art. 40 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"el domicilio de las personas naturales es el lugar de su residencia habitual, y, en su caso, el que determine la Ley de Enjuiciamiento Civil."},{"ref":"Art. 41 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"se entenderá que lo tienen en el lugar en que se halle establecida su representación legal, o donde ejerzan las principales funciones de su instituto."}]}]},{"n":"6","title":"Del matrimonio: requisitos, efectos, nulidad, separación y divorcio (arts. 42-107 CC)","blocks":[{"text":"La promesa de matrimonio no obliga a contraerlo (art. 42). Toda persona tiene derecho a casarse y el matrimonio tiene los mismos requisitos y efectos entre personas del mismo o de distinto sexo (art. 44). No hay matrimonio sin consentimiento, y la condición, término o modo se tiene por no puesta (art. 45). No pueden casarse los menores no emancipados ni quienes ya están casados (art. 46); ni entre sí los parientes en línea recta por consanguinidad o adopción, los colaterales por consanguinidad hasta el tercer grado y los condenados por participar en la muerte dolosa del cónyuge (art. 47). El juez puede dispensar el impedimento de muerte dolosa y el de parentesco de tercer grado colateral (art. 48).","refs":[{"ref":"Art. 44 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El matrimonio tendrá los mismos requisitos y efectos cuando ambos contrayentes sean del mismo o de diferente sexo."},{"ref":"Art. 45 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"No hay matrimonio sin consentimiento matrimonial. La condición, término o modo del consentimiento se tendrá por no puesta."},{"ref":"Art. 47 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los parientes en línea recta por consanguinidad o adopción. 2. Los colaterales por consanguinidad hasta el tercer grado."}]},{"text":"Los cónyuges son iguales (art. 66) y deben vivir juntos, guardarse fidelidad, socorrerse y compartir las responsabilidades domésticas y el cuidado de las personas dependientes (art. 68). Es nulo el matrimonio sin consentimiento, el celebrado con impedimento no dispensado, sin la autoridad o los testigos, por error en la identidad o en cualidades determinantes, o por coacción o miedo grave (art. 73).","refs":[{"ref":"Art. 68 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los cónyuges están obligados a vivir juntos, guardarse fidelidad y socorrerse mutuamente. Deberán, además, compartir las responsabilidades domésticas"},{"ref":"Art. 73 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"5.º El contraído por coacción o miedo grave."}]},{"text":"La separación judicial puede pedirse por ambos cónyuges o por uno solo una vez transcurridos tres meses desde la boda, plazo que no se exige si hay riesgo para la vida, integridad o libertad del cónyuge o de los hijos (art. 81). El divorcio se decreta con los mismos requisitos (art. 86). El matrimonio se disuelve por la muerte o la declaración de fallecimiento de uno de los cónyuges y por el divorcio (art. 85); los efectos del divorcio se producen desde la firmeza de la sentencia o decreto, o desde la escritura pública de mutuo acuerdo (art. 89).","refs":[{"ref":"Art. 81 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"A petición de uno solo de los cónyuges, una vez transcurridos tres meses desde la celebración del matrimonio."},{"ref":"Art. 85 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El matrimonio se disuelve, sea cual fuere la forma y el tiempo de su celebración, por la muerte o la declaración de fallecimiento de uno de los cónyuges y por el divorcio."}]}]},{"n":"7","title":"Filiación y alimentos entre parientes (arts. 108-153 CC)","blocks":[{"text":"La filiación puede ser por naturaleza o por adopción; la natural es matrimonial cuando los progenitores están casados entre sí, y todas surten los mismos efectos (art. 108). Produce efectos desde que tiene lugar y su determinación es retroactiva cuando sea compatible (art. 112). Se acredita por la inscripción en el Registro Civil, el documento o sentencia que la determina, la presunción de paternidad matrimonial y, en último término, la posesión de estado (art. 113).","refs":[{"ref":"Art. 108 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La filiación puede tener lugar por naturaleza y por adopción. La filiación por naturaleza puede ser matrimonial y no matrimonial. Es matrimonial cuando los progenitores están casados entre sí."},{"ref":"Art. 113 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La filiación se acredita por la inscripción en el Registro Civil, por el documento o sentencia que la determina legalmente, por la presunción de paternidad matrimonial y, a falta de los medios anteriores, por la posesión de estado."}]},{"text":"Los alimentos comprenden todo lo indispensable para sustento, habitación, vestido y asistencia médica, además de la educación del alimentista menor y los gastos de embarazo y parto (art. 142). Se los deben en toda su extensión los cónyuges y los ascendientes y descendientes; los hermanos solo se deben los auxilios necesarios para la vida cuando los necesiten por causa no imputable al alimentista (art. 143). El orden de reclamación es: cónyuge, descendientes, ascendientes y hermanos (art. 144), y la cuantía es proporcional al caudal de quien da y a las necesidades de quien recibe (art. 146).","refs":[{"ref":"Art. 142 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Se entiende por alimentos todo lo que es indispensable para el sustento, habitación, vestido y asistencia médica."},{"ref":"Art. 143 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los hermanos sólo se deben los auxilios necesarios para la vida, cuando los necesiten por cualquier causa que no sea imputable al alimentista, y se extenderán en su caso a los que precisen para su educación."},{"ref":"Art. 146 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La cuantía de los alimentos será proporcionada al caudal o medios de quien los da y a las necesidades de quien los recibe."}]}]},{"n":"8","title":"Relaciones paterno-filiales y adopción (arts. 154-180 CC)","blocks":[{"text":"Los hijos no emancipados están bajo la patria potestad de los progenitores, que se ejerce como responsabilidad parental en interés de los hijos y comprende velar por ellos, educarlos, representarlos, administrar sus bienes y decidir su residencia habitual (art. 154). Se ejerce conjuntamente o por uno con consentimiento del otro (art. 156). Cuando la Entidad Pública constata un desamparo asume por ministerio de la ley la tutela del menor (art. 172.1).","refs":[{"ref":"Art. 154 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los hijos e hijas no emancipados están bajo la patria potestad de los progenitores."}]},{"text":"El adoptante debe ser mayor de veinticinco años (basta uno si son dos) y la diferencia de edad con el adoptando ha de ser de al menos dieciséis años y no superior a cuarenta y cinco, salvo excepciones (art. 175.1). Solo se adoptan menores no emancipados, salvo excepción (art. 175.2), y no puede adoptarse a un descendiente ni a un pariente en segundo grado colateral (art. 175.3). La adopción se constituye por resolución judicial (art. 176.1) y extingue los vínculos jurídicos con la familia de origen (art. 178.1).","refs":[{"ref":"Art. 175.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La adopción requiere que el adoptante sea mayor de veinticinco años. Si son dos los adoptantes bastará con que uno de ellos haya alcanzado dicha edad. En todo caso, la diferencia de edad entre adoptante y adoptando será de, al menos, dieciséis años"},{"ref":"Art. 176.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La adopción se constituirá por resolución judicial"},{"ref":"Art. 178.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La adopción produce la extinción de los vínculos jurídicos entre el adoptado y su familia de origen."}]}]},{"n":"9","title":"Ausencia y declaración de fallecimiento (arts. 181-198 CC)","blocks":[{"text":"Desaparecida una persona sin noticias, puede nombrarse un defensor; el cónyuge presente mayor de edad no separado es su defensor nato (art. 181). Hay ausencia legal pasado un año desde las últimas noticias si no dejó apoderado general, o tres años si dejó encomendada la administración de todos sus bienes (art. 183). Ojo: los arts. 181 y 184 del texto consolidado aún dicen «Secretario judicial» (hoy letrado de la Administración de Justicia).","refs":[{"ref":"Art. 183 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Primero. Pasado un año desde las últimas noticias o a falta de éstas desde su desaparición, si no hubiese dejado apoderado con facultades de administración de todos sus bienes. Segundo. Pasados tres años, si hubiese dejado encomendada por apoderamiento la administración de todos sus bienes."},{"ref":"Art. 181 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El cónyuge presente mayor de edad no separado legalmente será el representante y defensor nato del desaparecido"}]},{"text":"Procede declarar el fallecimiento a los diez años de las últimas noticias, o a los cinco si al expirar el plazo el ausente hubiera cumplido setenta y cinco años; los plazos se cuentan desde el fin del año natural de las últimas noticias. Si hubo riesgo inminente de muerte por violencia, basta un año, y en caso de siniestro, tres meses (art. 193). La declaración pone fin a la ausencia legal (art. 195) y abre la sucesión, aunque los herederos no pueden disponer a título gratuito hasta cinco años después (art. 196).","refs":[{"ref":"Art. 193 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"1º. Transcurridos diez años desde las últimas noticias habidas del ausente, o, a falta de éstas, desde su desaparición. 2º. Pasados cinco años desde las ultimas noticias o, en defecto de éstas, desde su desaparición, si al expirar dicho plazo hubiere cumplido el ausente setenta y cinco años."},{"ref":"Art. 193 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"En caso de siniestro este plazo será de tres meses."},{"ref":"Art. 196 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los herederos no podrán disponer a título gratuito hasta cinco años después de la declaración del fallecimiento."}]}]},{"n":"10","title":"Tutela y guarda de los menores (arts. 199-238 CC)","blocks":[{"text":"Tras la reforma de 2021, la tutela queda reservada a menores: están sujetos a ella los menores no emancipados en situación de desamparo y los no sujetos a patria potestad (art. 199). Las funciones tutelares son un deber, se ejercen en beneficio del tutelado y bajo salvaguarda judicial (art. 200). También pueden ser tutores personas jurídicas sin ánimo de lucro dedicadas a la protección de menores (art. 212). Se prefiere a la persona designada por los progenitores en testamento o documento notarial y, después, al ascendiente o hermano que designe el juez (art. 213).","refs":[{"ref":"Art. 199 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Quedan sujetos a tutela: 1.º Los menores no emancipados en situación de desamparo. 2.º Los menores no emancipados no sujetos a patria potestad."},{"ref":"Art. 200 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las funciones tutelares constituyen un deber, se ejercerán en beneficio del tutelado y estarán bajo la salvaguarda de la autoridad judicial."},{"ref":"Art. 213 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"1.º A la persona o personas designadas por los progenitores en testamento o documento público notarial. 2.º Al ascendiente o hermano que designe la autoridad judicial."}]}]},{"n":"11","title":"Mayor edad y emancipación (arts. 239-248 CC)","blocks":[{"text":"La emancipación tiene lugar por la mayor edad, por concesión de quienes ejercen la patria potestad y por concesión judicial (art. 239). La mayor edad empieza a los dieciocho años cumplidos, incluyendo completo el día del nacimiento (art. 240). La concesión paterna exige que el menor tenga dieciséis años cumplidos y la consienta, y se otorga por escritura pública o comparecencia ante el encargado del Registro Civil (art. 241); se inscribe y no puede revocarse (art. 242).","refs":[{"ref":"Art. 239 y 240 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"1.º Por la mayor edad. 2.º Por concesión de los que ejerzan la patria potestad. 3.º Por concesión judicial. […] La mayor edad empieza a los dieciocho años cumplidos."},{"ref":"Art. 241 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"se requiere que el menor tenga dieciséis años cumplidos y que la consienta. Esta emancipación se otorgará por escritura pública o por comparecencia ante el encargado del Registro Civil."}]},{"text":"El emancipado rige su persona y bienes como si fuera mayor, pero hasta la mayor edad no puede tomar dinero a préstamo, gravar o enajenar inmuebles, establecimientos mercantiles u objetos de extraordinario valor sin consentimiento de sus progenitores; sí puede comparecer en juicio por sí solo (art. 247).","refs":[{"ref":"Art. 247 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La emancipación habilita al menor para regir su persona y bienes como si fuera mayor; pero hasta que llegue a la mayor edad no podrá el emancipado tomar dinero a préstamo, gravar o enajenar bienes inmuebles y establecimientos mercantiles o industriales u objetos de extraordinario valor sin consentimiento de sus progenitores"},{"ref":"Art. 247 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El menor emancipado podrá por sí solo comparecer en juicio."}]}]},{"n":"12","title":"Medidas de apoyo a las personas con discapacidad y disposiciones comunes (arts. 249-300 CC)","blocks":[{"text":"Las medidas de apoyo a mayores de edad o menores emancipados buscan el pleno desarrollo de su personalidad en igualdad, respetando su voluntad, deseos y preferencias, y se rigen por los principios de necesidad y proporcionalidad (art. 249). Son, además de las voluntarias, la guarda de hecho (medida informal), la curatela (medida formal para quien precisa apoyo de modo continuado) y el defensor judicial (apoyo ocasional, aunque sea recurrente) (art. 250). Las medidas judiciales se revisan como máximo cada tres años (art. 268). Las resoluciones y documentos notariales sobre cargos tutelares y medidas de apoyo se inscriben en el Registro Civil (art. 300).","refs":[{"ref":"Art. 250 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las medidas de apoyo para el ejercicio de la capacidad jurídica de las personas que lo precisen son, además de las de naturaleza voluntaria, la guarda de hecho, la curatela y el defensor judicial."},{"ref":"Art. 250 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La curatela es una medida formal de apoyo que se aplicará a quienes precisen el apoyo de modo continuado."},{"ref":"Art. 250 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"El nombramiento de defensor judicial como medida formal de apoyo procederá cuando la necesidad de apoyo se precise de forma ocasional, aunque sea recurrente."},{"ref":"Art. 268 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las medidas de apoyo adoptadas judicialmente serán revisadas periódicamente en un plazo máximo de tres años."},{"ref":"Art. 300 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las resoluciones judiciales y los documentos públicos notariales sobre los cargos tutelares y medidas de apoyo a personas con discapacidad habrán de inscribirse en el Registro Civil."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Fuentes: ley, costumbre y principios generales; la jurisprudencia del Tribunal Supremo solo complementa (art. 1 CC).","refs":[{"ref":"Art. 1.6 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"La jurisprudencia complementará el ordenamiento jurídico"}]},{"text":"Vacatio legis general: veinte días desde la completa publicación en el BOE (art. 2.1).","refs":[{"ref":"Art. 2.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las leyes entrarán en vigor a los veinte días de su completa publicación"}]},{"text":"Sin analogía: leyes penales, excepcionales y de ámbito temporal (art. 4.2).","refs":[{"ref":"Art. 4.2 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Las leyes penales, las excepcionales y las de ámbito temporal"}]},{"text":"Vecindad civil: dos años de residencia con declaración o diez sin declaración en contrario (art. 14.5).","refs":[{"ref":"Art. 14.5 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Por residencia continuada de diez años, sin declaración en contrario durante este plazo."}]},{"text":"Nacionalidad por residencia: 10 años; 5 refugiados; 2 iberoamericanos, Andorra, Filipinas, Guinea Ecuatorial, Portugal y sefardíes; nulidad por fraude, acción del Fiscal en quince años (arts. 22.1 y 25.2).","refs":[{"ref":"Art. 25.2 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"dentro del plazo de quince años."}]},{"text":"Personalidad: nacimiento con vida y entero desprendimiento del seno materno; conmoriencia: muertas al mismo tiempo (arts. 30 y 33).","refs":[{"ref":"Art. 30 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"una vez producido el entero desprendimiento del seno materno."}]},{"text":"Impedimento colateral por consanguinidad: hasta el tercer grado, dispensable (arts. 47 y 48).","refs":[{"ref":"Art. 47 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"Los colaterales por consanguinidad hasta el tercer grado."}]},{"text":"Adopción: adoptante mayor de 25 años y diferencia mínima de 16 (máxima de 45) (art. 175.1).","refs":[{"ref":"Art. 175.1 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"la diferencia de edad entre adoptante y adoptando será de, al menos, dieciséis años y no podrá ser superior a cuarenta y cinco años"}]},{"text":"Fallecimiento: diez años, o cinco si el ausente cumplió 75; emancipación paterna: dieciséis años cumplidos y consentimiento del menor (arts. 193 y 241).","refs":[{"ref":"Art. 241 CC","law":"Código Civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","quote":"se requiere que el menor tenga dieciséis años cumplidos y que la consienta."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763', null, null, null, null
