insert into public.sources (title, url, kind, publisher, published_on) values ('Orden PRE/422/2013, de 15 de marzo, estructura orgánica de los Servicios Centrales de la Dirección General de la Guardia Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-15c-servicios-centrales-dggc', 'Tema 15. Estructura de los Servicios Centrales de la Dirección General de la Guardia Civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-15c-servicios-centrales-dggc' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Dirección General de la Guardia Civil: organización central y periférica (Orden PRE/422/2013, cap. I)"},{"n":"1.1","title":"Órganos colegiados y órganos de apoyo al Director: Gabinete Técnico, Asesoría Jurídica, Secretaría de Despacho"},{"n":"1.2","title":"Centro Universitario de la Guardia Civil"},{"n":"1.3","title":"Estructura vigente de primer nivel según el RD 207/2024 (Dirección Adjunta Operativa, Mando de Personal, Mando de Apoyo)"},{"n":"2","title":"Dirección Adjunta Operativa y Mando de Operaciones (cap. II)"},{"n":"2.1","title":"Estado Mayor y Jefatura de Unidades Especiales y de Reserva"},{"n":"2.2","title":"Jefaturas de Información, Policía Judicial, Fiscal y de Fronteras, Tráfico y SEPRONA; Zonas"},{"n":"2.3","title":"Asuntos Internos y Unidad Especial de Intervención"},{"n":"3","title":"Área de personal (cap. III): Jefaturas de Personal, Enseñanza y Asistencia al Personal; Observatorio de Conducta Ética"},{"n":"4","title":"Área de apoyo (cap. IV): Jefaturas de los Servicios de Apoyo, de Servicios Técnicos y de Asuntos Económicos"}]'::jsonb, '["Art. 1.2 Orden PRE/422/2013: «La organización periférica de la Dirección General de la Guardia Civil estará constituida por las Zonas, las Comandancias, las Compañías y los Puestos.»","Art. 2 Orden PRE/422/2013: «Adscritos a la Dirección General de la Guardia Civil estarán el Consejo Superior de la Guardia Civil y el Consejo de la Guardia Civil»","Art. 4.3 RD 207/2024: «De la persona titular de la Dirección General dependen directamente los siguientes órganos: a) La Dirección Adjunta Operativa. b) El Mando de Personal. c) El Mando de Apoyo.»","Art. 3.2 Orden PRE/422/2013: «Gabinete Técnico. Con nivel orgánico de Subdirección General, y a cargo de un Oficial General de la Guardia Civil, es el órgano de asistencia y apoyo del Director General»","Art. 4 Orden PRE/422/2013: «Dependiente de la Dirección General de la Guardia Civil se encuentra el Centro Universitario de la Guardia Civil, con naturaleza de centro universitario público, cuya titularidad corresponde al Ministro del Interior.»","Art. 5.1.e) Orden PRE/422/2013: «e) Sustituir al Director General de la Guardia Civil, con carácter interino o accidental, así como en el ejercicio de la potestad sancionadora que le atribuye la legislación vigente sobre régimen disciplinario del Cuerpo de la Guardia Civil.»","Art. 7.2 Orden PRE/422/2013: «Del Jefe del Estado Mayor depende orgánicamente la Sala de Operaciones y Servicios, que tiene como misión la recepción y transmisión de las novedades y órdenes relativas al servicio diario. Cuando las necesidades del mismo así lo aconsejen, se activará como Centro de Crisis»","Art. 8.2.b) Orden PRE/422/2013: «b) Unidad de Acción Rural. Unidad de la Guardia Civil, especialmente concebida, preparada y organizada para la lucha contra elementos terroristas y la ejecución de operaciones que entrañen gran riesgo y requieran una respuesta rápida»","Art. 9 Orden PRE/422/2013: «A la Jefatura de Información, al mando de un Oficial General de la Guardia Civil en situación de servicio activo, le corresponde organizar, dirigir y gestionar la obtención, recepción, tratamiento, análisis y difusión de la información de interés para el orden público y la seguridad ciudadana»","Art. 10.2.a) Orden PRE/422/2013: «a) Unidad Central Operativa. Tiene como misión investigar y perseguir los asuntos relacionados con la delincuencia grave, nacional e internacional»","Art. 14.1 Orden PRE/422/2013: «son las Unidades de mando, coordinación e inspección de todos los Servicios de la Dirección General de la Guardia Civil existentes en el ámbito territorial de cada una de ellas.»","Art. 17.1 Orden PRE/422/2013: «El Servicio de Asuntos Internos tiene como misión investigar las conductas contrarias a la ética profesional del personal destinado en la Dirección General de la Guardia Civil»","Art. 22.2.d) Orden PRE/422/2013: «d) Servicio de Prevención. Tiene como cometidos el control interno superior, dentro de la estructura orgánica de la Dirección General de la Guardia Civil, en materia de prevención de riesgos para la seguridad y salud del personal en el trabajo.»","Art. 23 bis Orden PRE/422/2013: «El Observatorio de Conducta Ética de la Guardia Civil, con el nivel orgánico que se determine en la relación de puestos de trabajo, es el órgano responsable de centralizar las labores de seguimiento, impulso y evaluación de la aplicación del Código de Conducta en la Guardia Civil.»","Art. 24.3 Orden PRE/422/2013: «a) Jefatura de los Servicios de Apoyo. b) Jefatura de Servicios Técnicos. c) Jefatura de Asuntos Económicos.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Dirección General de la Guardia Civil: organización central y periférica (Orden PRE/422/2013, art. 1)","blocks":[{"text":"La Orden PRE/422/2013 desarrolla la estructura de los Servicios Centrales de la Dirección General de la Guardia Civil. En su texto, la organización central se articula en tres órganos directivos con rango de Subdirección General: la Dirección Adjunta Operativa, la Subdirección General de Personal y la Subdirección General de Apoyo. La organización periférica está formada por las Zonas, las Comandancias, las Compañías y los Puestos (art. 1). Ojo: el RD 207/2024 llama hoy «Mando de Personal» y «Mando de Apoyo» a las dos últimas (apartado 3).","refs":[{"ref":"Art. 1.1 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"a) Dirección Adjunta Operativa. b) Subdirección General de Personal. c) Subdirección General de Apoyo."},{"ref":"Art. 1.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"La organización periférica de la Dirección General de la Guardia Civil estará constituida por las Zonas, las Comandancias, las Compañías y los Puestos."}]}]},{"n":"2","title":"Órganos colegiados, órganos de apoyo al Director y Centro Universitario (arts. 2-4)","blocks":[{"text":"Están adscritos a la Dirección General dos órganos colegiados: el Consejo Superior de la Guardia Civil y el Consejo de la Guardia Civil (art. 2). Del Director General dependen directamente tres unidades de apoyo: el Gabinete Técnico, la Asesoría Jurídica y la Secretaría de Despacho (art. 3.1).","refs":[{"ref":"Art. 2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Adscritos a la Dirección General de la Guardia Civil estarán el Consejo Superior de la Guardia Civil y el Consejo de la Guardia Civil"},{"ref":"Art. 3.1 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"a) Gabinete Técnico. b) Asesoría Jurídica. c) Secretaría de Despacho."}]},{"text":"El Gabinete Técnico tiene nivel orgánico de Subdirección General, está a cargo de un Oficial General y es el órgano de asistencia y apoyo del Director General: coordina órganos, gestiona relaciones institucionales, estudia planes y tramita disposiciones. De su Jefe dependen la Oficina de Relaciones Informativas y Sociales (comunicación interna y externa, web e intranet), la Oficina de Protocolo y el Centro de Análisis y Prospectiva, que gestiona conocimiento y fuentes abiertas sobre seguridad (art. 3.2).","refs":[{"ref":"Art. 3.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Gabinete Técnico. Con nivel orgánico de Subdirección General, y a cargo de un Oficial General de la Guardia Civil, es el órgano de asistencia y apoyo del Director General"},{"ref":"Art. 3.2.b Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Centro de Análisis y Prospectiva. Órgano de apoyo para la gestión de información relacionada con la seguridad interior"}]},{"text":"La Asesoría Jurídica es el órgano consultivo y asesor en materia jurídica, sin perjuicio de la Abogacía General del Estado (art. 3.3). La Secretaría de Despacho presta asistencia personal e inmediata al Director (agenda, reuniones, viajes y seguridad personal), y de su Jefe dependen la Unidad de Escolta del Director General y el Registro Central de la correspondencia oficial (art. 3.4).","refs":[{"ref":"Art. 3.4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Del Jefe de la Secretaría de Despacho dependen también la Unidad de Escolta del Director General y el Registro Central, encargado de la tramitación de la correspondencia oficial"}]},{"text":"El Centro Universitario de la Guardia Civil depende de la Dirección General, tiene naturaleza de centro universitario público y su titularidad corresponde al Ministro del Interior; imparte los estudios conducentes a títulos oficiales (art. 4).","refs":[{"ref":"Art. 4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Dependiente de la Dirección General de la Guardia Civil se encuentra el Centro Universitario de la Guardia Civil, con naturaleza de centro universitario público, cuya titularidad corresponde al Ministro del Interior."}]}]},{"n":"3","title":"Estructura de primer nivel según el RD 207/2024","blocks":[{"text":"El Real Decreto 207/2024 (texto consolidado con modificaciones de 2025 y 2026) define la Dirección General como el órgano encargado de la ordenación, dirección, coordinación y ejecución de las misiones de la Guardia Civil; su titular tiene rango de subsecretario y ejerce el mando directo del Cuerpo bajo la dependencia de la Secretaría de Estado de Seguridad. De él dependen directamente la Dirección Adjunta Operativa, el Mando de Personal y el Mando de Apoyo, y cuenta con un Gabinete Técnico con nivel de subdirección general (art. 4).","refs":[{"ref":"Art. 4.1 RD 207/2024","law":"RD 207/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793","quote":"Corresponde a la persona titular de la Dirección General, bajo la dependencia de la persona titular de la Secretaría de Estado de Seguridad, el mando directo de la Guardia Civil."},{"ref":"Art. 4.3 RD 207/2024","law":"RD 207/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793","quote":"De la persona titular de la Dirección General dependen directamente los siguientes órganos: a) La Dirección Adjunta Operativa. b) El Mando de Personal. c) El Mando de Apoyo."}]},{"text":"El Consejo Superior de la Guardia Civil lo preside el Director General y lo integran los Tenientes Generales y Generales de División en servicio activo (art. 4.2 RD 207/2024). Ojo: el RD también recoge unidades que la Orden PRE/422/2013 no tiene, como el Mando de Fronteras y Policía Marítima o la Jefatura de Armas, Explosivos y Seguridad; las preguntas de este tema siguen el texto de la Orden.","refs":[{"ref":"Art. 4.2 RD 207/2024","law":"RD 207/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793","quote":"El Consejo Superior de la Guardia Civil estará presidido por la persona titular de la Dirección General de la Guardia Civil e integrado, asimismo, por los Tenientes Generales y Generales de División de la Guardia Civil en servicio activo"},{"ref":"Art. 4.6 RD 207/2024","law":"RD 207/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793","quote":"b) El Mando de Fronteras y Policía Marítima."}]}]},{"n":"4","title":"Dirección Adjunta Operativa (cap. II, art. 5)","blocks":[{"text":"La Dirección Adjunta Operativa, con nivel de Subdirección General y a cargo de un Teniente General en servicio activo, es el principal colaborador del Director General. Dirige y coordina los servicios de las unidades, propone su organización y distribución territorial y sustituye al Director General con carácter interino o accidental, también en la potestad sancionadora disciplinaria (art. 5.1). De ella dependen el Mando de Operaciones, la Secretaría de Cooperación Internacional, la Intervención Central de Armas y Explosivos, el Servicio de Asuntos Internos, la Unidad Especial de Intervención y la Unidad de Coordinación de Ciberseguridad; al Director Adjunto Operativo lo sustituye el titular del Mando de Operaciones (art. 5.3 y 5.4).","refs":[{"ref":"Art. 5.1.e Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Sustituir al Director General de la Guardia Civil, con carácter interino o accidental, así como en el ejercicio de la potestad sancionadora que le atribuye la legislación vigente sobre régimen disciplinario del Cuerpo de la Guardia Civil."},{"ref":"Art. 5.4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"El titular del Mando de Operaciones sustituirá al Director Adjunto Operativo, con carácter interino o accidental."}]}]},{"n":"5","title":"Mando de Operaciones y Estado Mayor (arts. 6-7)","blocks":[{"text":"El Mando de Operaciones, también a cargo de un Teniente General, planea y conduce operativamente los servicios. De él dependen el Estado Mayor, la Jefatura de Unidades Especiales y de Reserva, las Jefaturas de Información, Policía Judicial, Fiscal y de Fronteras, Agrupación de Tráfico y SEPRONA, las Zonas y las Comandancias de Ceuta y Melilla (art. 6).","refs":[{"ref":"Art. 6.1 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"es responsable del planeamiento y de la conducción operativa de los servicios"}]},{"text":"El Estado Mayor es el principal órgano auxiliar del Mando de Operaciones y elabora la Doctrina de actuación de las unidades operativas. De su Jefe depende la Sala de Operaciones y Servicios, que recibe y transmite las novedades y órdenes del servicio diario y que, cuando es necesario, se activa como Centro de Crisis (art. 7).","refs":[{"ref":"Art. 7.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Del Jefe del Estado Mayor depende orgánicamente la Sala de Operaciones y Servicios, que tiene como misión la recepción y transmisión de las novedades y órdenes relativas al servicio diario. Cuando las necesidades del mismo así lo aconsejen, se activará como Centro de Crisis"}]}]},{"n":"6","title":"Jefatura de Unidades Especiales y de Reserva (art. 8)","blocks":[{"text":"Esta Jefatura dirige, coordina y controla varias unidades. La Agrupación de Reserva y Seguridad es la principal unidad de reserva, para prevenir y restablecer la seguridad pública. La Unidad de Acción Rural está concebida para la lucha contra elementos terroristas y para operaciones de gran riesgo que requieran respuesta rápida. El Servicio Aéreo explota los medios aéreos (art. 8.2.a-c).","refs":[{"ref":"Art. 8.2.b Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Unidad de Acción Rural. Unidad de la Guardia Civil, especialmente concebida, preparada y organizada para la lucha contra elementos terroristas y la ejecución de operaciones que entrañen gran riesgo y requieran una respuesta rápida"}]},{"text":"El Servicio Cinológico y Remonta dirige técnicamente los servicios con unidades dotadas de perros y gestiona el ganado. El Servicio de Desactivación de Explosivos y Defensa NRBQ actúa ante artefactos explosivos, incendiarios, nucleares, radiológicos, biológicos o químicos y mantiene la operatividad del Sistema de Defensa NRBQ del Cuerpo. El Servicio de Montaña actúa en zonas de orografía o clima difícil, y el Servicio de Protección y Seguridad protege instalaciones y personalidades y ejerce competencias de seguridad privada (art. 8.2.d-g). También dependen orgánicamente de esta Jefatura las unidades de seguridad de la Casa del Rey y de Presidencia del Gobierno (art. 8.3).","refs":[{"ref":"Art. 8.2.d Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio Cinológico y Remonta. Órgano especializado de la Guardia Civil para la dirección técnica y ejecución de los servicios en los que participen Unidades dotadas de perros"},{"ref":"Art. 8.2.e Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"para dirigir técnicamente y mantener la operatividad del Sistema de Defensa NRBQ de la Guardia Civil"},{"ref":"Art. 8.3 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"la Unidad de Seguridad de la Casa de Su Majestad El Rey, la Unidad de Seguridad de Presidencia del Gobierno"}]}]},{"n":"7","title":"Jefaturas de Información, Policía Judicial, Fiscal y de Fronteras, Tráfico y SEPRONA; Zonas (arts. 9-14)","blocks":[{"text":"La Jefatura de Información obtiene, analiza y difunde la información de interés para el orden público, especialmente en materia antiterrorista (art. 9). De la Jefatura de Policía Judicial dependen la Unidad Central Operativa (UCO), que investiga la delincuencia grave nacional e internacional; la Unidad Técnica de Policía Judicial, que asesora, centraliza la información y el análisis criminal y encuadra administrativamente al personal destinado en Interpol, Europol y SIRENE; y el Servicio de Criminalística, que elabora informes periciales e identifica personas en sucesos con víctimas múltiples (art. 10).","refs":[{"ref":"Art. 10.2.a Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Unidad Central Operativa. Tiene como misión investigar y perseguir los asuntos relacionados con la delincuencia grave, nacional e internacional"},{"ref":"Art. 10.2.b Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Asimismo, encuadra a efectos administrativos al personal del Cuerpo de la Guardia Civil destinado en Interpol, Europol, SIRENE"},{"ref":"Art. 10.2.c Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"identificar personas en sucesos con víctimas múltiples"}]},{"text":"La Jefatura Fiscal y de Fronteras gestiona el resguardo fiscal, la lucha contra el contrabando y el narcotráfico y la vigilancia de costas, fronteras, puertos y aeropuertos; de ella dependen la Oficina de Proyectos y los Servicios Fiscal, Marítimo y de Costas y Fronteras (art. 11). La Agrupación de Tráfico es la unidad especializada en tráfico, seguridad vial y transporte (art. 12), y el SEPRONA vela por la naturaleza, el medio ambiente, la caza y pesca y el patrimonio histórico (art. 13). Las Zonas son las unidades de mando, coordinación e inspección de todos los servicios en su territorio (art. 14).","refs":[{"ref":"Art. 11.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio Marítimo. Tiene como misión específica ejercer las funciones que le corresponden a la Guardia Civil en las aguas marítimas españolas y las aguas continentales"},{"ref":"Art. 14.1 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"son las Unidades de mando, coordinación e inspección de todos los Servicios de la Dirección General de la Guardia Civil existentes en el ámbito territorial de cada una de ellas."}]}]},{"n":"8","title":"Cooperación internacional, armas, Asuntos Internos y UEI (arts. 15-18)","blocks":[{"text":"La Secretaría de Cooperación Internacional centraliza las peticiones de cooperación internacional y lo relativo a los agregados en el extranjero (art. 15). La Intervención Central de Armas y Explosivos controla las competencias sobre armas, explosivos, pirotecnia y cartuchería (art. 16). El Servicio de Asuntos Internos investiga las conductas contrarias a la ética profesional del personal de la Dirección General (art. 17), y la Unidad Especial de Intervención ejecuta las operaciones que por su peligrosidad se le encomienden (art. 18).","refs":[{"ref":"Art. 17.1 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"El Servicio de Asuntos Internos tiene como misión investigar las conductas contrarias a la ética profesional del personal destinado en la Dirección General de la Guardia Civil"},{"ref":"Art. 18 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"La Unidad Especial de Intervención tiene como misión específica ejecutar las operaciones que, por su peligrosidad o especiales características se le encomienden."}]}]},{"n":"9","title":"Área de personal (cap. III, arts. 19-23 ter)","blocks":[{"text":"La Subdirección General de Personal dirige la política de personal y educativa; de ella dependen las Jefaturas de Personal, Enseñanza y Asistencia al Personal, la Secretaría Permanente para la Clasificación y Evaluación, el Observatorio de Conducta Ética y la Unidad de Desarrollo y Talento (art. 19). La Jefatura de Personal gestiona ascensos, destinos, situaciones, retribuciones y régimen disciplinario, y de ella dependen los Servicios de Gestión del Personal, Retribuciones, Régimen Disciplinario e Historial Profesional (art. 20).","refs":[{"ref":"Art. 19.4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"e) El Observatorio de Conducta Ética de la Guardia Civil."},{"ref":"Art. 20.2.d Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio de Historial Profesional, responsable de recepcionar, integrar, controlar y gestionar la información que forma parte del Historial Profesional del personal de la Guardia Civil."}]},{"text":"La Jefatura de Enseñanza organiza la selección, formación, perfeccionamiento y altos estudios y la actividad deportiva; tiene los Servicios de Formación y Capacitación, Selección y Perfeccionamiento y Altos Estudios, de ella dependen los centros docentes, y en ella se ubica la representación de la Escuela Iberoamericana de Policía (IBERPOL) (art. 21).","refs":[{"ref":"Art. 21.4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"En la Jefatura de Enseñanza queda ubicada la representación, en el ámbito de la Guardia Civil, de la Escuela Iberoamérica de Policía (IBERPOL)."}]},{"text":"La Jefatura de Asistencia al Personal gestiona la acción social y la asistencia sanitaria y psicológica. Sus servicios son Acción Social, Sanidad, Psicología, Prevención (control interno superior en prevención de riesgos laborales), Asuntos Generales y Estudios Históricos, que dirige el Museo y la Biblioteca (art. 22). El Observatorio de Conducta Ética centraliza el seguimiento, impulso y evaluación del Código de Conducta (art. 23 bis).","refs":[{"ref":"Art. 22.2.d Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio de Prevención. Tiene como cometidos el control interno superior, dentro de la estructura orgánica de la Dirección General de la Guardia Civil, en materia de prevención de riesgos para la seguridad y salud del personal en el trabajo."},{"ref":"Art. 22.2.f Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"ejerciendo para ello la dirección del Museo y de la Biblioteca."},{"ref":"Art. 23 bis Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"es el órgano responsable de centralizar las labores de seguimiento, impulso y evaluación de la aplicación del Código de Conducta en la Guardia Civil."}]}]},{"n":"10","title":"Área de apoyo (cap. IV, arts. 24-27)","blocks":[{"text":"La Subdirección General de Apoyo, a cargo de un Teniente General, gestiona los recursos financieros y materiales a través de tres Jefaturas (art. 24). La de los Servicios de Apoyo se ocupa del material móvil, armamento, equipamiento e infraestructuras, con los Servicios de Acuartelamiento, Material Móvil, Armamento y Equipamiento Policial y Abastecimiento (art. 25). La de Servicios Técnicos lleva informática, telecomunicaciones, innovación tecnológica y estadística (art. 26), y la de Asuntos Económicos, contratación y gestión económica (art. 27).","refs":[{"ref":"Art. 24.3 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"a) Jefatura de los Servicios de Apoyo. b) Jefatura de Servicios Técnicos. c) Jefatura de Asuntos Económicos."},{"ref":"Art. 26.2.d Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio de Estadística. Tiene como cometidos la elaboración y ejecución del Plan Estadístico de la Guardia Civil"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Organización periférica: Zonas, Comandancias, Compañías y Puestos.","refs":[{"ref":"Art. 1.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"las Zonas, las Comandancias, las Compañías y los Puestos."}]},{"text":"Sustituye al Director General con carácter interino o accidental: la Dirección Adjunta Operativa.","refs":[{"ref":"Art. 5.1.e Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Sustituir al Director General de la Guardia Civil, con carácter interino o accidental"}]},{"text":"Centro Universitario de la Guardia Civil: titularidad del Ministro del Interior.","refs":[{"ref":"Art. 4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"cuya titularidad corresponde al Ministro del Interior."}]},{"text":"La Sala de Operaciones y Servicios puede activarse como Centro de Crisis.","refs":[{"ref":"Art. 7.2 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"se activará como Centro de Crisis"}]},{"text":"Escolta del Director General y Registro Central: Secretaría de Despacho.","refs":[{"ref":"Art. 3.4 Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Del Jefe de la Secretaría de Despacho dependen también la Unidad de Escolta del Director General y el Registro Central"}]},{"text":"Museo y Biblioteca: Servicio de Estudios Históricos (Jefatura de Asistencia al Personal).","refs":[{"ref":"Art. 22.2.f Orden PRE/422/2013","law":"Orden PRE/422/2013","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906","quote":"Servicio de Estudios Históricos."}]},{"text":"RD 207/2024: del Director General dependen la Dirección Adjunta Operativa, el Mando de Personal y el Mando de Apoyo.","refs":[{"ref":"Art. 4.3 RD 207/2024","law":"RD 207/2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793","quote":"b) El Mando de Personal. c) El Mando de Apoyo."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-2906', null, null, null, 'Otras normas citadas: RD 207/2024 (https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793)'
  from public.topics t where t.slug = 'gc-15c-servicios-centrales-dggc'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Guardia Civil · Historia de la Guardia Civil (web oficial)', 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/', 'web_oficial'::public.source_kind, 'Guardia Civil (web oficial)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-15d-historia-guardia-civil', 'Tema 15. Historia de la Guardia Civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-15d-historia-guardia-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Antecedentes: los inicios del siglo XIX (bandolerismo, Milicia Nacional, Legión de Salvaguardias Nacionales)"},{"n":"2","title":"La Fundación (1844-1845): reales decretos, reglamentos y Cartilla"},{"n":"3","title":"La consolidación: guerras carlistas, primera misión internacional y Guardias Jóvenes"},{"n":"4","title":"Sexenio Revolucionario y Restauración Monárquica (1868-1902)"},{"n":"5","title":"El reinado de Alfonso XIII (1902-1931)"},{"n":"6","title":"La Segunda República (1931-1936)"},{"n":"7","title":"El Franquismo: supresión de Carabineros, Tráfico y especialidades"},{"n":"8","title":"La Transición y la Democracia: LO 2/1986, SEPRONA, EUROGENDFOR y normas actuales"}]'::jsonb, '["Los inicios del Siglo XIX Web de la Guardia Civil (Historia): «Desde este puesto concibe un proyecto de Instituto armado para el mantenimiento del orden público: la Legión de Salvaguardias Nacionales que, inspirada en la Gendarmería Nacional francesa, debería combatir la delincuencia y garantizar la libre circulación de bienes y personas.»","La Fundación (28/03/1844) Web de la Guardia Civil (Historia): «Así, el 28 de marzo de 1844, se produce el momento histórico de la creación oficial de la Guardia Civil cuando, por Real Decreto, se crea un “cuerpo especial de fuerza armada de Infantería y Caballería”, bajo la dependencia del Ministerio de la Gobernación y con “la denominación de Guardias Civiles”. A los efectos de organizar esta nueva fuerza se comisiona al mariscal de campo D. Francisco Javier Girón y Ezpeleta, II Duque de Ahumada.»","La Fundación (13/05/1844) Web de la Guardia Civil (Historia): «para dar lugar al definitivo Real Decreto de 13 de mayo, presentado por el Presidente de Gobierno y Ministro de la Guerra, D. Ramón María Narváez, auténtico decreto fundacional de la Guardia Civil.»","La Fundación (organización) Web de la Guardia Civil (Historia): «Inicialmente se compondrá de 14 jefes, 232 oficiales y 5769 guardias repartidos en 14 Tercios»","La Fundación (reglamentos) Web de la Guardia Civil (Historia): «El 9 de octubre de 1844 se aprobaba el Reglamento para el Servicio de la Guardia Civil, estableciendo las obligaciones y facultades de la Guardia Civil, su dependencia orgánica, vinculada en lo referido a su servicio peculiar al Ministerio de la Gobernación, y el objeto primordial de la Institución: “la conservación del orden público, la protección de las personas y las propiedades (...) y el auxilio que reclame la ejecución de las leyes”.»","La Fundación (Cartilla) Web de la Guardia Civil (Historia): «Surge así el 20 de diciembre de 1845, de la propia mano del Duque de Ahumada, un documento que constituye el auténtico código moral de la Institución: la “Cartilla del Guardia Civil”»","La Fundación (honor) Web de la Guardia Civil (Historia): «“el honor es la principal divisa del guardia civil; debe, por consiguiente, conservarlo sin mancha. Una vez perdido, no se recobra jamás”.»","La consolidación (Oporto, 1847) Web de la Guardia Civil (Historia): «Una unidad de Caballería de la Guardia Civil se encarga de patrullar y garantizar la seguridad ciudadana en la ciudad de Oporto.»","La consolidación (Guardias Jóvenes) Web de la Guardia Civil (Historia): «El 1º de abril de 1853, por Real Orden, se creará la “Compañía de Guardias Jóvenes” para dar amparo y educación a los huérfanos e hijos del Cuerpo y ayudar a la formación de nuevos guardias.»","El Reinado de Alfonso XIII (patrona) Web de la Guardia Civil (Historia): «la declaración de la Virgen del Pilar como patrona de la Guardia Civil en 1913»","El Reinado de Alfonso XIII (Beneficencia) Web de la Guardia Civil (Historia): «En 1929 mediante Real Decreto de 4 de octubre, se concede a la Guardia Civil la Gran Cruz de la Orden Civil de Beneficencia»","La Segunda República (Sanjurjada) Web de la Guardia Civil (Historia): «La conocida como Sanjurjada tiene como consecuencia que la Dirección General de la Guardia Civil dependiente del Ministerio de la Guerra se transforme en Inspección General para pasar a depender del Ministerio de Gobernación.»","El Franquismo (Carabineros) Web de la Guardia Civil (Historia): «el 15 de marzo de 1940 se promulga una Ley fundamentada en dos pilares básicos: la supresión del Cuerpo de Carabineros, al que se pone fin tras 111 años de servicio ininterrumpido, y asunción de sus funciones por la Guardia Civil»","El Franquismo (Tráfico) Web de la Guardia Civil (Historia): «Se crea la Agrupación de Tráfico de la Guardia Civil que constituye un punto de inflexión en el proceso de la modernización del Cuerpo.»","La Transición y La Democracia (LO 2/1986) Web de la Guardia Civil (Historia): «Con la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad de 13 de marzo, se define a la Guardia Civil como instituto armado de naturaleza militar»","La Transición y La Democracia (SEPRONA) Web de la Guardia Civil (Historia): «se crea en 1988 el Servicio de Protección de la Naturaleza (SEPRONA)»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Antecedentes: los inicios del siglo XIX","blocks":[{"text":"Tras la Guerra de la Independencia, la debilidad del Estado llenó de inseguridad los caminos: desde 1814 los bandoleros (excombatientes de la guerrilla, desertores y delincuentes) se adueñaron de ellos. Para combatirla, los liberales de las Cortes de Cádiz reunificaron la Milicia Nacional, disuelta por Fernando VII en 1814, reconstituida en 1820 y desaparecida en 1823 con el fin del Trienio Liberal.","refs":[{"ref":"Los inicios del Siglo XIX","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"es desde 1814 cuando se adueñan literalmente de los caminos del país."},{"ref":"Los inicios del Siglo XIX","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Ésta, pese a ser disuelta en 1814 por Fernando VII, se reconstituye nuevamente en 1820, hasta que el fin del Trienio Liberal determina su desaparición en 1823."}]},{"text":"En 1820 el teniente general Pedro Agustín Girón y de las Casas, primer duque de Ahumada, fue nombrado Ministro de la Guerra y concibió la Legión de Salvaguardias Nacionales, inspirada en la Gendarmería Nacional francesa, para combatir la delincuencia y garantizar la libre circulación de bienes y personas. Las Cortes no la aprobaron, pero el proyecto inspiró a su hijo, el segundo duque de Ahumada.","refs":[{"ref":"Los inicios del Siglo XIX","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la Legión de Salvaguardias Nacionales que, inspirada en la Gendarmería Nacional francesa, debería combatir la delincuencia y garantizar la libre circulación de bienes y personas."}]}]},{"n":"2","title":"La Fundación (1844-1845): reales decretos y organización","blocks":[{"text":"La creación oficial se produce por Real Decreto de 28 de marzo de 1844, que crea un «cuerpo especial de fuerza armada de Infantería y Caballería» dependiente del Ministerio de la Gobernación, con la denominación de Guardias Civiles. Su organización se encomienda al mariscal de campo Francisco Javier Girón y Ezpeleta, II Duque de Ahumada, que defendía la calidad sobre la cantidad: «cinco mil hombres buenos» antes que quince mil medianos.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"el 28 de marzo de 1844, se produce el momento histórico de la creación oficial de la Guardia Civil"},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"se comisiona al mariscal de campo D. Francisco Javier Girón y Ezpeleta, II Duque de Ahumada."}]},{"text":"El informe del Duque de 20 de abril de 1844 provocó la derogación del primer decreto, que ni llegó a entrar en vigor, y dio lugar al Real Decreto de 13 de mayo de 1844, presentado por Ramón María Narváez, Presidente del Gobierno y Ministro de la Guerra: es el auténtico decreto fundacional. Fijó una doble dependencia: del Ministerio de la Guerra en organización, personal, disciplina, material y haberes, y del de la Gobernación en su servicio peculiar y su movimiento. Se compondría de 14 jefes, 232 oficiales y 5.769 guardias en 14 Tercios.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"para dar lugar al definitivo Real Decreto de 13 de mayo, presentado por el Presidente de Gobierno y Ministro de la Guerra, D. Ramón María Narváez, auténtico decreto fundacional de la Guardia Civil."},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"del Ministerio de la Guerra en lo concerniente a su organización, personal, disciplina, material y percibo de sus haberes, y del Ministerio de la Gobernación en lo relativo a su servicio peculiar y su movimiento."},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Inicialmente se compondrá de 14 jefes, 232 oficiales y 5769 guardias repartidos en 14 Tercios"}]},{"text":"El 1 de septiembre de 1844, día en que el Duque fue designado Inspector General, se presentó oficialmente el Cuerpo con una parada militar de 1.870 guardias, que lucían un sombrero de tres picos de origen francés: el tricornio.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"un original sombrero de tres picos de origen francés: el tricornio"},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"El 1 de septiembre de 1844, día de la designación del Duque de Ahumada como Inspector General de la Guardia Civil, tuvo lugar la presentación oficial del Cuerpo"}]}]},{"n":"3","title":"Reglamentos y Cartilla del Guardia Civil","blocks":[{"text":"El 9 de octubre de 1844 se aprobó el Reglamento para el Servicio, que fijó el objeto primordial de la Institución: la conservación del orden público, la protección de las personas y las propiedades y el auxilio a la ejecución de las leyes. El 15 de octubre se aprobó el Reglamento Militar, elaborado por el Ministerio de la Guerra, que regula organización, ascensos, disciplina y estatuto del personal.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"El 9 de octubre de 1844 se aprobaba el Reglamento para el Servicio de la Guardia Civil"},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"El Reglamento Militar de la Guardia Civil aprobado el 15 de octubre, es elaborado por el Ministerio de la Guerra"}]},{"text":"El 20 de diciembre de 1845 el propio Duque redactó la Cartilla del Guardia Civil, auténtico código moral del Cuerpo, que sintetiza ambos reglamentos. Su artículo más famoso dice que el honor es la principal divisa del guardia civil y que, una vez perdido, no se recobra jamás. La Cartilla también le encomienda auxiliar a la población en catástrofes, siniestros y accidentes.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Surge así el 20 de diciembre de 1845, de la propia mano del Duque de Ahumada, un documento que constituye el auténtico código moral de la Institución"},{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"\"el honor es la principal divisa del guardia civil; debe, por consiguiente, conservarlo sin mancha. Una vez perdido, no se recobra jamás\"."},{"ref":"La consolidación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la propia Cartilla encomienda al guardia civil el deber de auxiliar a la población en caso de catástrofes, siniestros y accidentes."}]}]},{"n":"4","title":"La consolidación: guerras carlistas, Oporto y Guardias Jóvenes","blocks":[{"text":"El Cuerpo se consolidó durante la Segunda (1846-1849) y la Tercera Guerra Carlista (1872-1876), luchando contra guerrilla y bandolerismo. En 1847 desempeñó su primera misión internacional: una unidad de Caballería patrulló Oporto, en un Portugal en guerra civil. El bandolerismo se consideró virtualmente erradicado a finales del siglo XIX.","refs":[{"ref":"La consolidación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Una unidad de Caballería de la Guardia Civil se encarga de patrullar y garantizar la seguridad ciudadana en la ciudad de Oporto."},{"ref":"La consolidación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"se considera virtualmente erradicado a finales del s. XIX."}]},{"text":"El 1 de abril de 1853, por Real Orden, se creó la Compañía de Guardias Jóvenes para amparar y educar a los huérfanos e hijos del Cuerpo, origen del actual Colegio de Guardias Jóvenes «Duque de Ahumada».","refs":[{"ref":"La consolidación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"El 1º de abril de 1853, por Real Orden, se creará la \"Compañía de Guardias Jóvenes\" para dar amparo y educación a los huérfanos e hijos del Cuerpo y ayudar a la formación de nuevos guardias."}]}]},{"n":"5","title":"Sexenio Revolucionario y Restauración (1868-1902)","blocks":[{"text":"En el Sexenio (1868-1874) la Guardia Civil fue la institución en que se apoyaron los gobiernos: Prim suprimió la Guardia Rural para que la asumiera, Pi y Margall la hizo depender solo de Gobernación (decisión revocada después) y en enero de 1874 participó con Pavía en la disolución de la Asamblea. En la Restauración, la Ley Constitutiva del Ejército de 1878 la integró en el Ejército, y desde 1886 asumió las escoltas en trenes de viajeros. Tras el Desastre del 98 se crearon la Comandancia de Canarias y las Secciones de Ceuta y Melilla.","refs":[{"ref":"Sexenio Revolucionario","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"el Gobierno Provisional de Prim suprime la Guardia Rural con el objeto de que fuera la Guardia Civil quien asumiera las competencias correspondientes"},{"ref":"La Restauración Monárquica","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"El Cuerpo asumiría a nivel nacional el servicio de escoltas en los trenes de viajeros a partir de 1886."},{"ref":"La Restauración Monárquica","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la creación de la Comandancia de Canarias, las Secciones de Ceuta y Melilla"}]}]},{"n":"6","title":"El reinado de Alfonso XIII (1902-1931)","blocks":[{"text":"Fue una etapa de modernización: sección de ciclistas (1902), pistola Star de 9 mm (1921), Parque de Máquinas de Locomoción (mayo de 1922) y servicio radiotelegráfico (primera emisión el 1 de agosto de 1922, día en que también se estrenó el himno). La Virgen del Pilar fue declarada patrona en 1913, el primer museo se abrió en 1921 y en 1926 se crearon las Zonas, cuatro al principio.","refs":[{"ref":"El Reinado de Alfonso XIII","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la declaración de la Virgen del Pilar como patrona de la Guardia Civil en 1913"},{"ref":"El Reinado de Alfonso XIII","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"En 1926, respondiendo a un principio de regionalización, se crean las Zonas, cuatro en un principio"}]},{"text":"Por Real Decreto de 4 de octubre de 1929 se concedió a la Guardia Civil la Gran Cruz de la Orden Civil de Beneficencia por sus servicios en incendios, inundaciones y salvamentos, reconociendo su carácter «benemérito».","refs":[{"ref":"El Reinado de Alfonso XIII","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"En 1929 mediante Real Decreto de 4 de octubre, se concede a la Guardia Civil la Gran Cruz de la Orden Civil de Beneficencia"}]}]},{"n":"7","title":"La Segunda República (1931-1936)","blocks":[{"text":"La República tuvo que emplear al Cuerpo en una etapa de graves desórdenes (Castilblanco, Arnedo, Casas Viejas). Tras el alzamiento fallido del general Sanjurjo en agosto de 1932 (la Sanjurjada), la Dirección General, que dependía del Ministerio de la Guerra, se transformó en Inspección General dependiente de Gobernación. El 12 de febrero de 1935 se le concedió la Corbata de la Orden de la República. Ojo: la fuente oficial capturada tiene un salto de texto en el relato de 1934 (insurrección sofocada el 19 de octubre).","refs":[{"ref":"La Segunda República","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la Dirección General de la Guardia Civil dependiente del Ministerio de la Guerra se transforme en Inspección General para pasar a depender del Ministerio de Gobernación."},{"ref":"La Segunda República","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"concede al Instituto la Corbata de la Orden de la República el 12 de febrero de 1935"}]}]},{"n":"8","title":"El Franquismo: Carabineros, Tráfico y especialidades","blocks":[{"text":"La Ley de 15 de marzo de 1940 suprimió el Cuerpo de Carabineros, tras 111 años de servicio, y la Guardia Civil asumió sus funciones. En 1959, con el aumento del tráfico rodado, se le encomendó la vigilancia del tráfico y del transporte por carretera y se creó la Agrupación de Tráfico. Siguieron las especialidades: Montaña y actividades subacuáticas (años sesenta), helicópteros (primeros pilotos en enero de 1973) y desactivación de explosivos (1974).","refs":[{"ref":"El Franquismo","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la supresión del Cuerpo de Carabineros, al que se pone fin tras 111 años de servicio ininterrumpido, y asunción de sus funciones por la Guardia Civil"},{"ref":"El Franquismo","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"En este mismo año, dado el aumento del tráfico rodado que se produce como consecuencia del crecimiento económico, se encomienda a la Guardia Civil la vigilancia del tráfico y del transporte por carretera."}]}]},{"n":"9","title":"La Transición y la Democracia","blocks":[{"text":"El Real Decreto 3543/1981, de 30 de octubre, creó el guardia civil auxiliar como voluntariado especial. La LO 2/1986 definió a la Guardia Civil como instituto armado de naturaleza militar con doble dependencia de Interior y Defensa. En 1988 se crearon el SEPRONA y la Agrupación de Reserva y Seguridad, y en 1991 el Servicio Marítimo.","refs":[{"ref":"La Transición y La Democracia","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"por Real Decreto 3543/1981, de 30 de octubre se crea la figura del guardia civil auxiliar, como una modalidad de voluntariado especial."},{"ref":"La Transición y La Democracia","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"se crea en 1988 el Servicio de Protección de la Naturaleza (SEPRONA)"}]},{"text":"Desde 2005 participa en la Fuerza de Gendarmería Europea (EUROGENDFOR) con las policías de naturaleza militar de Francia, Holanda, Italia, Portugal y Rumania. En 2007 se aprobaron la LO 11/2007 (derechos y deberes) y la LO 12/2007 (régimen disciplinario); en 2022, el Código de Conducta (RD 176/2022); y en 2020 María Gámez fue la primera mujer Directora General.","refs":[{"ref":"La Transición y La Democracia","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Desde su entrada en servicio en 2005, la Guardia Civil participa en la Fuerza de Gendarmería Europea (EUROGENDFOR) junto con fuerzas de policía de naturaleza militar: de Francia, Holanda, Italia, Portugal y Rumania."},{"ref":"La Transición y La Democracia","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Se convierte en la primera mujer al frente de la institución"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Creación oficial: Real Decreto de 28 de marzo de 1844; decreto fundacional: 13 de mayo de 1844 (Narváez).","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"auténtico decreto fundacional de la Guardia Civil."}]},{"text":"Organización inicial: 14 Tercios.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"repartidos en 14 Tercios"}]},{"text":"Reglamentos: Servicio (9-10-1844) y Militar (15-10-1844); Cartilla: 20-12-1845.","refs":[{"ref":"La Fundación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Reglamento Militar de la Guardia Civil aprobado el 15 de octubre"}]},{"text":"Primera misión internacional: Oporto, 1847.","refs":[{"ref":"La consolidación","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"la ciudad de Oporto."}]},{"text":"Patrona, Virgen del Pilar: 1913; Gran Cruz de Beneficencia: 1929.","refs":[{"ref":"El Reinado de Alfonso XIII","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"patrona de la Guardia Civil en 1913"}]},{"text":"Carabineros suprimidos en 1940; Agrupación de Tráfico en 1959; SEPRONA en 1988.","refs":[{"ref":"El Franquismo","law":"Web de la Guardia Civil (Historia)","url":"https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/","quote":"Se crea la Agrupación de Tráfico de la Guardia Civil"}]}]}]'::jsonb, (select id from public.sources where url = 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/'), 'https://web.guardiacivil.es/es/institucional/conocenos/historiaguacivil/', null, null, null, null
  from public.topics t where t.slug = 'gc-15d-historia-guardia-civil'
