insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 17/2015, de 9 de julio, del Sistema Nacional de Protección Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7730', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
