insert into public.sources (title, url, kind, publisher, published_on) values ('Directiva 2012/27/UE, relativa a la eficiencia energética (texto consolidado a 4.5.2023, capítulos I y II), derogada con efectos desde el 12.10.2025 por la Directiva (UE) 2023/1791 (versión refundida)', 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504', 'web_oficial'::public.source_kind, 'Unión Europea · EUR-Lex (DOUE L 315 de 14.11.2012 y modificaciones)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-16b-eficiencia-energetica', 'Tema 16. Eficiencia energética: Directiva 2012/27/UE (capítulos I y II)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-16b-eficiencia-energetica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Directiva 2012/27/UE, relativa a la eficiencia energética: vigencia (derogada desde el 12.10.2025 por la Directiva (UE) 2023/1791, versión refundida)"},{"n":"2","title":"Capítulo I: objeto, ámbito de aplicación, definiciones y objetivos (arts. 1-3)"},{"n":"2.1","title":"Objeto y objetivos principales para 2020 y 2030 (art. 1)"},{"n":"2.2","title":"Definiciones (art. 2)"},{"n":"2.3","title":"Objetivos y contribuciones nacionales (art. 3)"},{"n":"3","title":"Capítulo II: eficiencia del uso de energía (arts. 5-13)"},{"n":"3.1","title":"Función ejemplarizante de los edificios de los organismos públicos (art. 5)"},{"n":"3.2","title":"Adquisición por los organismos públicos (art. 6)"},{"n":"3.3","title":"Obligación de ahorro de energía y sistemas de obligaciones (arts. 7 y 7 bis)"},{"n":"3.4","title":"Auditorías energéticas y sistemas de gestión energética (art. 8)"},{"n":"3.5","title":"Medición, facturación e información a los consumidores; sanciones (arts. 9-13)"}]'::jsonb, '["Art. 1.1 Directiva 2012/27/UE: «La presente Directiva establece un marco común de medidas para el fomento de la eficiencia energética dentro de la Unión a fin de garantizar la consecución de los objetivos principales en materia de eficiencia energética de la Unión, que consisten en un aumento de la eficiencia energética del 20 % para 2020 y de al menos el 32,5 % para 2030»","Art. 1.1 Directiva 2012/27/UE: «La presente Directiva contribuye a la aplicación del principio «primero, la eficiencia energética».»","Art. 1.2 Directiva 2012/27/UE: «Los requisitos que establece la presente Directiva son requisitos mínimos y se entienden sin perjuicio de que cualquier Estado miembro mantenga o introduzca medidas más estrictas.»","Art. 2.4 Directiva 2012/27/UE: ««eficiencia energética»: la relación entre la producción de un rendimiento, servicio, bien o energía, y el gasto de energía;»","Art. 2.25 Directiva 2012/27/UE: ««auditoría energética»: todo procedimiento sistemático destinado a obtener conocimientos adecuados del perfil de consumo de energía existente de un edificio o grupo de edificios, de una instalación u operación industrial o comercial, o de un servicio privado o público, así como para determinar y cuantificar las posibilidades de ahorro de energía a un coste eficiente e informar al respecto;»","Art. 2.30 Directiva 2012/27/UE: ««cogeneración»: la generación simultánea de energía térmica y de energía eléctrica o mecánica en un solo proceso;»","Art. 3.5 Directiva 2012/27/UE: «En la fijación de esas contribuciones, los Estados miembros tendrán en cuenta que el consumo de energía de la Unión en 2030 no deberá exceder de 1 128 Mtep de energía primaria y/o de 846 Mtep de energía final.»","Art. 5.1 Directiva 2012/27/UE: «cada uno de los Estados miembros se asegurará de que, a partir del 1 de enero de 2014, el 3 % de la superficie total de los edificios con calefacción y/o sistema de refrigeración que tenga en propiedad y ocupe su Administración central se renueve cada año»","Art. 5.1 Directiva 2012/27/UE: «Dicho límite bajará a 250 m2 a partir del 9 de julio de 2015.»","Art. 6.1 Directiva 2012/27/UE: «Los Estados miembros garantizarán que las Administraciones centrales adquieran solamente productos, servicios y edificios que tengan un alto rendimiento energético»","Art. 7.1.b) Directiva 2012/27/UE: «b) la consecución de un nuevo ahorro cada año, desde el 1 de enero de 2021 hasta el 31 de diciembre de 2030, del 0,8 % del consumo anual de energía final, como promedio de los últimos tres años previos al 1 de enero de 2019.»","Art. 8.4 Directiva 2012/27/UE: «Los Estados miembros velarán por que se someta a las empresas que no sean PYME a una auditoría energética realizada de manera independiente y con una buena rentabilidad por expertos cualificados y/o acreditados o ejecutada y supervisada por autoridades independientes con arreglo al Derecho nacional a más tardar el 5 de diciembre de 2015, y como mínimo cada cuatro años a partir de la fecha de la auditoría energética anterior.»","Art. 11 bis.1 Directiva 2012/27/UE: «Los Estados miembros velarán por que los usuarios finales reciban de forma gratuita la totalidad de sus facturas y la información sobre la facturación del consumo de energía y de que tengan un acceso adecuado y gratuito a los datos sobre su consumo.»","Art. 13 Directiva 2012/27/UE: «Las sanciones previstas deberán ser eficaces, proporcionadas y disuasorias.»","Art. 38 Directiva (UE) 2023/1791 Directiva 2012/27/UE: «Queda derogada con efectos a partir del 12 de octubre de 2025 la Directiva 2012/27/UE, en su versión modificada por los actos citados en el anexo XVI, parte A»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Vigencia: una directiva ya derogada","blocks":[{"text":"Ojo antes de estudiar: el temario cita la Directiva 2012/27/UE, pero la Directiva (UE) 2023/1791, versión refundida sobre eficiencia energética, la deroga con efectos desde el 12 de octubre de 2025; las referencias a la antigua se entienden hechas a la nueva según una tabla de correspondencias. Estos apuntes siguen el texto consolidado de 2012/27/UE (versión de 04.05.2023), que es el que pide el temario. En el examen pueden preguntar tanto su contenido como la fecha de derogación.","refs":[{"ref":"Art. 38 Directiva (UE) 2023/1791","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Queda derogada con efectos a partir del 12 de octubre de 2025 la Directiva 2012/27/UE"},{"ref":"Art. 38 Directiva (UE) 2023/1791","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Las referencias a la Directiva derogada se entenderán hechas a la presente Directiva con arreglo a la tabla de correspondencias que figura en el anexo XVII."}]}]},{"n":"2","title":"Objeto y objetivos principales para 2020 y 2030 (art. 1)","blocks":[{"text":"La Directiva crea un marco común de medidas para fomentar la eficiencia energética en la Unión y alcanzar sus objetivos principales: un aumento de la eficiencia energética del 20 % para 2020 y de al menos el 32,5 % para 2030. Contribuye a aplicar el principio «primero, la eficiencia energética».","refs":[{"ref":"Art. 1.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"que consisten en un aumento de la eficiencia energética del 20 % para 2020 y de al menos el 32,5 % para 2030"},{"ref":"Art. 1.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"La presente Directiva contribuye a la aplicación del principio «primero, la eficiencia energética»."}]},{"text":"Sus requisitos son mínimos: cada Estado puede mantener o introducir medidas más estrictas, que deben ser compatibles con el Derecho de la Unión y notificarse a la Comisión (art. 1.2).","refs":[{"ref":"Art. 1.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Los requisitos que establece la presente Directiva son requisitos mínimos y se entienden sin perjuicio de que cualquier Estado miembro mantenga o introduzca medidas más estrictas. Tales medidas deberán ser compatibles con el Derecho de la Unión."}]}]},{"n":"3","title":"Definiciones (art. 2)","blocks":[{"text":"«Eficiencia energética» es la relación entre la producción de un rendimiento, servicio, bien o energía y el gasto de energía. «Administración central» son todos los órganos administrativos cuya competencia se extiende a todo el territorio de un Estado miembro. La «auditoría energética» es un procedimiento sistemático para conocer el perfil de consumo de un edificio, instalación o servicio y cuantificar sus posibilidades de ahorro rentable.","refs":[{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"«eficiencia energética»: la relación entre la producción de un rendimiento, servicio, bien o energía, y el gasto de energía;"},{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"«Administración central»: todos los órganos administrativos cuya competencia se extiende a la totalidad del territorio de un Estado miembro;"},{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"«auditoría energética»: todo procedimiento sistemático destinado a obtener conocimientos adecuados del perfil de consumo de energía existente"}]},{"text":"Son PYME las empresas de menos de 250 personas con volumen de negocios anual no superior a 50 millones de euros o balance no superior a 43 millones. «Cogeneración» es la generación simultánea de energía térmica y eléctrica o mecánica en un solo proceso, y una «unidad de microgeneración» es la de cogeneración con potencia máxima inferior a 50 kWe. Un «sistema urbano eficiente de calefacción y refrigeración» usa al menos un 50 % de renovables, un 50 % de calor residual, un 75 % de calor cogenerado o un 50 % de combinación de ellos.","refs":[{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"la categoría de microempresas, pequeñas y medianas empresas está constituida por las empresas que ocupan a menos de 250 personas y cuyo volumen de negocios anual no excede de 50 millones EUR o cuyo balance general anual no excede de 43 millones EUR;"},{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"«cogeneración»: la generación simultánea de energía térmica y de energía eléctrica o mecánica en un solo proceso;"},{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"«unidad de microgeneración»: unidad de cogeneración con una potencia máxima inferior a los 50 kWe;"},{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"que utilice al menos un 50 % de energía renovable, un 50 % de calor residual, un 75 % de calor cogenerado o un 50 % de una combinación de estos tipos de energía y calor;"}]}]},{"n":"4","title":"Objetivos y contribuciones nacionales (art. 3)","blocks":[{"text":"Cada Estado fija un objetivo nacional orientativo de eficiencia energética y lo notifica a la Comisión. Para 2020 se tenía en cuenta que el consumo de la Unión no superase 1.483 Mtep de energía primaria o 1.086 Mtep de energía final. Para 2030, los Estados fijan contribuciones orientativas teniendo en cuenta que el consumo de la Unión no debe exceder de 1.128 Mtep de energía primaria y/o 846 Mtep de energía final.","refs":[{"ref":"Art. 3.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"que el consumo de energía de la Unión en 2020 no ha de ser superior a 1 483 Mtep de energía primaria o a 1 086 Mtep de energía final;"},{"ref":"Art. 3.5 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"el consumo de energía de la Unión en 2030 no deberá exceder de 1 128 Mtep de energía primaria y/o de 846 Mtep de energía final."}]}]},{"n":"5","title":"Función ejemplarizante de los edificios públicos (art. 5)","blocks":[{"text":"Desde el 1 de enero de 2014, cada año debe renovarse el 3 % de la superficie total de los edificios con calefacción y/o refrigeración que la Administración central tenga en propiedad y ocupe, para cumplir los requisitos mínimos de rendimiento energético. Ese 3 % se calcula sobre los edificios de más de 500 m2 útiles, límite que bajó a 250 m2 desde el 9 de julio de 2015. Se da prioridad a los edificios con peor rendimiento.","refs":[{"ref":"Art. 5.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"a partir del 1 de enero de 2014, el 3 % de la superficie total de los edificios con calefacción y/o sistema de refrigeración que tenga en propiedad y ocupe su Administración central se renueve cada año"},{"ref":"Art. 5.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Dicho límite bajará a 250 m2 a partir del 9 de julio de 2015."}]},{"text":"Los Estados pueden excluir los edificios protegidos por su valor arquitectónico o histórico, los de defensa nacional (salvo alojamientos y oficinas) y los lugares de culto y actividades religiosas (art. 5.2). Si un año se renueva más del 3 %, el exceso puede computarse en cualquiera de los tres años anteriores o siguientes (art. 5.3).","refs":[{"ref":"Art. 5.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"c) edificios utilizados como lugares de culto y para actividades religiosas."},{"ref":"Art. 5.3 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"podrá computar el exceso en el índice de renovación anual de cualquiera de los tres años anteriores o siguientes."}]}]},{"n":"6","title":"Adquisición por los organismos públicos (art. 6)","blocks":[{"text":"Las Administraciones centrales solo pueden adquirir productos, servicios y edificios de alto rendimiento energético, en la medida en que sea coherente con la rentabilidad, la viabilidad económica, la sostenibilidad, la idoneidad técnica y una competencia suficiente. En las fuerzas armadas solo se aplica si no choca con sus fines, y no afecta al suministro de equipo militar.","refs":[{"ref":"Art. 6.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Los Estados miembros garantizarán que las Administraciones centrales adquieran solamente productos, servicios y edificios que tengan un alto rendimiento energético, en la medida en que ello sea coherente con la rentabilidad, la viabilidad económica, la sostenibilidad en un sentido más amplio, la idoneidad técnica, así como una competencia suficiente"},{"ref":"Art. 6.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"La obligación no se aplicará a los contratos de suministro de equipo militar"}]}]},{"n":"7","title":"Obligación de ahorro y sistemas de obligaciones (arts. 7 y 7 bis)","blocks":[{"text":"Los Estados deben lograr un ahorro acumulado de energía final: del 1,5 % anual de las ventas a clientes finales entre 2014 y 2020, y del 0,8 % anual del consumo de energía final entre el 1 de enero de 2021 y el 31 de diciembre de 2030, calculado sobre el promedio de los tres años previos a 2019 (Chipre y Malta, 0,24 %). Pueden cumplirlo mediante sistemas de obligaciones que recaen en distribuidores y comercializadores de energía (art. 7 bis).","refs":[{"ref":"Art. 7.1.b Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"la consecución de un nuevo ahorro cada año, desde el 1 de enero de 2021 hasta el 31 de diciembre de 2030, del 0,8 % del consumo anual de energía final, como promedio de los últimos tres años previos al 1 de enero de 2019."},{"ref":"Art. 7 bis.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"los Estados miembros designarán a las partes obligadas entre los distribuidores de energía, las empresas minoristas de venta de energía y los distribuidores o minoristas de combustible para transporte"}]}]},{"n":"8","title":"Auditorías energéticas (art. 8)","blocks":[{"text":"Las empresas que no son PYME debían someterse a una auditoría energética independiente a más tardar el 5 de diciembre de 2015 y, como mínimo, cada cuatro años desde la anterior. Quedan exentas las que apliquen un sistema de gestión energética o ambiental certificado por un organismo independiente que incluya una auditoría conforme al anexo VI. Para las PYME, los Estados elaboran programas de fomento.","refs":[{"ref":"Art. 8.4 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"a más tardar el 5 de diciembre de 2015, y como mínimo cada cuatro años a partir de la fecha de la auditoría energética anterior."},{"ref":"Art. 8.6 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Se eximirá del cumplimiento de los requisitos establecidos en el apartado 4 a aquellas empresas que no sean PYME y que apliquen un sistema de gestión energética o ambiental"},{"ref":"Art. 8.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Los Estados miembros elaborarán programas que alienten a las PYME a realizar auditorías energéticas"}]}]},{"n":"9","title":"Medición, facturación, información y sanciones (arts. 9-13)","blocks":[{"text":"Los clientes finales deben recibir contadores individuales a precio competitivo que reflejen su consumo real (arts. 9 y 9 bis). Los contadores instalados después del 25 de octubre de 2020 deben ser de lectura remota, y los ya instalados deben adaptarse o sustituirse a más tardar el 1 de enero de 2027, salvo que no sea rentable (art. 9 quater). Las facturas y la información de consumo son gratuitas (art. 11 bis), y los Estados promueven el uso eficiente entre los pequeños clientes (art. 12). Las sanciones por incumplimiento deben ser eficaces, proporcionadas y disuasorias (art. 13).","refs":[{"ref":"Art. 9 quater.2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"se dotarán de lectura remota o serán sustituidos por dispositivos de lectura remota a más tardar el 1 de enero de 2027"},{"ref":"Art. 11 bis.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Los Estados miembros velarán por que los usuarios finales reciban de forma gratuita la totalidad de sus facturas"},{"ref":"Art. 13 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Las sanciones previstas deberán ser eficaces, proporcionadas y disuasorias."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Objetivos de la Unión: 20 % en 2020 y al menos 32,5 % en 2030.","refs":[{"ref":"Art. 1.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"del 20 % para 2020 y de al menos el 32,5 % para 2030"}]},{"text":"Techo 2030: 1.128 Mtep primaria y/o 846 Mtep final.","refs":[{"ref":"Art. 3.5 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"1 128 Mtep de energía primaria y/o de 846 Mtep de energía final."}]},{"text":"Renovación anual del 3 % de edificios de la Administración central; umbral de 250 m2 desde el 9-7-2015.","refs":[{"ref":"Art. 5.1 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"Dicho límite bajará a 250 m2"}]},{"text":"Ahorro anual 2021-2030: 0,8 % del consumo de energía final.","refs":[{"ref":"Art. 7.1.b Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"del 0,8 % del consumo anual de energía final"}]},{"text":"Auditoría de empresas no PYME: al menos cada cuatro años.","refs":[{"ref":"Art. 8.4 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"como mínimo cada cuatro años"}]},{"text":"Microgeneración: menos de 50 kWe.","refs":[{"ref":"Art. 2 Directiva 2012/27/UE","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"inferior a los 50 kWe"}]},{"text":"Derogada desde el 12 de octubre de 2025 por la Directiva (UE) 2023/1791.","refs":[{"ref":"Art. 38 Directiva (UE) 2023/1791","law":"Directiva 2012/27/UE","url":"https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504","quote":"con efectos a partir del 12 de octubre de 2025"}]}]}]'::jsonb, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504'), 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:02012L0027-20230504', null, null, null, null
  from public.topics t where t.slug = 'gc-16b-eficiencia-energetica'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 11/2022, de 28 de junio, General de Telecomunicaciones (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-17-tecnologias-informacion', 'Tema 17. Telecomunicaciones, TIC en la AGE, servicios de confianza e interoperabilidad') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-17-tecnologias-informacion' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ley 11/2022: objeto, servicios de interés general y objetivos (título I, arts. 1-3)"},{"n":"1.1","title":"Servicios para la seguridad nacional, la defensa, la seguridad pública y la protección civil (art. 4)"},{"n":"2","title":"Salvaguardia de derechos fundamentales y secreto de las comunicaciones (título III, cap. III, arts. 56-59)"},{"n":"2.1","title":"Protección de datos, cifrado e integridad y seguridad de las redes (arts. 60-63)"},{"n":"3","title":"RD 806/2014: objeto y ámbito (cap. I, arts. 1-2)"},{"n":"4","title":"Modelo de gobernanza TIC: Estrategia TIC, medios compartidos y unidades TIC (cap. III, arts. 9-13)"},{"n":"5","title":"Ley 6/2020: disposiciones generales (título I, arts. 1-3)"},{"n":"6","title":"Certificados electrónicos: vigencia, revocación e identificación (título II, arts. 4-7)"},{"n":"7","title":"Obligaciones y responsabilidad de los prestadores de servicios de confianza (título III, arts. 8-13)"},{"n":"8","title":"El DNI y sus certificados electrónicos (disp. adic. 3.ª)"},{"n":"9","title":"Esquema Nacional de Interoperabilidad: objeto, principios y dimensiones (RD 4/2010, arts. 1-15)"}]'::jsonb, '["Art. 2 Ley 11/2022: «1. Las telecomunicaciones son servicios de interés general que se prestan en régimen de libre competencia. 2. Sólo tienen la consideración de servicio público o están sometidos a obligaciones de servicio público los servicios regulados en el artículo 4 y en el título III, respectivamente.»","Art. 4.2 Ley 11/2022: «Las redes, servicios, instalaciones y equipos de telecomunicaciones que desarrollen actividades esenciales para la seguridad y defensa nacionales integran los medios destinados a éstas, se reservan al Estado y se rigen por su normativa específica.»","Art. 58.1 Ley 11/2022: «Los operadores que suministren redes públicas de comunicaciones electrónicas o que presten servicios de comunicaciones electrónicas disponibles al público deberán garantizar el secreto de las comunicaciones de conformidad con los artículos 18.3 y 55.2 de la Constitución, debiendo adoptar las medidas técnicas necesarias.»","Art. 61 Ley 11/2022: «La conservación y cesión de los datos generados o tratados en el marco de la prestación de servicios de comunicaciones electrónicas o de redes públicas de comunicación a los agentes facultados a través de la correspondiente autorización judicial con fines de detección, investigación y enjuiciamiento de delitos graves contemplados en el Código Penal o en las leyes penales especiales se rige por lo establecido en la Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones.»","Art. 62.1-2 Ley 11/2022: «1. Cualquier tipo de información que se transmita por redes de comunicaciones electrónicas podrá ser protegida mediante procedimientos de cifrado. 2. El cifrado es un instrumento de seguridad de la información.»","Art. 1 RD 806/2014: «El objeto de este real decreto es el desarrollo y ejecución de un modelo común de gobernanza de las Tecnologías de la Información y las Comunicaciones (TIC) en la Administración General del Estado y sus Organismos Públicos.»","Art. 10.3 RD 806/2014: «La utilización de los medios y servicios compartidos será de carácter obligatorio y sustitutivo respecto a los medios y servicios particulares empleados por las distintas unidades.»","Art. 12.1 RD 806/2014: «Son unidades TIC aquellas unidades administrativas cuya función sea la provisión de servicios en materia de Tecnologías de la Información y Comunicaciones a sí mismas o a otras unidades administrativas.»","Art. 3.1 Ley 6/2020: «Los documentos electrónicos públicos, administrativos y privados, tienen el valor y la eficacia jurídica que corresponda a su respectiva naturaleza, de conformidad con la legislación que les resulte aplicable.»","Art. 4 Ley 6/2020: «1. Los certificados electrónicos se extinguen por caducidad a la expiración de su período de vigencia, o mediante revocación por los prestadores de servicios electrónicos de confianza en los supuestos previstos en el artículo siguiente. 2. El período de vigencia de los certificados cualificados no será superior a cinco años.»","Art. 9.2 Ley 6/2020: «Los prestadores de servicios de confianza que expidan certificados electrónicos deberán disponer de un servicio de consulta sobre el estado de validez o revocación de los certificados emitidos accesible al público.»","DA 3.ª.2 Ley 6/2020: «Todas las personas físicas o jurídicas, públicas o privadas, reconocerán la eficacia del Documento Nacional de Identidad para acreditar la identidad y los demás datos personales del titular que consten en el mismo, así como la identidad del firmante y la integridad de los documentos firmados con sus certificados electrónicos.»","Art. 6 RD 4/2010: «La interoperabilidad se entenderá contemplando sus dimensiones organizativa, semántica y técnica.»","Art. 11.1 RD 4/2010: «Las Administraciones públicas usarán estándares abiertos, así como, en su caso y de forma complementaria, estándares que sean de uso generalizado por los ciudadanos, al objeto de garantizar la independencia en la elección de alternativas tecnológicas por los ciudadanos y las Administraciones públicas y la adaptabilidad al progreso de la tecnología»","Art. 13.1 RD 4/2010: «La Red SARA prestará la citada Red de comunicaciones de las Administraciones públicas españolas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Ley 11/2022: objeto, servicios de interés general y objetivos (título I, arts. 1-3)","blocks":[{"text":"La Ley 11/2022, General de Telecomunicaciones, regula las telecomunicaciones en sentido amplio: la instalación y explotación de redes de comunicaciones electrónicas, la prestación de los servicios, sus recursos y servicios asociados, los equipos radioeléctricos y los equipos terminales, al amparo de la competencia exclusiva del Estado del artículo 149.1.21.ª CE (art. 1.1). También se aplica al dominio público radioeléctrico que utilicen todas las redes, públicas o no. Quedan fuera los servicios de comunicación audiovisual, las plataformas de intercambio de vídeos, los contenidos audiovisuales y los servicios de la sociedad de la información de la Ley 34/2002, salvo que sean a la vez servicios de comunicaciones electrónicas (art. 1.2).","refs":[{"ref":"Art. 1.1 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"El objeto de esta ley es la regulación de las telecomunicaciones, que comprende la instalación y explotación de las redes de comunicaciones electrónicas, la prestación de los servicios de comunicaciones electrónicas, sus recursos y servicios asociados, los equipos radioeléctricos y los equipos terminales de telecomunicación, de conformidad con el artículo 149.1.21.ª de la Constitución."},{"ref":"Art. 1.2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"Quedan excluidos del ámbito de esta ley los servicios de comunicación audiovisual, los servicios de intercambio de vídeos a través de plataforma, los contenidos audiovisuales transmitidos a través de las redes"}]},{"text":"La idea central del título I es que las telecomunicaciones son servicios de interés general que se prestan en régimen de libre competencia (art. 2.1). No son, por tanto, un servicio público con carácter general: solo tienen la consideración de servicio público los servicios del artículo 4 (seguridad nacional, defensa, seguridad pública, seguridad vial y protección civil), y solo están sometidos a obligaciones de servicio público los regulados en el título III, entre ellas el servicio universal (art. 2.2).","refs":[{"ref":"Art. 2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"1. Las telecomunicaciones son servicios de interés general que se prestan en régimen de libre competencia. 2. Sólo tienen la consideración de servicio público o están sometidos a obligaciones de servicio público los servicios regulados en el artículo 4 y en el título III, respectivamente."}]},{"text":"El artículo 3 enumera trece objetivos y principios (letras a a m). Entre ellos: fomentar la competencia efectiva y sostenible; desarrollar la economía y el empleo digital; promover el despliegue de redes de muy alta capacidad; fomentar la neutralidad tecnológica en la regulación; garantizar las obligaciones de servicio público, en especial el servicio universal; y defender los intereses de los usuarios, salvaguardando la no discriminación, el honor y la intimidad, la protección de la juventud y la infancia, de las personas con discapacidad, de los datos personales y el secreto de las comunicaciones.","refs":[{"ref":"Art. 3.i) Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"i) fomentar la neutralidad tecnológica en la regulación;"},{"ref":"Art. 3.k) Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"En la prestación de estos servicios deben salvaguardarse los imperativos constitucionales de no discriminación, de respeto a los derechos al honor y a la intimidad, la protección a la juventud y a la infancia, la protección a las personas con discapacidad, la protección de los datos personales y el secreto en las comunicaciones;"}]}]},{"n":"2","title":"Servicios para la seguridad nacional, la defensa, la seguridad pública y la protección civil (art. 4)","blocks":[{"text":"El artículo 4 es el único que califica servicios como servicio público (art. 4.1). Las redes, servicios, instalaciones y equipos que desarrollen actividades esenciales para la seguridad y la defensa nacionales se reservan al Estado y se rigen por su normativa específica (art. 4.2). El ministerio competente en telecomunicaciones ejecuta la política de defensa nacional en el sector, coordinado con el Ministerio de Defensa, y en orden público, seguridad pública, seguridad vial y protección civil coopera con el Ministerio del Interior y con las comunidades autónomas competentes (art. 4.3 y 4.4). Ojo: la ley sigue citando al «Ministerio de Asuntos Económicos y Transformación Digital»; la denominación del departamento ha podido cambiar en reestructuraciones posteriores.","refs":[{"ref":"Art. 4.1 y 4.2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"1. Sólo tienen la consideración de servicio público los servicios regulados en este artículo. 2. Las redes, servicios, instalaciones y equipos de telecomunicaciones que desarrollen actividades esenciales para la seguridad y defensa nacionales integran los medios destinados a éstas, se reservan al Estado y se rigen por su normativa específica."},{"ref":"Art. 4.4 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"En los ámbitos del orden público, la seguridad pública, seguridad vial y de la protección civil, en su específica relación con el uso de las telecomunicaciones, el Ministerio de Asuntos Económicos y Transformación Digital cooperará con el Ministerio del Interior y con los órganos responsables de las Comunidades Autónomas con competencias sobre las citadas materias."}]},{"text":"Con carácter excepcional y transitorio, el Gobierno puede asumir la gestión directa de determinados servicios o la explotación de ciertas redes para garantizar la seguridad pública y la seguridad nacional, sin vulnerar nunca los derechos fundamentales (art. 4.6). Es un dato clásico de examen el control judicial: el Gobierno comunica el acuerdo en 24 horas al órgano jurisdiccional competente, que en 48 horas establece si es acorde con los derechos fundamentales y, si no lo es, lo anula.","refs":[{"ref":"Art. 4.6 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"En ningún caso esta intervención podrá suponer una vulneración de los derechos fundamentales y libertades públicas reconocidas en el ordenamiento jurídico."},{"ref":"Art. 4.6 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"deberán ser comunicados por el Gobierno en el plazo de veinticuatro horas al órgano jurisdiccional competente para que, en un plazo de cuarenta y ocho horas, establezca si los mismos resultan acordes con los derechos fundamentales y libertades públicas reconocidas en el ordenamiento jurídico, procediendo a su anulación en caso negativo."}]}]},{"n":"3","title":"Salvaguardia de derechos fundamentales y secreto de las comunicaciones (arts. 56-59)","blocks":[{"text":"Cualquier medida sobre el acceso o el uso de servicios y aplicaciones por los usuarios finales debe respetar los derechos fundamentales (CEDH, Carta de Derechos Fundamentales de la UE y Constitución). Si puede restringirlos, solo cabe si es adecuada, necesaria y proporcionada en una sociedad democrática, respetando la presunción de inocencia, la intimidad, la libertad de expresión y la tutela judicial efectiva mediante un procedimiento previo, justo e imparcial (art. 56). Además, los operadores no pueden imponer condiciones distintas por nacionalidad, residencia o lugar de establecimiento del usuario sin justificación objetiva (art. 57).","refs":[{"ref":"Art. 56.2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"solo podrá imponerse si es adecuada, necesaria y proporcionada en una sociedad democrática"},{"ref":"Art. 57 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"por motivos relacionados con la nacionalidad, el lugar de residencia o el lugar de establecimiento del usuario final, a menos que dicho trato diferente se justifique de forma objetiva."}]},{"text":"Los operadores deben garantizar el secreto de las comunicaciones conforme a los artículos 18.3 y 55.2 CE y adoptar las medidas técnicas necesarias (art. 58.1). Los que suministran redes públicas o prestan servicios interpersonales basados en numeración o de acceso a internet están obligados a realizar las interceptaciones autorizadas judicialmente (LECrim, LO 2/2002 de control judicial del CNI y otras leyes orgánicas) y a adoptar a su costa las medidas del artículo (art. 58.2). Deben entregar al agente facultado solo los datos incluidos en la orden de interceptación legal (art. 58.8) y, si aplican compresión o cifrado reversibles, entregar las comunicaciones desprovistas de esos efectos (art. 58.11).","refs":[{"ref":"Art. 58.1 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"deberán garantizar el secreto de las comunicaciones de conformidad con los artículos 18.3 y 55.2 de la Constitución, debiendo adoptar las medidas técnicas necesarias."},{"ref":"Art. 58.2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"están obligados a realizar las interceptaciones que se autoricen judicialmente […] Asimismo, deberán adoptar a su costa las medidas que se establecen en este artículo y en los reglamentos correspondientes."},{"ref":"Art. 58.8 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"Los sujetos obligados deberán facilitar al agente facultado, de entre los datos previstos en los apartados 5, 6 y 7 de este artículo, sólo aquéllos que estén incluidos en la orden de interceptación legal."}]},{"text":"Distinta es la interceptación técnica que hace la propia Administración de telecomunicaciones para controlar el dominio público radioeléctrico o localizar interferencias (art. 59). Sus sistemas deben diseñarse para reducir al mínimo el riesgo de afectar a los contenidos; si queda constancia de contenidos, los soportes se custodian hasta que acabe el expediente sancionador o se destruyen inmediatamente, y nunca pueden divulgarse.","refs":[{"ref":"Art. 59.1.b) Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"los soportes en los que éstos aparezcan deberán ser custodiados hasta la finalización, en su caso, del expediente sancionador que hubiera lugar o, en otro caso, destruidos inmediatamente. En ninguna circunstancia podrán ser objeto de divulgación."}]}]},{"n":"4","title":"Protección de datos, conservación de datos, cifrado e integridad de las redes (arts. 60-63)","blocks":[{"text":"Los operadores deben adoptar medidas técnicas y de gestión para proteger los datos personales: que solo el personal autorizado acceda a ellos, protegerlos frente a destrucción, pérdida o acceso ilícitos y aplicar una política de seguridad (art. 60.1). Si hay una violación de datos personales, el operador la notifica sin dilaciones indebidas a la Agencia Española de Protección de Datos y, si puede afectar negativamente a la intimidad del abonado o particular, también a este (art. 60.3).","refs":[{"ref":"Art. 60.3 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"En caso de violación de los datos personales, el operador de servicios de comunicaciones electrónicas disponibles al público notificará sin dilaciones indebidas dicha violación a la Agencia Española de Protección de Datos."}]},{"text":"La conservación y cesión de datos de comunicaciones a los agentes facultados, con autorización judicial y para delitos graves, se rige por la Ley 25/2007 (art. 61). Cualquier información puede protegerse mediante cifrado, que la ley define como instrumento de seguridad de la información; en casos justificados de seguridad del Estado, seguridad pública o investigación de delitos puede obligarse a facilitar los algoritmos a la Administración, que tratará esa información con la máxima confidencialidad (art. 62).","refs":[{"ref":"Art. 61 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"se rige por lo establecido en la Ley 25/2007, de 18 de octubre, de conservación de datos relativos a las comunicaciones electrónicas y a las redes públicas de comunicaciones."},{"ref":"Art. 62.1-2 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"1. Cualquier tipo de información que se transmita por redes de comunicaciones electrónicas podrá ser protegida mediante procedimientos de cifrado. 2. El cifrado es un instrumento de seguridad de la información."}]},{"text":"Los operadores gestionan los riesgos de seguridad y garantizan la integridad de sus redes (art. 63). Notifican al ministerio los incidentes con impacto significativo, valorado según usuarios afectados, duración, área geográfica, grado de afectación y alcance económico y social. El ministerio informa, cuando proceda, a la ENISA, y comunica a la Secretaría de Estado de Seguridad del Ministerio del Interior los incidentes de operadores estratégicos relevantes para la protección de infraestructuras críticas (Ley 8/2011).","refs":[{"ref":"Art. 63.3 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"el Ministerio comunicará a la Secretaría de Estado de Seguridad del Ministerio del Interior aquellos incidentes que afectando a los operadores estratégicos nacionales sean de interés para la mejora de la protección de infraestructuras críticas"}]}]},{"n":"5","title":"RD 806/2014: objeto y ámbito (cap. I, arts. 1-2)","blocks":[{"text":"El Real Decreto 806/2014 desarrolla y ejecuta un modelo común de gobernanza de las TIC en la Administración General del Estado y sus organismos públicos (art. 1). Ese modelo incluye una estrategia global de transformación digital que garantice el uso adecuado de los recursos informáticos para mejorar los servicios públicos al ciudadano. Se aplica a la AGE y a sus organismos públicos (art. 2). Ojo: el artículo 2 remite todavía al artículo 43 de la Ley 6/1997 (LOFAGE), hoy derogada por la Ley 40/2015.","refs":[{"ref":"Art. 1 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"El objeto de este real decreto es el desarrollo y ejecución de un modelo común de gobernanza de las Tecnologías de la Información y las Comunicaciones (TIC) en la Administración General del Estado y sus Organismos Públicos."},{"ref":"Art. 2 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"El ámbito de aplicación de este real decreto se extiende a la Administración General del Estado y sus Organismos Públicos previstos en el artículo 43 de la Ley 6/1997, de 14 de abril"}]}]},{"n":"6","title":"Modelo de gobernanza TIC: Estrategia TIC, medios compartidos y unidades TIC (arts. 9-13)","blocks":[{"text":"La Estrategia TIC la aprueba el Gobierno, a iniciativa de la Comisión de Estrategia TIC y a propuesta de los ministros competentes; fija los objetivos, principios y acciones de la administración digital y sirve de base a los planes de acción de cada ministerio. La Comisión de Estrategia TIC determina su ámbito temporal y periodo de revisión (art. 9). Ojo: los ministerios que cita el artículo 9 (Presidencia; Hacienda y Administraciones Públicas; Industria, Energía y Turismo) responden a la estructura de 2014.","refs":[{"ref":"Art. 9 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"El Gobierno, a iniciativa de la Comisión de Estrategia TIC, y a propuesta de los Ministros de la Presidencia, de Hacienda y Administraciones Públicas y de Industria, Energía y Turismo, aprobará la Estrategia en materia de tecnologías de la información y las comunicaciones"},{"ref":"Art. 9 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"La Comisión de Estrategia TIC determinará el ámbito temporal de la Estrategia TIC, así como su periodo de revisión."}]},{"text":"Los medios y servicios TIC se declaran de uso compartido cuando responden a necesidades transversales de un número significativo de unidades (art. 10.1). La declaración corresponde a la Comisión de Estrategia TIC a propuesta de la Dirección de Tecnologías de la Información y las Comunicaciones (art. 10.2), y su uso es obligatorio y sustitutivo respecto de los medios particulares de cada unidad (art. 10.3). La Dirección TIC lleva un Catálogo de Servicios Comunes y se encarga de la provisión, explotación y gestión de esos medios, salvo la informática presupuestaria de la IGAE (art. 10.5).","refs":[{"ref":"Art. 10.2 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"La declaración de medios y servicios compartidos necesarios para la ejecución y desarrollo de la Estrategia TIC aprobada por el Gobierno, corresponderá a la Comisión de Estrategia TIC a propuesta de la Dirección de Tecnologías de la Información y las Comunicaciones."},{"ref":"Art. 10.3 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"La utilización de los medios y servicios compartidos será de carácter obligatorio y sustitutivo respecto a los medios y servicios particulares empleados por las distintas unidades."}]},{"text":"El Comité de Estrategia TIC puede declarar proyectos de interés prioritario, sobre todo los de cooperación con comunidades autónomas, entes locales y la UE (art. 11). Son unidades TIC las unidades administrativas que proveen servicios TIC a sí mismas o a otras (art. 12.1); entre esas funciones están el soporte de sistemas y redes, el desarrollo de aplicaciones, la consultoría, la seguridad de los sistemas, la atención a usuarios, la innovación y la administración digital (art. 12.2).","refs":[{"ref":"Art. 12.1 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"Son unidades TIC aquellas unidades administrativas cuya función sea la provisión de servicios en materia de Tecnologías de la Información y Comunicaciones a sí mismas o a otras unidades administrativas."},{"ref":"Art. 12.2 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"d) Seguridad de sistemas de información. e) Atención técnica a usuarios."}]}]},{"n":"7","title":"Ley 6/2020: disposiciones generales (título I, arts. 1-3)","blocks":[{"text":"La Ley 6/2020 regula determinados aspectos de los servicios electrónicos de confianza como complemento del Reglamento (UE) 910/2014 (eIDAS) (art. 1). Se aplica a los prestadores públicos y privados establecidos en España y a los de otro Estado con establecimiento permanente en España si ofrecen servicios no supervisados por otro país de la UE (art. 2). Los documentos electrónicos públicos, administrativos y privados tienen el valor y la eficacia jurídica propios de su naturaleza (art. 3.1); su prueba se rige por el artículo 326 de la Ley de Enjuiciamiento Civil, distinguiendo si el servicio de confianza usado era cualificado o no.","refs":[{"ref":"Art. 1 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"La presente Ley tiene por objeto regular determinados aspectos de los servicios electrónicos de confianza, como complemento del Reglamento (UE) n.º 910/2014"},{"ref":"Art. 3.1 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Los documentos electrónicos públicos, administrativos y privados, tienen el valor y la eficacia jurídica que corresponda a su respectiva naturaleza, de conformidad con la legislación que les resulte aplicable."}]}]},{"n":"8","title":"Certificados electrónicos: vigencia, revocación e identificación (título II, arts. 4-7)","blocks":[{"text":"Los certificados se extinguen por caducidad al acabar su vigencia o por revocación (art. 4.1). La vigencia de los certificados cualificados no puede superar cinco años (art. 4.2). Se revocan, entre otros casos, a solicitud del firmante, por violación del secreto de los datos de creación de firma, por resolución judicial o administrativa, por fallecimiento del firmante, por cese del prestador o por falsedad de los datos (art. 5.1). El prestador comunica al titular la revocación o suspensión con los motivos, la fecha y la hora (art. 5.3).","refs":[{"ref":"Art. 4 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"1. Los certificados electrónicos se extinguen por caducidad a la expiración de su período de vigencia, o mediante revocación por los prestadores de servicios electrónicos de confianza en los supuestos previstos en el artículo siguiente. 2. El período de vigencia de los certificados cualificados no será superior a cinco años."},{"ref":"Art. 5.1.c) Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"c) Resolución judicial o administrativa que lo ordene."}]},{"text":"En los certificados cualificados de personas físicas consta su nombre, apellidos y DNI, NIE o NIF, o un pseudónimo inequívoco (art. 6.1). Para obtener uno, la persona física debe personarse ante los encargados de verificar su identidad y acreditarla con DNI, pasaporte u otros medios; puede prescindirse de la personación si su firma en la solicitud se ha legitimado ante notario (art. 7.1). Por orden ministerial pueden admitirse métodos a distancia como la vídeo-identificación con seguridad equivalente (art. 7.2), y no hace falta repetir la identificación si consta por una relación previa de menos de cinco años (art. 7.6).","refs":[{"ref":"Art. 7.1 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Podrá prescindirse de la personación de la persona física que solicite un certificado cualificado si su firma en la solicitud de expedición de un certificado cualificado ha sido legitimada en presencia notarial."},{"ref":"Art. 7.6 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"el período de tiempo transcurrido desde la identificación fuese menor de cinco años."}]}]},{"n":"9","title":"Obligaciones y responsabilidad de los prestadores de servicios de confianza (título III, arts. 8-13)","blocks":[{"text":"Si un certificado lleva pseudónimo, el prestador debe constatar la verdadera identidad y revelarla a jueces y autoridades que la soliciten (art. 8). Todo prestador debe publicar información veraz, no copiar los datos de creación de firma del titular y, si expide certificados, disponer de un servicio público de consulta de su validez o revocación (art. 9.1 y 9.2). Los prestadores cualificados, además, conservan la información de los servicios 15 años desde la extinción del certificado o el fin del servicio; constituyen un seguro de responsabilidad civil de al menos 1.500.000 euros, más 500.000 por cada tipo de servicio cualificado adicional (salvo los del sector público); y avisan de su cese con dos meses de antelación (art. 9.3).","refs":[{"ref":"Art. 9.2 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Los prestadores de servicios de confianza que expidan certificados electrónicos deberán disponer de un servicio de consulta sobre el estado de validez o revocación de los certificados emitidos accesible al público."},{"ref":"Art. 9.3.a) Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"será de 15 años desde la extinción del certificado o la finalización del servicio prestado."},{"ref":"Art. 9.3.b) Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"b) Constituir un seguro de responsabilidad civil por importe mínimo de 1.500.000 euros, excepto si el prestador pertenece al sector público. Si presta más de un servicio cualificado de los previstos en el Reglamento (UE) 910/2014, se añadirán 500.000 euros más por cada tipo de servicio."},{"ref":"Art. 9.3.c) Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"con una antelación mínima de dos meses al cese efectivo de la actividad"}]},{"text":"El prestador responde frente a terceros de las personas u otros prestadores en quienes delegue funciones (art. 10), pero no responde si el usuario dio datos falsos, fue negligente custodiando sus claves o usó un certificado caducado, ni si el destinatario actúa con negligencia, por ejemplo al no verificar la firma (art. 11). Los prestadores no cualificados no necesitan verificación previa, pero deben comunicar su actividad al ministerio en tres meses desde que la inicien (art. 12). Las violaciones de seguridad se notifican al ministerio y la información se amplía en un mes como máximo (art. 13).","refs":[{"ref":"Art. 11.2 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Se entenderá que el destinatario actúa de forma negligente cuando no tenga en cuenta la suspensión o pérdida de vigencia del certificado electrónico, o cuando no verifique la firma o sello electrónico."},{"ref":"Art. 12 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Los prestadores de servicios de confianza no cualificados no necesitan verificación administrativa previa de cumplimiento de requisitos para iniciar su actividad, pero deberán comunicar su actividad al Ministerio de Asuntos Económicos y Transformación Digital en el plazo de tres meses desde que la inicien"},{"ref":"Art. 13.3 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Los prestadores de servicios ampliarán, en un plazo máximo de un mes tras la notificación del incidente"}]}]},{"n":"10","title":"El DNI y sus certificados electrónicos (disp. adic. 3.ª Ley 6/2020)","blocks":[{"text":"El DNI electrónico es el DNI que permite acreditar electrónicamente la identidad personal de su titular, en los términos del artículo 8 de la LO 4/2015 de seguridad ciudadana, y firmar electrónicamente documentos (DA 3.ª.1). Todas las personas, públicas o privadas, deben reconocer su eficacia para acreditar la identidad y los datos personales del titular, la identidad del firmante y la integridad de lo firmado con sus certificados (DA 3.ª.2). Los órganos del Ministerio del Interior que lo expiden cumplen las obligaciones de los prestadores que expiden certificados cualificados (DA 3.ª.3).","refs":[{"ref":"DA 3.ª.1 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"El Documento Nacional de Identidad electrónico es el Documento Nacional de Identidad que permite acreditar electrónicamente la identidad personal de su titular, en los términos establecidos en el artículo 8 de la Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana, así como la firma electrónica de documentos."},{"ref":"DA 3.ª.3 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"Los órganos competentes del Ministerio del Interior para la expedición del Documento Nacional de Identidad cumplirán las obligaciones que la presente Ley impone a los prestadores de servicios electrónicos de confianza que expidan certificados cualificados."}]}]},{"n":"11","title":"Esquema Nacional de Interoperabilidad (RD 4/2010, arts. 1-15)","blocks":[{"text":"El ENI reúne los criterios y recomendaciones de seguridad, normalización y conservación de la información, formatos y aplicaciones que deben seguir las Administraciones para asegurar la interoperabilidad organizativa, semántica y técnica y evitar discriminar a los ciudadanos por su elección tecnológica (art. 1.2). Sus principios específicos son tres: la interoperabilidad como cualidad integral, desde la concepción de los sistemas y en todo su ciclo de vida; su carácter multidimensional; y el enfoque de soluciones multilaterales (arts. 4 a 7). Ojo: el RD 4/2010 remite aún a la Ley 11/2007, derogada por las Leyes 39/2015 y 40/2015.","refs":[{"ref":"Art. 4 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"a) La interoperabilidad como cualidad integral. b) Carácter multidimensional de la interoperabilidad. c) Enfoque de soluciones multilaterales."},{"ref":"Art. 6 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"La interoperabilidad se entenderá contemplando sus dimensiones organizativa, semántica y técnica."}]},{"text":"En la vertiente técnica, las Administraciones usan estándares abiertos y, de forma complementaria, estándares de uso generalizado por los ciudadanos (art. 11.1). Para comunicarse entre sí utilizan preferentemente la Red de comunicaciones de las Administraciones públicas españolas, que presta la Red SARA (art. 13.1), y aplican el Plan de direccionamiento de la Administración (art. 14). Sus sistemas se sincronizan con la hora oficial, a través del Real Instituto y Observatorio de la Armada (art. 15).","refs":[{"ref":"Art. 11.1 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"Las Administraciones públicas usarán estándares abiertos, así como, en su caso y de forma complementaria, estándares que sean de uso generalizado por los ciudadanos"},{"ref":"Art. 13.1 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"La Red SARA prestará la citada Red de comunicaciones de las Administraciones públicas españolas."},{"ref":"Art. 15.2 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"La sincronización de la fecha y la hora se realizará con el Real Instituto y Observatorio de la Armada"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Telecomunicaciones: servicios de interés general en libre competencia; servicio público solo los del artículo 4.","refs":[{"ref":"Art. 2.1 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"Las telecomunicaciones son servicios de interés general que se prestan en régimen de libre competencia."}]},{"text":"Gestión directa o intervención de redes por el Gobierno: comunicación al juez en 24 horas, que decide en 48 horas.","refs":[{"ref":"Art. 4.6 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"en el plazo de veinticuatro horas al órgano jurisdiccional competente para que, en un plazo de cuarenta y ocho horas"}]},{"text":"Violación de datos personales: notificación a la AEPD sin dilaciones indebidas.","refs":[{"ref":"Art. 60.3 Ley 11/2022","law":"Ley 11/2022","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757","quote":"notificará sin dilaciones indebidas dicha violación a la Agencia Española de Protección de Datos"}]},{"text":"Medios y servicios TIC compartidos: los declara la Comisión de Estrategia TIC y su uso es obligatorio y sustitutivo.","refs":[{"ref":"Art. 10.3 RD 806/2014","law":"RD 806/2014","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741","quote":"será de carácter obligatorio y sustitutivo"}]},{"text":"Certificados cualificados: vigencia máxima de cinco años; conservación de información 15 años.","refs":[{"ref":"Art. 4.2 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"El período de vigencia de los certificados cualificados no será superior a cinco años."}]},{"text":"Seguro del prestador cualificado privado: 1.500.000 euros más 500.000 por servicio adicional.","refs":[{"ref":"Art. 9.3.b) Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"por importe mínimo de 1.500.000 euros"}]},{"text":"Prestador no cualificado: sin verificación previa; comunica su actividad en tres meses.","refs":[{"ref":"Art. 12 Ley 6/2020","law":"Ley 6/2020","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046","quote":"en el plazo de tres meses desde que la inicien"}]},{"text":"ENI: dimensiones organizativa, semántica y técnica; red común SARA; hora del Real Instituto y Observatorio de la Armada.","refs":[{"ref":"Art. 13.1 RD 4/2010","law":"RD 4/2010","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331","quote":"La Red SARA prestará la citada Red de comunicaciones de las Administraciones públicas españolas."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757', null, null, null, 'Otras normas citadas: RD 806/2014 (https://www.boe.es/buscar/act.php?id=BOE-A-2014-9741), Ley 6/2020 (https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046), RD 4/2010 (https://www.boe.es/buscar/act.php?id=BOE-A-2010-1331)'
  from public.topics t where t.slug = 'gc-17-tecnologias-informacion'
