   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 176/2022, de 4 de marzo, Código de Conducta del personal de la Guardia Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-19-deontologia', 'Tema 19. Deontología profesional: Código de Conducta de la Guardia Civil') on conflict (slug) do nothing;
