insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-21-violencia-genero', 'Tema 21. Protección integral contra la violencia de género (LO 1/2004)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-21-violencia-genero' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Título preliminar: objeto y principios rectores (arts. 1-2)"},{"n":"2","title":"Título I: medidas de sensibilización, prevención y detección (arts. 3-16)"},{"n":"2.1","title":"Ámbito educativo, publicidad y medios de comunicación, ámbito sanitario"},{"n":"3","title":"Título II: derechos de las mujeres víctimas de violencia de género (arts. 17-28 ter)"},{"n":"3.1","title":"Información, asistencia social integral y asistencia jurídica gratuita (arts. 17-20)"},{"n":"3.2","title":"Derechos laborales, de las funcionarias públicas y económicos; acreditación (arts. 21-28)"},{"n":"3.3","title":"Derecho a la reparación (arts. 28 bis y 28 ter)"},{"n":"4","title":"Título III: tutela institucional: Delegación del Gobierno, Observatorio y Fuerzas y Cuerpos de Seguridad (arts. 29-32)"},{"n":"5","title":"Título IV: tutela penal (arts. 33-42)"},{"n":"6","title":"Título V: tutela judicial; medidas judiciales de protección y seguridad de las víctimas (arts. 61-69)"},{"n":"7","title":"Fiscal contra la Violencia sobre la Mujer (arts. 70-72)"}]'::jsonb, '["Art. 1.1 LO 1/2004: «La presente Ley tiene por objeto actuar contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 1.3 LO 1/2004: «La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.»","Art. 1.4 LO 1/2004: «La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.»","Art. 10 LO 1/2004: «De acuerdo con lo establecido en la Ley 34/1988, de 11 de noviembre, General de Publicidad, se considerará ilícita la publicidad que utilice la imagen de la mujer con carácter vejatorio o discriminatorio.»","Art. 19.1 LO 1/2004: «Las mujeres víctimas de violencia de género tienen derecho a servicios sociales de atención, de emergencia, de apoyo y acogida y de recuperación integral. La organización de estos servicios por parte de las comunidades autónomas y las Corporaciones Locales responderá a los principios de atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional.»","Art. 20.1 LO 1/2004: «Las víctimas de violencia de género tienen derecho a recibir asesoramiento jurídico gratuito en el momento inmediatamente previo a la interposición de la denuncia, y a la defensa y representación gratuitas por abogado y procurador en todos los procesos y procedimientos administrativos que tengan causa directa o indirecta en la violencia padecida.»","Art. 24 LO 1/2004: «La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia en los términos que se determinen en su legislación específica.»","Art. 25 LO 1/2004: «Las ausencias totales o parciales al trabajo motivadas por la situación física o psicológica derivada de la violencia de género sufrida por una mujer funcionaria se considerarán justificadas en los términos que se determine en su legislación específica.»","Art. 27.2 LO 1/2004: «El importe de esta ayuda será equivalente al de seis meses de subsidio por desempleo. Cuando la víctima de la violencia ejercida contra la mujer tuviera reconocida oficialmente una discapacidad en grado igual o superior al 33 por 100, el importe será equivalente a doce meses de subsidio por desempleo.»","Art. 29.1 LO 1/2004: «La Delegación del Gobierno contra la Violencia de Género, adscrita al Ministerio de Igualdad o al departamento con competencias en la materia, formulará las políticas públicas en relación con la violencia de género a desarrollar por el Gobierno y elaborará la Macroencuesta de Violencia contra las Mujeres.»","Art. 31.1 LO 1/2004: «El Gobierno establecerá, en las Fuerzas y Cuerpos de Seguridad del Estado, unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales adoptadas.»","Art. 61.1 LO 1/2004: «Las medidas de protección y seguridad previstas en el presente capítulo serán compatibles con cualesquiera de las medidas cautelares y de aseguramiento que se pueden adoptar en los procesos civiles y penales.»","Art. 64.1 LO 1/2004: «El Juez podrá ordenar la salida obligatoria del inculpado por violencia de género del domicilio en el que hubiera estado conviviendo o tenga su residencia la unidad familiar, así como la prohibición de volver al mismo.»","Art. 67 LO 1/2004: «El Juez podrá acordar, respecto de los inculpados en delitos relacionados con la violencia a que se refiere esta Ley, la suspensión del derecho a la tenencia, porte y uso de armas, con la obligación de depositarlas en los términos establecidos por la normativa vigente.»","Art. 68 LO 1/2004: «Las medidas restrictivas de derechos contenidas en este capítulo deberán adoptarse mediante auto motivado en el que se aprecie su proporcionalidad y necesidad, y, en todo caso, con intervención del Ministerio Fiscal y respeto de los principios de contradicción, audiencia y defensa.»","Art. 69 LO 1/2004: «Las medidas de este capítulo podrán mantenerse tras la sentencia definitiva y durante la tramitación de los eventuales recursos que correspondiesen. En este caso, deberá hacerse constar en la sentencia el mantenimiento de tales medidas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Título preliminar: objeto y concepto de violencia de género (art. 1)","blocks":[{"text":"La LO 1/2004 actúa contra la violencia que, como manifestación de la discriminación, la desigualdad y las relaciones de poder de los hombres sobre las mujeres, ejercen sobre ellas quienes sean o hayan sido sus cónyuges o estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia (art. 1.1). Es decir: el agresor es la pareja o expareja, haya o no convivencia. La Ley establece medidas de protección integral para prevenir, sancionar y erradicar esta violencia y asistir a las mujeres, a sus hijos menores y a los menores bajo su tutela, guarda o custodia (art. 1.2).","refs":[{"ref":"Art. 1.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia."},{"ref":"Art. 1.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Por esta ley se establecen medidas de protección integral cuya finalidad es prevenir, sancionar y erradicar esta violencia"}]},{"text":"Comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad (art. 1.3). También es violencia de género la que esas mismas personas ejercen sobre los familiares o allegados menores de edad de la mujer con el objetivo de causarle perjuicio o daño a ella (art. 1.4, la llamada violencia vicaria).","refs":[{"ref":"Art. 1.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad."},{"ref":"Art. 1.4 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero."}]}]},{"n":"2","title":"Título preliminar: principios rectores (art. 2)","blocks":[{"text":"La Ley articula un conjunto integral de medidas con fines como fortalecer la sensibilización y la prevención en los ámbitos educativo, social, sanitario, publicitario y mediático; consagrar derechos de las víctimas exigibles ante las Administraciones; reforzar los servicios sociales de información, atención, emergencia, apoyo y recuperación integral; garantizar derechos laborales, funcionariales y económicos; y establecer un sistema integral de tutela institucional (art. 2). Ojo: el art. 2.f) aún habla de la «Delegación Especial del Gobierno contra la Violencia sobre la Mujer», mientras que el art. 29, en su redacción actual, la denomina Delegación del Gobierno contra la Violencia de Género.","refs":[{"ref":"Art. 2.b) LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Consagrar derechos de las mujeres víctimas de violencia de género, exigibles ante las Administraciones Públicas"},{"ref":"Art. 2.f) LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"a través de la Delegación Especial del Gobierno contra la Violencia sobre la Mujer, en colaboración con el Observatorio Estatal de la Violencia sobre la Mujer"}]}]},{"n":"3","title":"Título I: sensibilización y ámbito educativo (arts. 3-9)","blocks":[{"text":"El Gobierno debe poner en marcha un Plan Estatal de Sensibilización y Prevención de la Violencia de Género, de carácter permanente, dirigido a hombres y mujeres, con formación de profesionales y controlado por una Comisión de amplia participación en la que estén presentes las víctimas (art. 3.1). La Delegación del Gobierno contra la Violencia de Género, oída esa Comisión, elabora el informe anual de evaluación del Plan y lo remite a las Cortes Generales. Los poderes públicos impulsan además campañas específicas (art. 3.2).","refs":[{"ref":"Art. 3.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La Delegación del Gobierno contra la Violencia de Género, oída la Comisión a la que se refiere el párrafo anterior, elaborará el Informe anual de evaluación del Plan Estatal de Sensibilización y Prevención de la Violencia de Género y lo remitirá a las Cortes Generales."}]},{"text":"El sistema educativo transmite valores de respeto e igualdad (art. 4), y las Administraciones deben prever la escolarización inmediata de los hijos afectados por un cambio de residencia derivado de la violencia de género (art. 5). Se regulan también el fomento de la igualdad en los materiales, la formación del profesorado, la participación en los Consejos Escolares y la actuación de la inspección educativa (arts. 6 a 9).","refs":[{"ref":"Art. 5 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las Administraciones competentes deberán prever la escolarización inmediata de los hijos que se vean afectados por un cambio de residencia derivada de actos de violencia de género."}]}]},{"n":"4","title":"Título I: publicidad, medios de comunicación y ámbito sanitario (arts. 10-16)","blocks":[{"text":"Conforme a la Ley General de Publicidad, es ilícita la publicidad que utilice la imagen de la mujer con carácter vejatorio o discriminatorio (art. 10). Pueden ejercer la acción de cesación la Delegación del Gobierno, el Instituto de la Mujer u órgano autonómico equivalente, el Ministerio Fiscal y las asociaciones cuyo objetivo único sea defender los intereses de la mujer (art. 12). Los medios de comunicación deben fomentar la protección de la igualdad (art. 13).","refs":[{"ref":"Art. 10 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"se considerará ilícita la publicidad que utilice la imagen de la mujer con carácter vejatorio o discriminatorio."},{"ref":"Art. 12 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"el Ministerio Fiscal y las Asociaciones que tengan como objetivo único la defensa de los intereses de la mujer estarán legitimados para ejercitar ante los Tribunales la acción de cesación"}]},{"text":"En el ámbito sanitario se promueve la detección precoz y la formación (art. 15). En el Consejo Interterritorial del Sistema Nacional de Salud se crea una Comisión contra la Violencia de Género, con representantes de todas las Comunidades Autónomas competentes, que emite un informe anual remitido al Observatorio Estatal de la Violencia sobre la Mujer y al Pleno del Consejo Interterritorial (art. 16).","refs":[{"ref":"Art. 16 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La Comisión emitirá un informe anual que será remitido al Observatorio Estatal de la Violencia sobre la Mujer y al Pleno del Consejo Interterritorial."}]}]},{"n":"5","title":"Título II: información, atención integral y asistencia jurídica (arts. 17-20)","blocks":[{"text":"Todas las víctimas tienen garantizados los derechos de la Ley sin discriminación en el acceso (art. 17.1). Los servicios de información y orientación, atención psicosocial inmediata, telefónica y en línea, asesoramiento jurídico 24 horas, acogida y asistencia social integral tienen carácter de servicios esenciales (art. 17.3). La víctima tiene derecho a información plena y adecuada, también en formato accesible para mujeres con discapacidad y para quienes desconozcan el castellano o la otra lengua oficial (art. 18).","refs":[{"ref":"Art. 17.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"asesoramiento jurídico 24 horas, los servicios de acogida y asistencia social integral, consistentes en orientación jurídica, psicológica y social destinadas a las víctimas de violencias contra las mujeres tendrán carácter de servicios esenciales."},{"ref":"Art. 18.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La información deberá ser accesible para las mujeres que desconozcan el castellano o, en su caso, la otra lengua oficial de su territorio de residencia."}]},{"text":"Las víctimas tienen derecho a servicios sociales de atención, emergencia, apoyo y acogida y recuperación integral, que las Comunidades Autónomas y Corporaciones Locales organizan según los principios de atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional (art. 19.1). Tienen derecho a asesoramiento jurídico gratuito en el momento inmediatamente previo a la denuncia y a defensa y representación gratuitas por abogado y procurador en todos los procesos derivados de la violencia, con una misma dirección letrada (art. 20.1). Pueden personarse como acusación particular en cualquier momento, sin retrotraer actuaciones (art. 20.7).","refs":[{"ref":"Art. 19.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"responderá a los principios de atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional."},{"ref":"Art. 20.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las víctimas de violencia de género tienen derecho a recibir asesoramiento jurídico gratuito en el momento inmediatamente previo a la interposición de la denuncia"},{"ref":"Art. 20.7 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las víctimas de violencia de género podrán personarse como acusación particular en cualquier momento del procedimiento"}]}]},{"n":"6","title":"Título II: derechos laborales, de las funcionarias y acreditación (arts. 21-26)","blocks":[{"text":"La trabajadora víctima tiene derecho a reducir o reordenar su tiempo de trabajo, a la movilidad geográfica, al cambio de centro, a la adaptación del puesto y a la suspensión con reserva de puesto y la extinción del contrato (art. 21.1); la suspensión y la extinción son situación legal de desempleo (art. 21.2). Las empresas que contraten interinos para sustituirla tienen una bonificación del 100 % de las cuotas empresariales por contingencias comunes (art. 21.3). Sus ausencias o faltas de puntualidad derivadas de la violencia se consideran justificadas y remuneradas cuando lo determinen los servicios sociales o de salud (art. 21.4).","refs":[{"ref":"Art. 21.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica, al cambio de centro de trabajo"},{"ref":"Art. 21.4 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las ausencias o faltas de puntualidad al trabajo motivadas por la situación física o psicológica derivada de la violencia de género se considerarán justificadas y serán remuneradas"}]},{"text":"La funcionaria víctima tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia, según su legislación específica (art. 24), y sus ausencias se consideran justificadas (art. 25). La situación se acredita con una sentencia condenatoria, una orden de protección u otra resolución judicial que acuerde una medida cautelar, o el informe del Ministerio Fiscal, entre otros títulos; con menores, también con documentos sanitarios oficiales comunicados a la Fiscalía o al juzgado (art. 23).","refs":[{"ref":"Art. 24 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia"},{"ref":"Art. 23 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"se acreditarán mediante una sentencia condenatoria por cualquiera de las manifestaciones de la violencia contra las mujeres previstas en esta ley, una orden de protección o cualquier otra resolución judicial que acuerde una medida cautelar a favor de la víctima"}]}]},{"n":"7","title":"Título II: derechos económicos y derecho a la reparación (arts. 27-28 ter)","blocks":[{"text":"Si la víctima carece de rentas superiores al 75 % del salario mínimo interprofesional y tendrá especiales dificultades para obtener empleo, recibe una ayuda de pago único (art. 27.1). Equivale, con carácter general, a seis meses de subsidio por desempleo; doce meses si tiene una discapacidad de al menos el 33 %; y puede llegar a dieciocho o veinticuatro meses con responsabilidades familiares (art. 27.2 y 27.4). Las víctimas son colectivo prioritario en el acceso a viviendas protegidas y residencias públicas para mayores (art. 28).","refs":[{"ref":"Art. 27.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El importe de esta ayuda será equivalente al de seis meses de subsidio por desempleo."},{"ref":"Art. 28 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"serán consideradas colectivos prioritarios en el acceso a viviendas protegidas y residencias públicas para mayores"}]},{"text":"El derecho a la reparación comprende la compensación económica por los daños y perjuicios, las medidas para la completa recuperación física, psíquica y social, las acciones de reparación simbólica y las garantías de no repetición (art. 28 bis).","refs":[{"ref":"Art. 28 bis LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las víctimas de violencia de género tienen derecho a la reparación, lo que comprende la compensación económica por los daños y perjuicios derivados de la violencia, las medidas necesarias para su completa recuperación física, psíquica y social, las acciones de reparación simbólica y las garantías de no repetición."}]}]},{"n":"8","title":"Título III: tutela institucional y Fuerzas y Cuerpos de Seguridad (arts. 29-32)","blocks":[{"text":"La Delegación del Gobierno contra la Violencia de Género, adscrita al Ministerio de Igualdad, formula las políticas públicas del Gobierno en esta materia y elabora la Macroencuesta de Violencia contra las Mujeres; su titular está legitimado ante los tribunales (art. 29). El Observatorio Estatal de Violencia sobre la Mujer asesora, evalúa y estudia, y remite al Gobierno y a las Comunidades Autónomas un informe anual sobre la evolución de esta violencia (art. 30). Ojo: el art. 30.1 sigue adscribiendo el Observatorio al «Ministerio de Trabajo y Asuntos Sociales», denominación de 2004 ya superada.","refs":[{"ref":"Art. 29.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"formulará las políticas públicas en relación con la violencia de género a desarrollar por el Gobierno y elaborará la Macroencuesta de Violencia contra las Mujeres."},{"ref":"Art. 30.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"remitirá al Gobierno y a las Comunidades Autónomas, con periodicidad anual, un informe sobre la evolución de la violencia ejercida sobre la mujer"},{"ref":"Art. 30.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"como órgano colegiado adscrito al Ministerio de Trabajo y Asuntos Sociales"}]},{"text":"Artículo clave para un guardia civil: el Gobierno establecerá en las Fuerzas y Cuerpos de Seguridad del Estado unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales (art. 31.1). Las Policías Locales cooperan en asegurar el cumplimiento de esas medidas, y la actuación policial tiene en cuenta el Protocolo de Actuación de las Fuerzas y Cuerpos de Seguridad y de Coordinación con los Órganos Judiciales (art. 31.2 y 31.3). Los poderes públicos elaboran planes de colaboración y protocolos que impliquen a sanidad, justicia, fuerzas de seguridad y servicios sociales (art. 32).","refs":[{"ref":"Art. 31.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El Gobierno establecerá, en las Fuerzas y Cuerpos de Seguridad del Estado, unidades especializadas en la prevención de la violencia de género y en el control de la ejecución de las medidas judiciales adoptadas."},{"ref":"Art. 31.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"habrá de tener en cuenta el Protocolo de Actuación de las Fuerzas y Cuerpos de Seguridad y de Coordinación con los Órganos Judiciales"}]}]},{"n":"9","title":"Título IV: tutela penal (arts. 33-42)","blocks":[{"text":"La Ley reformó el Código Penal: en delitos de violencia de género, la suspensión de la pena se condiciona siempre a ciertas obligaciones (art. 33) y la prisión solo puede sustituirse por trabajos en beneficio de la comunidad (art. 35); se agravan las lesiones, el maltrato ocasional, las amenazas y coacciones leves cuando la víctima es o ha sido esposa o pareja, aun sin convivencia (arts. 36 a 39); y se castiga el quebrantamiento de las penas o medidas del art. 48 CP con prisión de seis meses a un año (art. 40). La Administración penitenciaria realiza programas específicos para estos internos, que las Juntas de Tratamiento valoran en grados, permisos y libertad condicional (art. 42).","refs":[{"ref":"Art. 35 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"la pena de prisión sólo podrá ser sustituida por la de trabajos en beneficio de la comunidad."},{"ref":"Art. 37 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"cuando la ofendida sea o haya sido esposa, o mujer que esté o haya estado ligada a él por una análoga relación de afectividad aun sin convivencia"},{"ref":"Art. 42 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La Administración penitenciaria realizará programas específicos para internos condenados por delitos relacionados con la violencia de género."}]},{"text":"Ojo: el título IV reproduce la redacción que la Ley dio en 2004 a esos artículos del Código Penal, que después se han reformado; por ejemplo, el art. 153 CP vigente (LO 1/2015) ya habla de «lesión de menor gravedad» y el art. 620 CP (faltas) no figura en el texto consolidado. Para las penas actuales hay que consultar el Código Penal (tema 8).","refs":[{"ref":"Art. 153.1 CP","law":"Código Penal","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444","quote":"El que por cualquier medio o procedimiento causare a otro menoscabo psíquico o una lesión de menor gravedad de las previstas en el apartado 2 del artículo 147"}]}]},{"n":"10","title":"Título V: tutela judicial y medidas de protección de las víctimas (arts. 43-69)","blocks":[{"text":"La Ley creó los Juzgados de Violencia sobre la Mujer: uno o más en cada partido judicial, con sede en su capital (art. 43, que añadió el art. 87 bis LOPJ); instruyen, entre otros, los delitos de homicidio, lesiones, contra la libertad, la integridad moral o la libertad sexual cometidos sobre la mujer (art. 44, art. 87 ter LOPJ). Las medidas de protección son compatibles con las cautelares civiles y penales (art. 61.1). Ante una solicitud de orden de protección, el Juez de Violencia sobre la Mujer o el de Guardia actúa según el art. 544 ter LECrim (art. 62). Se protege la intimidad de las víctimas y pueden celebrarse vistas a puerta cerrada (art. 63).","refs":[{"ref":"Art. 43 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"En cada partido habrá uno o más Juzgados de Violencia sobre la Mujer, con sede en la capital de aquél y jurisdicción en todo su ámbito territorial."},{"ref":"Art. 62 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"el Juez de Violencia sobre la Mujer y, en su caso, el Juez de Guardia, actuarán de conformidad con lo dispuesto en el artículo 544 ter de la Ley de Enjuiciamiento Criminal."}]},{"text":"El juez puede ordenar la salida del inculpado del domicilio familiar y prohibirle volver; prohibirle aproximarse a la persona protegida en cualquier lugar, con control por medios tecnológicos, fijando una distancia mínima que no podrá rebasar bajo apercibimiento de responsabilidad penal; y suspender sus comunicaciones (art. 64). Puede suspender la patria potestad o la custodia (art. 65), ordena la suspensión del régimen de visitas salvo que el interés superior del menor aconseje otra cosa (art. 66) y puede suspender la tenencia, porte y uso de armas, con obligación de depositarlas (art. 67). Las medidas restrictivas se adoptan por auto motivado, proporcionado y necesario, con intervención del Ministerio Fiscal (art. 68), y pueden mantenerse tras la sentencia durante los recursos (art. 69).","refs":[{"ref":"Art. 64.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El Juez fijará una distancia mínima entre el inculpado y la persona protegida que no se podrá rebasar, bajo apercibimiento de incurrir en responsabilidad penal."},{"ref":"Art. 67 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"la suspensión del derecho a la tenencia, porte y uso de armas, con la obligación de depositarlas en los términos establecidos por la normativa vigente."},{"ref":"Art. 68 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"deberán adoptarse mediante auto motivado en el que se aprecie su proporcionalidad y necesidad, y, en todo caso, con intervención del Ministerio Fiscal"}]}]},{"n":"11","title":"Título V: Fiscal contra la Violencia sobre la Mujer (arts. 70-72)","blocks":[{"text":"El Fiscal General del Estado nombra, oído el Consejo Fiscal, un Fiscal contra la Violencia sobre la Mujer con categoría de Fiscal de Sala, que interviene en los procesos penales de especial trascendencia y, por delegación, en los civiles de violencia de género (art. 70, que añadió el art. 18 quáter al Estatuto Orgánico del Ministerio Fiscal). En las Fiscalías existen secciones contra la violencia sobre la mujer (art. 71).","refs":[{"ref":"Art. 70 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El Fiscal General del Estado nombrará, oído el Consejo Fiscal, como delegado, un Fiscal contra la Violencia sobre la Mujer, con categoría de Fiscal de Sala"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Violencia de género: la del cónyuge o pareja, actual o pasada, aun sin convivencia.","refs":[{"ref":"Art. 1.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"aun sin convivencia."}]},{"text":"También la ejercida sobre los menores de la mujer para dañarla a ella.","refs":[{"ref":"Art. 1.4 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"se ejerza sobre sus familiares o allegados menores de edad"}]},{"text":"Informe anual del Plan Estatal: lo elabora la Delegación del Gobierno y va a las Cortes Generales.","refs":[{"ref":"Art. 3.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"lo remitirá a las Cortes Generales."}]},{"text":"Asesoramiento jurídico gratuito: inmediatamente antes de la denuncia.","refs":[{"ref":"Art. 20.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"en el momento inmediatamente previo a la interposición de la denuncia"}]},{"text":"Ayuda de pago único: seis meses de subsidio por desempleo, con carácter general.","refs":[{"ref":"Art. 27.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"seis meses de subsidio por desempleo."}]},{"text":"Observatorio Estatal: informe anual al Gobierno y a las Comunidades Autónomas.","refs":[{"ref":"Art. 30.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"con periodicidad anual"}]},{"text":"Fuerzas y Cuerpos de Seguridad del Estado: unidades especializadas en prevención y en control de las medidas judiciales.","refs":[{"ref":"Art. 31.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"unidades especializadas en la prevención de la violencia de género"}]},{"text":"Alejamiento: el juez fija una distancia mínima; armas: suspensión con depósito.","refs":[{"ref":"Art. 64.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"El Juez fijará una distancia mínima"}]},{"text":"Medidas restrictivas: auto motivado con intervención del Ministerio Fiscal.","refs":[{"ref":"Art. 68 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"mediante auto motivado"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', null, null, null, null
  from public.topics t where t.slug = 'gc-21-violencia-genero'
