insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La prueba de gramática (base 6.1.1.b de la convocatoria)"},{"n":"2","title":"Dequeísmo y queísmo"},{"n":"3","title":"Leísmo, laísmo y loísmo"},{"n":"4","title":"Verbo haber impersonal y perífrasis «haber que»"},{"n":"5","title":"Verbo hacer: imperativo, uso impersonal y «hacer público»"},{"n":"6","title":"Verbos irregulares: ir, andar, conducir, satisfacer, errar"},{"n":"7","title":"Perífrasis deber / deber de + infinitivo"},{"n":"8","title":"Adverbios, conjunciones y determinantes: detrás, sino, sendos, cuyo"}]'::jsonb, '["Base 6.1.1.b Convocatoria Guardia Civil 2026 (BOE-A-2026-9982): «Consistirá en la realización de un ejercicio con veinte (20) frases o expresiones, debiendo señalar aquellas frases o expresiones que no son correctas desde los puntos de vista morfológico y/o sintáctico.»","DPD, s. v. dequeísmo RAE-ASALE, Diccionario panhispánico de dudas: «Es el uso indebido de la preposición de delante de la conjunción que cuando la preposición no está gramaticalmente justificada.»","DPD, s. v. queísmo RAE-ASALE, Diccionario panhispánico de dudas: «Es la supresión indebida de una preposición (generalmente de) delante de la conjunción que, cuando la preposición está gramaticalmente justificada.»","DPD, s. v. dequeísmo, 5b RAE-ASALE, Diccionario panhispánico de dudas: «Sustituir la subordinada con que por el pronombre eso y comprobar si se mantiene o no la preposición de, o si ha de usarse otra distinta»","DPD, s. v. laísmo RAE-ASALE, Diccionario panhispánico de dudas: «Es el uso impropio de la(s) en función de complemento indirecto femenino, en lugar de le(s), que es la forma a la que corresponde etimológicamente ejercer esa función»","DPD, s. v. loísmo RAE-ASALE, Diccionario panhispánico de dudas: «Es el uso impropio de lo(s) en función de complemento indirecto masculino (de persona o de cosa) o neutro (cuando el antecedente es un pronombre neutro o toda una oración), en lugar de le(s)»","DPD, s. v. leísmo RAE-ASALE, Diccionario panhispánico de dudas: «El leísmo, en cambio, no se admite de ningún modo en la norma culta cuando el referente es inanimado: ⊗El libro que me prestaste le leí de un tirón; ⊗Los informes me les mandas cuando puedas.»","DPD, s. v. haber, 4 RAE-ASALE, Diccionario panhispánico de dudas: «Por consiguiente, en estos casos, lo más apropiado es que el verbo permanezca en singular, y así sucede en el uso culto mayoritario, especialmente en la lengua escrita, tanto en España como en América»","DPD, s. v. haber, 3b RAE-ASALE, Diccionario panhispánico de dudas: «Al ser impersonal, se conjuga solo en tercera persona del singular; por ello, si el verbo que le sigue es pronominal, no es correcto el uso del pronombre de primera persona del plural»","DPD, s. v. hacer RAE-ASALE, Diccionario panhispánico de dudas: «El imperativo singular es haz (tú) y hacé (vos), y no ⊗hace.»","DPD, s. v. ir RAE-ASALE, Diccionario panhispánico de dudas: «Las formas de imperativo propias del tuteo son ve (tú) e id (vosotros)»","DPD, s. v. conducir RAE-ASALE, Diccionario panhispánico de dudas: «Como ocurre en todos los verbos terminados en -ducir, se escuchan a veces formas regularizadas en el pretérito perfecto simple, que no se consideran correctas: ⊗conducí, ⊗conduciste, ⊗condució, etc., en lugar de conduje, condujiste, condujo, etc.»","DPD, s. v. deber RAE-ASALE, Diccionario panhispánico de dudas: «b) deber de + infinitivo. Denota normalmente probabilidad o suposición»","DPD, s. v. detrás RAE-ASALE, Diccionario panhispánico de dudas: «Por su condición de adverbio, se desaconseja en el habla culta su uso con posesivos: ⊗detrás mío, ⊗detrás suya, etc. (en lugar de detrás de mí, detrás de él/ella, etc.).»","DPD, s. v. sino RAE-ASALE, Diccionario panhispánico de dudas: «En la lengua actual, cuando lo que se contrapone son oraciones con el verbo en forma personal, sino debe ir seguido de que»","DPD, s. v. sendos RAE-ASALE, Diccionario panhispánico de dudas: «No debe emplearse como equivalente de dos o ambos»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La prueba de gramática (base 6.1.1.b de la convocatoria)","blocks":[{"text":"La prueba de gramática consiste en veinte frases o expresiones de las que hay que señalar las que no son correctas desde el punto de vista morfológico (formas de las palabras: conjugaciones, plurales, imperativos) o sintáctico (construcción de la frase: preposiciones, concordancias, pronombres). Se añaden cuatro frases de reserva, que solo cuentan si el tribunal anula alguna. Como en ortografía, es error tanto dejar sin marcar una frase incorrecta como marcar una correcta, de modo que hay que conocer también las construcciones que la norma admite.","refs":[{"ref":"Base 6.1.1.b)","law":"Convocatoria Guardia Civil 2026 (BOE-A-2026-9982)","url":"https://www.boe.es/diario_boe/txt.php?id=BOE-A-2026-9982","quote":"Consistirá en la realización de un ejercicio con veinte (20) frases o expresiones, debiendo señalar aquellas frases o expresiones que no son correctas desde los puntos de vista morfológico y/o sintáctico."},{"ref":"Base 6.1.1.b)","law":"Convocatoria Guardia Civil 2026 (BOE-A-2026-9982)","url":"https://www.boe.es/diario_boe/txt.php?id=BOE-A-2026-9982","quote":"Se considera respuesta errónea, tanto dejar de marcar una frase o expresión incorrecta como marcar una que es correcta."}]},{"text":"La referencia normativa que se usa en estos apuntes es el Diccionario panhispánico de dudas de la RAE y la ASALE, que marca con ⊗ las formas incorrectas. Los errores que más se repiten son el dequeísmo y el queísmo, los usos indebidos de le, la y lo, la concordancia del verbo haber y las conjugaciones regularizadas de verbos irregulares.","refs":[{"ref":"DPD, s. v. dequeísmo, 1a","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗Pienso de que conseguiremos ganar el campeonato (correcto: Pienso que conseguiremos ganar el campeonato)"}]}]},{"n":"2","title":"El dequeísmo","blocks":[{"text":"El dequeísmo es el uso indebido de la preposición de delante de la conjunción que cuando la preposición no está gramaticalmente justificada. Se da, sobre todo, ante una subordinada que es complemento directo, porque el complemento directo nunca lleva de: con verbos de pensamiento, lengua, afección o percepción. Son incorrectas «Pienso de que…», «Me dijeron de que…», «Temo de que…» o «He oído de que…».","refs":[{"ref":"DPD, s. v. dequeísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es el uso indebido de la preposición de delante de la conjunción que cuando la preposición no está gramaticalmente justificada."},{"ref":"DPD, s. v. dequeísmo, 1a","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"El complemento directo nunca va encabezado por la preposición de"}]},{"text":"Tampoco lleva de la subordinada que funciona como sujeto: «Me alegra que seáis felices» (no «Me alegra de que»), «Es posible que nieve mañana» (no «Es posible de que»). Ojo con la forma pronominal: «Me alegro de que seáis felices» sí exige de, porque alegrarse se construye con de. También hay dequeísmo al meter de en locuciones que no la llevan (a medida que, a menos que, a no ser que, una vez que) y al usar de en lugar de la preposición que exige el verbo: «Insistieron en que fuéramos», no «Insistieron de que».","refs":[{"ref":"DPD, s. v. dequeísmo, 1b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗Me alegra de que seáis felices (correcto: Me alegra que seáis felices)"},{"ref":"DPD, s. v. dequeísmo, 1b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗Es posible de que nieve mañana (correcto: Es posible que nieve mañana)"},{"ref":"DPD, s. v. dequeísmo, 1d","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗a medida de que (correcto: a medida que; → medida, 1)"},{"ref":"DPD, s. v. dequeísmo, 1e","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗Insistieron de que fuéramos con ellos (correcto: Insistieron en que fuéramos con ellos)"}]},{"text":"Para comprobarlo, el DPD propone dos trucos: convertir la frase en pregunta (si la pregunta lleva de, la frase también) o sustituir la subordinada por «eso» y ver si se mantiene la preposición: «Se preocupa de eso» / «Se preocupa de que…»; «Opina eso» / «Opina que…»; «Insistió en eso» / «Insistió en que…».","refs":[{"ref":"DPD, s. v. dequeísmo, 5b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Sustituir la subordinada con que por el pronombre eso y comprobar si se mantiene o no la preposición de, o si ha de usarse otra distinta"}]}]},{"n":"3","title":"El queísmo","blocks":[{"text":"El queísmo es el error contrario: suprimir indebidamente una preposición (normalmente de) delante de que cuando sí está justificada. Está menos estigmatizado, pero se recomienda evitarlo. Aparece con verbos pronominales de régimen (acordarse de, alegrarse de, olvidarse de, fijarse en): «Me olvidé de que tenía que llamarte», no «Me olvidé que…»; y con verbos no pronominales de régimen (confiar en, convencer de, insistir en).","refs":[{"ref":"DPD, s. v. queísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es la supresión indebida de una preposición (generalmente de) delante de la conjunción que, cuando la preposición está gramaticalmente justificada."},{"ref":"DPD, s. v. queísmo, 1a","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Me olvidé de que tenía que llamarte (no ⊗Me olvidé que tenía que llamarte)"}]},{"text":"También es queísmo suprimir la preposición en locuciones como a pesar de que, a fin de que, a condición de que o en caso de que, y en locuciones verbales como caber duda de, caer en la cuenta de o darse cuenta de: «Nos dimos cuenta de que era tarde». En cambio, tener en cuenta no exige de: «No tiene en cuenta que nos esforzamos».","refs":[{"ref":"DPD, s. v. queísmo, 1e","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"a pesar de que (no ⊗a pesar que)"},{"ref":"DPD, s. v. queísmo, 1f","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Nos dimos cuenta de que era tarde (no ⊗Nos dimos cuenta que era tarde)."},{"ref":"DPD, s. v. queísmo, 1f","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No tiene en cuenta que nos esforzamos (no ⊗No tiene en cuenta de que nos esforzamos)."}]}]},{"n":"4","title":"Leísmo, laísmo y loísmo","blocks":[{"text":"Los pronombres átonos tienen funciones fijas: lo, la, los, las son de complemento directo y le, les de complemento indirecto. El laísmo es usar la o las como complemento indirecto femenino en vez de le o les; suele nacer del cruce de construcciones: de «La besó» y «Le dio un beso» se pasa al incorrecto «La dio un beso». El loísmo es usar lo o los como complemento indirecto masculino o neutro en lugar de le o les.","refs":[{"ref":"DPD, s. v. laísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es el uso impropio de la(s) en función de complemento indirecto femenino, en lugar de le(s), que es la forma a la que corresponde etimológicamente ejercer esa función"},{"ref":"DPD, s. v. laísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"de La besó y Le dio un beso, a ⊗La dio un beso."},{"ref":"DPD, s. v. loísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es el uso impropio de lo(s) en función de complemento indirecto masculino (de persona o de cosa) o neutro (cuando el antecedente es un pronombre neutro o toda una oración), en lugar de le(s)"}]},{"text":"El leísmo es usar le o les como complemento directo. Por su extensión entre hablantes cultos, se tolera cuando el referente es una persona de género masculino: «A tu marido no le he visto». Pero no se admite de ningún modo cuando el referente es una cosa: «El libro que me prestaste le leí» es incorrecto (lo correcto es «lo leí»).","refs":[{"ref":"DPD, s. v. leísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"no se considera incorrecto el uso de le(s) en lugar de lo(s) en función de complemento directo cuando el referente es persona y el género gramatical masculino"},{"ref":"DPD, s. v. leísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"El leísmo, en cambio, no se admite de ningún modo en la norma culta cuando el referente es inanimado: ⊗El libro que me prestaste le leí de un tirón"}]}]},{"n":"5","title":"El verbo haber: uso impersonal y «haber que»","blocks":[{"text":"Cuando haber indica existencia es impersonal: el sustantivo que lo acompaña es complemento directo, no sujeto, y por eso el verbo va en singular aunque ese sustantivo sea plural. Se dice «Había muchos problemas» y «Hubo varios momentos», no «Habían muchos problemas». La misma regla se aplica en las perífrasis con poder, soler, deber o ir a: «Va a haber muchos cambios», no «Van a haber».","refs":[{"ref":"DPD, s. v. haber, 4","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"lo más apropiado es que el verbo permanezca en singular, y así sucede en el uso culto mayoritario, especialmente en la lengua escrita, tanto en España como en América"},{"ref":"DPD, s. v. haber, 4","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"La misma inmovilidad en singular del verbo conjugado debe producirse en el caso de que haber forme parte de una perífrasis con poder, soler, deber, ir a, etc."}]},{"text":"La perífrasis «haber que + infinitivo» significa ser necesario o conveniente y también es impersonal: solo se conjuga en tercera persona del singular. Por eso, si el infinitivo es pronominal, no puede llevar el pronombre de primera persona del plural: «Todavía hay que esforzarse mucho más», no «hay que esforzarnos». Tampoco debe usarse «habemos» como auxiliar del perfecto (lo correcto es «hemos»).","refs":[{"ref":"DPD, s. v. haber, 3b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Al ser impersonal, se conjuga solo en tercera persona del singular; por ello, si el verbo que le sigue es pronominal, no es correcto el uso del pronombre de primera persona del plural"},{"ref":"DPD, s. v. haber, 3","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No debe usarse la forma arcaica habemos para formar la primera persona del plural del pretérito perfecto compuesto de indicativo"}]}]},{"n":"6","title":"El verbo hacer: imperativo, uso impersonal y «hacer público»","blocks":[{"text":"El imperativo de hacer para tú es haz (y hacé para vos), nunca «hace»: «Haz tú la cama». Con expresiones de tiempo y meteorológicas, hacer es impersonal y va siempre en tercera persona del singular, aunque el complemento sea plural. Además, es redundante añadir «atrás» a hacer con complemento temporal: se dice «hace dos años» o «dos años atrás», pero no «hace dos años atrás».","refs":[{"ref":"DPD, s. v. hacer, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"El imperativo singular es haz (tú) y hacé (vos), y no ⊗hace."},{"ref":"DPD, s. v. hacer, 2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es redundante, y debe evitarse, el uso del adverbio atrás cuando hacer se construye con un complemento temporal"}]},{"text":"En la construcción «hacer público» (dar a conocer), el adjetivo público concuerda en género y número con el complemento directo, por lo que no es invariable: «El ministerio hizo públicos los nombramientos», «hizo pública la lista».","refs":[{"ref":"DPD, s. v. hacer, 9","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"el adjetivo público debe concordar en género y número con el sustantivo al que se refiere, esto es, con el complemento directo del verbo hacer"},{"ref":"DPD, s. v. hacer, 9","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No es correcto considerar público como adjetivo invariable en esta construcción"}]},{"text":"Resumen práctico para el impersonal: igual que con haber, cuando hacer indica tiempo transcurrido o fenómenos meteorológicos, no tiene sujeto y por eso no puede concordar en plural con el complemento. Es incorrecto «hacen ya tres años que ingresó» y lo correcto es «hace ya tres años». Si una frase del examen pone el verbo en plural junto a una expresión de tiempo o de temperatura, sospecha.","refs":[{"ref":"DPD, s. v. hacer, 2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"En todos estos casos, es impropio hacer concordar el verbo hacer en plural cuando es plural el complemento"}]}]},{"n":"7","title":"Verbos irregulares: ir, andar, conducir, satisfacer y errar","blocks":[{"text":"Ir tiene como imperativos ve (tú) e id (vosotros), y para el uso pronominal vete e idos; iros se admite hoy también. Hay que evitar la forma arcaica «íos» y la vulgar «ves» («Ves al cuarto de baño» es incorrecto: «Ve al cuarto de baño»). Su gerundio es yendo. Andar solo admite en el pretérito perfecto simple y el subjuntivo la raíz anduv-: anduve, anduviera; «andé» o «andara» son incorrectas.","refs":[{"ref":"DPD, s. v. ir, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Las formas de imperativo propias del tuteo son ve (tú) e id (vosotros)"},{"ref":"DPD, s. v. ir, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"En cambio, debe evitarse el uso de la forma arcaica ⊗íos y, para el imperativo singular, de la forma vulgar ⊗ves"},{"ref":"DPD, s. v. andar, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"no se consideran correctas las formas de estos tiempos con la raíz regular and-: ⊗andé, ⊗andaste"}]},{"text":"Los verbos en -ducir (conducir, traducir, producir) hacen el pretérito en -duje: conduje, condujo, condujera; «conducí» o «condució» son incorrectas. Satisfacer se conjuga como hacer: satisfice, satisficiera, satisfaré; «satisfaciera» es incorrecta. Su único rasgo propio es que en el imperativo vale satisfaz y satisface. Errar solo toma ye- cuando la raíz es tónica (yerro, yerras); con el acento en la desinencia, la forma correcta es erramos, no «yerramos».","refs":[{"ref":"DPD, s. v. conducir, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗conducí, ⊗conduciste, ⊗condució, etc., en lugar de conduje, condujiste, condujo, etc."},{"ref":"DPD, s. v. satisfacer, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"usando formas como ⊗satisfací, ⊗satisfaciera, ⊗satisfaceré, ⊗satisfacería, etc., en lugar de satisfice, satisficiera, satisfaré, satisfaría, etc."},{"ref":"DPD, s. v. errar, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Son, pues, incorrectas las formas con ye- cuando el acento de intensidad recae en la desinencia verbal y no en la raíz: ⊗yerramos, ⊗yerráis, ⊗yerraba, etc."}]}]},{"n":"8","title":"Las perífrasis deber + infinitivo y deber de + infinitivo","blocks":[{"text":"Deber es un verbo regular: son vulgares las formas sincopadas «debrá» o «debría». Como auxiliar forma dos perífrasis. «Deber + infinitivo» expresa preferentemente obligación («Debemos prepararnos»), aunque en la lengua culta también se usa para la probabilidad. «Deber de + infinitivo» expresa normalmente probabilidad o suposición («Debe de tener unos sesenta años»), aunque con menor frecuencia también se usa para la obligación.","refs":[{"ref":"DPD, s. v. deber, 2a","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"a) deber + infinitivo. Denota preferentemente obligación"},{"ref":"DPD, s. v. deber, 2b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"b) deber de + infinitivo. Denota normalmente probabilidad o suposición"},{"ref":"DPD, s. v. deber, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"no son correctas las formas sincopadas del futuro y del condicional simple, ⊗debrá, ⊗debría"}]},{"text":"En el examen, las dos perífrasis son correctas y no suelen marcarse como error por sí mismas; lo que se pregunta es su valor: si el enunciado pide la que «denota normalmente probabilidad o suposición», la respuesta es deber de + infinitivo. En cambio, sí es error morfológico escribir las formas sincopadas debrá o debría en lugar de deberá o debería.","refs":[{"ref":"DPD, s. v. deber, 2b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No obstante, aunque con frecuencia mucho menor, también se usa en la lengua culta para expresar obligación"}]}]},{"n":"9","title":"Adverbios y conjunciones: detrás, sino y si no","blocks":[{"text":"Detrás es un adverbio, y por eso no debe combinarse con posesivos: se dice «detrás de mí», «detrás de él», no «detrás mío» ni «detrás suya». La conjunción adversativa sino introduce el elemento que sustituye al negado («No me refiero al trabajo, sino a tu vida»); cuando se contraponen oraciones con verbo en forma personal, debe ir seguida de que: «No compraba la droga, sino que la vendía». No hay que confundirla con si no (condicional + negación): «si no lo hace usted».","refs":[{"ref":"DPD, s. v. detrás, 2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Por su condición de adverbio, se desaconseja en el habla culta su uso con posesivos: ⊗detrás mío, ⊗detrás suya, etc. (en lugar de detrás de mí, detrás de él/ella, etc.)."},{"ref":"DPD, s. v. sino, 2.1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"En la lengua actual, cuando lo que se contrapone son oraciones con el verbo en forma personal, sino debe ir seguido de que"},{"ref":"DPD, s. v. sino, 3","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No debe confundirse la conjunción adversativa sino antes descrita con si no"}]}]},{"n":"10","title":"Determinantes y locuciones: sendos, cuyo, con base en, a nivel de, más mayor","blocks":[{"text":"Sendos es un distributivo que va siempre delante de un sustantivo plural y significa «uno para cada uno» de los mencionados: «Los dos agentes recibieron sendas medallas» (una cada uno). No debe usarse como sinónimo de dos o ambos. Cuyo es un determinante relativo posesivo, sin tilde, con antecedente explícito (el poseedor); se antepone al sustantivo que expresa lo poseído y concuerda con este en género y número: «el agente cuyas pruebas…».","refs":[{"ref":"DPD, s. v. sendos, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Cuantificador distributivo que funciona como determinante antecediendo siempre a un sustantivo plural y significa ''uno (a o para) cada una de las personas o cosas que se mencionan''."},{"ref":"DPD, s. v. sendos, 2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No debe emplearse como equivalente de dos o ambos"},{"ref":"DPD, s. v. cuyo, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"se antepone al sustantivo que denota lo poseído, con el que concuerda en género y número"}]},{"text":"La locución correcta es «con base en»; «con base a» no se considera correcta, y «en base a» se admite aunque es menos recomendable. «A nivel de» solo es correcto si conserva la idea de altura o de categoría, no con el sentido de «con respecto a» o «en el ámbito de». Y «más mayor que» es desaconsejable cuando el segundo término está expreso: basta con «mayor que ella».","refs":[{"ref":"DPD, s. v. base, 5","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"No se considera correcta, en cambio, la variante ⊗con base a."},{"ref":"DPD, s. v. nivel, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Ambas construcciones son admisibles siempre que en ellas la palabra nivel conserve de algún modo la noción de ''altura'' o de ''categoría u orden jerárquico''"},{"ref":"DPD, s. v. mayor, 2.2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"resulta superflua y, por tanto, desaconsejable"}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Dequeísmo: «de que» sobrante (pienso de que, me alegra de que, es posible de que, a medida de que). Prueba: sustituir por «eso».","refs":[{"ref":"DPD, s. v. dequeísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Es el uso indebido de la preposición de delante de la conjunción que"}]},{"text":"Queísmo: falta la preposición (me olvidé que, a pesar que, nos dimos cuenta que).","refs":[{"ref":"DPD, s. v. queísmo, 1f","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Nos dimos cuenta de que era tarde (no ⊗Nos dimos cuenta que era tarde)."}]},{"text":"Laísmo: «la dio un beso»; loísmo: lo(s) como complemento indirecto; leísmo de cosa, siempre incorrecto.","refs":[{"ref":"DPD, s. v. laísmo","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"de La besó y Le dio un beso, a ⊗La dio un beso."}]},{"text":"Haber existencial, siempre en singular: había problemas, va a haber cambios, hay que esforzarse.","refs":[{"ref":"DPD, s. v. haber, 4","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"«Va a haber muchos cambios»"}]},{"text":"Imperativos: haz, ve, id; nunca «hace», «ves» ni «íos». Hacer públicos los nombramientos.","refs":[{"ref":"DPD, s. v. hacer, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"El imperativo singular es haz (tú) y hacé (vos), y no ⊗hace."}]},{"text":"Pretéritos: anduve, condujo, satisfice; erramos (no yerramos).","refs":[{"ref":"DPD, s. v. andar, 1","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Las formas con la raíz irregular anduv- del pretérito perfecto simple"}]},{"text":"Deber de + infinitivo = probabilidad; deber + infinitivo = obligación.","refs":[{"ref":"DPD, s. v. deber, 2b","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"Denota normalmente probabilidad o suposición"}]},{"text":"Detrás de mí (no detrás mío); sino que + verbo; sendos no es «ambos»; con base en, no con base a.","refs":[{"ref":"DPD, s. v. detrás, 2","law":"RAE-ASALE, Diccionario panhispánico de dudas","url":"https://www.rae.es/dpd/","quote":"⊗detrás mío, ⊗detrás suya"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.rae.es/dpd/'), 'https://www.rae.es/dpd/', null, null, null, 'Otras normas citadas: Convocatoria Guardia Civil 2026 (BOE-A-2026-9982) (https://www.boe.es/diario_boe/txt.php?id=BOE-A-2026-9982)'
  from public.topics t where t.slug = 'gcl-25b-gramatica'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where (t.slug like 'gc-%' or t.slug like 'gcl-%') and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'guardia-civil-cabos-guardias',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el proyecto (10/11/2026: apuntes completos por tema)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Guardia Civil: % fichas con apuntes publicadas', v_n;
end $$;

commit;
